warnings.filterwarnings("ignore")

FRED_BASE      = "https://api.stlouisfed.org/fred/series/observations"
COINGECKO_BASE = "https://api.coingecko.com/api/v3"
ALT_ME_BASE    = "https://api.alternative.me/fng/"


# ─────────────────────────────────────────────────────────────────────────────
# Grid + forward-fill helpers
# ─────────────────────────────────────────────────────────────────────────────

def _make_4h_index(start: str, end: str) -> pd.DatetimeIndex:
    return pd.date_range(start=start, end=end, freq="4h", tz="UTC")


def _to_utc(index: pd.DatetimeIndex) -> pd.DatetimeIndex:
    if index.tz is None:
        return index.tz_localize("UTC")
    return index.tz_convert("UTC")


def _ffill_to_grid(series: pd.Series, grid: pd.DatetimeIndex) -> pd.Series:
    """
    Reindex an irregular / daily series onto a 4h UTC grid using forward-fill.
    No future leakage: values only propagate forward in time.
    """
    series = series.copy()
    series.index = _to_utc(series.index)
    combined = series.reindex(series.index.union(grid)).sort_index().ffill()
    return combined.reindex(grid)


def _pct_change_bars(series: pd.Series, bars: int) -> pd.Series:
    """Percentage change over `bars` 4h bars (bars=6 -> 24h)."""
    return series.pct_change(bars)


def _rolling_std(series: pd.Series, bars: int) -> pd.Series:
    return series.rolling(bars).std()


# ─────────────────────────────────────────────────────────────────────────────
# FRED fetcher
# ─────────────────────────────────────────────────────────────────────────────

def _fetch_fred(
    series_id: str,
    start: str,
    end: str,
    api_key: str,
    col_name: str,
    grid: pd.DatetimeIndex,
) -> pd.Series:
    params = {
        "series_id":          series_id,
        "observation_start":  start,
        "observation_end":    end,
        "api_key":            api_key,
        "file_type":          "json",
        "frequency":          "d",
        "aggregation_method": "last",
    }
    try:
        r = requests.get(FRED_BASE, params=params, timeout=15)
        r.raise_for_status()
        obs   = r.json()["observations"]
        dates = pd.to_datetime([o["date"] for o in obs], utc=True)
        vals  = [float(o["value"]) if o["value"] != "." else np.nan for o in obs]
        s     = pd.Series(vals, index=dates, name=col_name).ffill()
        return _ffill_to_grid(s, grid)
    except Exception as e:
        print(f"  [FRED] {series_id} failed: {e}")
        return pd.Series(np.nan, index=grid, name=col_name)


# ─────────────────────────────────────────────────────────────────────────────
# yfinance fetcher
# ─────────────────────────────────────────────────────────────────────────────

def _fetch_yf(
    ticker: str,
    col_name: str,
    start: str,
    end: str,
    grid: pd.DatetimeIndex,
    field: str = "Close",
) -> pd.Series:
    try:
        raw = yf.download(ticker, start=start, end=end, progress=False, auto_adjust=True)[field]
        if isinstance(raw, pd.DataFrame):      # multi-ticker edge case
            raw = raw.iloc[:, 0]
        raw.index = pd.to_datetime(raw.index, utc=True)
        raw.name  = col_name
        return _ffill_to_grid(raw, grid)
    except Exception as e:
        print(f"  [yfinance] {ticker} failed: {e}")
        return pd.Series(np.nan, index=grid, name=col_name)


# ─────────────────────────────────────────────────────────────────────────────
# Alternative.me — Crypto Fear & Greed
# ─────────────────────────────────────────────────────────────────────────────

def _fetch_fear_greed(
    start: str,
    end: str,
    grid: pd.DatetimeIndex,
) -> pd.Series:
    """
    Crypto Fear & Greed Index from alternative.me.
    No API key required. Returns daily values 0-100.

    NOTE: do NOT pass date_format param — the default response returns
    unix timestamps as strings, which we parse explicitly below.
    With date_format=us the API returns "MM/DD/YYYY" strings which
    pd.to_datetime(..., unit="s") misinterprets, causing all-NaN.
    """
    try:
        n_days = (pd.Timestamp(end) - pd.Timestamp(start)).days + 5
        r = requests.get(
            ALT_ME_BASE,
            params={"limit": n_days},   # no date_format — get raw unix timestamps
            timeout=15,
        )
        r.raise_for_status()
        data = r.json()["data"]
        # API returns timestamp as a string of unix seconds e.g. "1672531200"
        dates = pd.to_datetime(
            [int(d["timestamp"]) for d in data], unit="s", utc=True
        ).normalize()
        vals  = [float(d["value"]) for d in data]
        s = pd.Series(vals, index=dates, name="fear_greed").sort_index()
        s = s[~s.index.duplicated(keep="last")]
        # filter to requested date range
        s = s.loc[s.index >= pd.Timestamp(start, tz="UTC")]
        return _ffill_to_grid(s, grid)
    except Exception as e:
        print(f"  [Fear&Greed] failed: {e}")
        return pd.Series(np.nan, index=grid, name="fear_greed")


# ─────────────────────────────────────────────────────────────────────────────
# CoinGecko — BTC dominance
# ─────────────────────────────────────────────────────────────────────────────

def _fetch_btc_dominance(
    start: str,
    end: str,
    grid: pd.DatetimeIndex,
) -> pd.Series:
    """
    BTC dominance % — tries 3 sources in order, returns first that works.

    Source 1: CoinPaprika  /v1/tickers/btc-bitcoin/historical
              Free, no key, returns daily data up to 5y. Direct dominance %
              is not in the endpoint but market_cap is — we divide by total
              from /v1/global endpoint (daily snapshot, so we fetch once per
              day in a loop — expensive for long windows, skip for >365d).
              Better: CoinPaprika /v1/coins/btc-bitcoin/ohlcv/historical
              gives OHLCV but not market cap. Use global stats instead.

    Source 2: CoinGecko /coins/bitcoin/market_chart — chunked into <=365d
              segments to stay on free-tier daily granularity (no interval
              param which requires paid plan since 2024).

    Source 3: Computed from yfinance — fetch BTC-USD and a basket of top
              altcoins, sum market caps as proxy for total crypto market cap.
              Rough but never fails, no API limits.
    """
    name = "btc_dominance_pct"

    # ── Source 1: CoinPaprika ─────────────────────────────────────────────────
    def _from_coinpaprika() -> pd.Series:
        """
        CoinPaprika /v1/tickers/btc-bitcoin/historical returns market_cap
        per day. /v1/global returns current total market cap only — not
        historical. So we use /v1/tickers?quotes=USD which lists all coins
        with market_cap at the current snapshot.

        For *historical* total market cap, CoinPaprika exposes it via:
          GET /v1/global  →  current only
          GET /v1/tickers/{coin_id}/historical?start=&end=&interval=1d
              →  historical OHLCV + market_cap for a single coin  ✓

        Strategy: fetch BTC historical market_cap, fetch ETH historical
        market_cap as the second-largest, and use the ratio
        btc / (btc + eth + ...) — but total cap requires all coins.

        Simpler: CoinPaprika exposes total market cap history via:
          GET https://api.coinpaprika.com/v1/coins/btc-bitcoin/markets
          → not what we want

        Actually use the undocumented but stable endpoint:
          GET https://api.coinpaprika.com/v1/global
          which has market_cap_usd and bitcoin_dominance_percentage TODAY,
          and the ticker history endpoint for time series.

        Best free CoinPaprika approach: use the /tickers historical for BTC
        market cap, and for total use the sum of top-10 tickers history.
        But that's 10 calls. Instead, note that CoinPaprika's
        /v1/tickers/btc-bitcoin/historical returns `market_cap` and the
        global endpoint has `bitcoin_dominance_percentage` — but only for
        today. There's no free historical global endpoint.

        → Fall through to source 2.
        """
        raise NotImplementedError("CoinPaprika has no free historical global market cap endpoint")

    # ── Source 2: CoinGecko chunked (no interval param) ──────────────────────
    def _from_coingecko() -> pd.Series:
        def _caps_to_daily(caps: list, col: str) -> pd.Series:
            df       = pd.DataFrame(caps, columns=["ts", "val"])
            df["dt"] = pd.to_datetime(df["ts"], unit="ms", utc=True).dt.normalize()
            return df.groupby("dt")["val"].last().rename(col)

        def _fetch_chunk(n_days: int) -> tuple[pd.Series, pd.Series]:
            r_btc = requests.get(
                f"{COINGECKO_BASE}/coins/bitcoin/market_chart",
                params={"vs_currency": "usd", "days": n_days},
                timeout=30,
            )
            r_btc.raise_for_status()
            btc_caps = r_btc.json().get("market_caps", [])
            time.sleep(3.0)

            r_tot = requests.get(
                f"{COINGECKO_BASE}/global/market_cap_chart",
                params={"vs_currency": "usd", "days": n_days},
                timeout=30,
            )
            r_tot.raise_for_status()
            payload    = r_tot.json()
            total_caps = payload.get("market_cap_chart", payload).get("market_cap", [])
            time.sleep(3.0)

            if not btc_caps or not total_caps:
                raise ValueError(f"empty: btc={len(btc_caps)} total={len(total_caps)}")

            return _caps_to_daily(btc_caps, "btc"), _caps_to_daily(total_caps, "total")

        total_days = (pd.Timestamp(end) - pd.Timestamp(start)).days + 1

        if total_days <= 365:
            btc_s, tot_s = _fetch_chunk(total_days)
        else:
            btc_parts, tot_parts = [], []
            seg_end = pd.Timestamp(end, tz="UTC")
            t_start = pd.Timestamp(start, tz="UTC")
            while seg_end > t_start:
                seg_start = max(seg_end - pd.Timedelta(days=364), t_start)
                days      = (seg_end - seg_start).days + 1
                b, t      = _fetch_chunk(days)
                b = b.loc[(b.index >= seg_start) & (b.index <= seg_end)]
                t = t.loc[(t.index >= seg_start) & (t.index <= seg_end)]
                btc_parts.append(b)
                tot_parts.append(t)
                seg_end = seg_start - pd.Timedelta(days=1)
            btc_s = pd.concat(btc_parts).sort_index()
            tot_s = pd.concat(tot_parts).sort_index()
            btc_s = btc_s[~btc_s.index.duplicated(keep="last")]
            tot_s = tot_s[~tot_s.index.duplicated(keep="last")]

        merged    = pd.concat([btc_s, tot_s], axis=1).ffill()
        merged    = merged.loc[
            (merged.index >= pd.Timestamp(start, tz="UTC")) &
            (merged.index <= pd.Timestamp(end,   tz="UTC"))
        ]
        dominance = (merged["btc"] / merged["total"] * 100).rename(name)
        if dominance.dropna().empty:
            raise ValueError("dominance series empty after date filter")
        return dominance

    # ── Source 3: yfinance proxy ──────────────────────────────────────────────
    def _from_yfinance() -> pd.Series:
        """
        Approximate dominance = BTC market cap / sum of top-coin market caps.
        Uses BTC-USD + a basket of large caps from yfinance.
        Market cap = Close price × circulating supply.  Since yfinance doesn't
        expose supply history, we use a fixed supply snapshot (conservative,
        accurate to ~2–3%) which is good enough for a regime feature.

        Fixed supplies (approximate circulating as of 2024):
            BTC  :  19.7M
            ETH  :  120M
            BNB  :  145M
            SOL  :  460M
            XRP  : 57.0B
            ADA  :  35.7B
            AVAX :  410M
            DOT  :  1.4B
            MATIC:  9.9B
            LINK :  587M
        This covers ~65–70% of total crypto market cap on average, so we
        scale the denominator by 1/0.68 to approximate the full market.
        """
        supplies = {
            "BTC-USD":   19_700_000,
            "ETH-USD":  120_000_000,
            "BNB-USD":  145_000_000,
            "SOL-USD":  460_000_000,
            "XRP-USD": 57_000_000_000,
            "ADA-USD": 35_700_000_000,
            "AVAX-USD":  410_000_000,
            "DOT-USD":  1_400_000_000,
            "MATIC-USD":9_900_000_000,
            "LINK-USD":  587_000_000,
        }
        tickers  = list(supplies.keys())
        prices   = yf.download(tickers, start=start, end=end,
                               progress=False, auto_adjust=True)["Close"]
        prices.index = pd.to_datetime(prices.index, utc=True)

        basket_coverage = 0.68   # these coins ≈ 68% of total market cap

        btc_cap   = prices["BTC-USD"] * supplies["BTC-USD"]
        total_cap = sum(prices[t] * supplies[t] for t in tickers) / basket_coverage

        dominance = (btc_cap / total_cap * 100).rename(name)
        if dominance.dropna().empty:
            raise ValueError("yfinance dominance proxy empty")
        return dominance

    # ── Try sources in order ──────────────────────────────────────────────────
    for source_name, source_fn in [
        ("CoinGecko (chunked)", _from_coingecko),
        ("yfinance proxy",      _from_yfinance),
    ]:
        try:
            print(f"  [BTC dom] trying {source_name}...")
            s = source_fn()
            print(f"  [BTC dom] {source_name} OK — {s.dropna().shape[0]} daily points")
            return _ffill_to_grid(s, grid)
        except Exception as e:
            print(f"  [BTC dom] {source_name} failed: {e}")

    print("  [BTC dom] all sources failed — column will be NaN")
    return pd.Series(np.nan, index=grid, name=name)


# ─────────────────────────────────────────────────────────────────────────────
# Master builder
# ─────────────────────────────────────────────────────────────────────────────

def build_macro_df(
    start: str,
    end: str,
    fred_key: str,
    existing_macro_df: Optional[pd.DataFrame] = None,
) -> pd.DataFrame:
    """
    Build (or extend) macro_df with all available macro / sentiment features.

    Parameters
    ----------
    start, end          : date strings "YYYY-MM-DD"
    fred_key            : FRED API key  (free at fred.stlouisfed.org)
    existing_macro_df   : if you already have a macro_df, pass it here and
                          new columns will be appended (missing columns only).

    Returns
    -------
    pd.DataFrame
        4h UTC index, all columns forward-filled, no future leakage.
        NaN rows at the very start (before first observation) are left as-is;
        handle them in your preprocessing pipeline (ffill/bfill/zero-fill).
    """
    grid    = _make_4h_index(start, end)
    columns = {}

    # ── already-present columns to skip ──────────────────────────────────────
    existing_cols = set(existing_macro_df.columns) if existing_macro_df is not None else set()

    def _need(col: str) -> bool:
        return col not in existing_cols

    # ─────────────────────────────────────────────────────────────────────────
    # VOLATILITY INDICES  (yfinance — no key)
    # ─────────────────────────────────────────────────────────────────────────
    print("[macro] Fetching volatility indices (yfinance)...")

    for ticker, col in [
        ("^VIX",  "vix"),   # S&P 500 implied vol — most important
        ("^GVZ",  "gvz"),   # Gold volatility
        ("^OVX",  "ovx"),   # Crude Oil volatility
        ("^VXN",  "vxn"),   # Nasdaq-100 volatility
    ]:
        if _need(col):
            columns[col] = _fetch_yf(ticker, col, start, end, grid)

    # ─────────────────────────────────────────────────────────────────────────
    # EQUITY & COMMODITIES  (yfinance — no key)
    # ─────────────────────────────────────────────────────────────────────────
    print("[macro] Fetching equity & commodities (yfinance)...")

    for ticker, col in [
        ("^GSPC", "spx"),   # S&P 500 level
        ("GC=F",  "gold"),  # Gold futures
        ("CL=F",  "wti"),   # WTI crude oil
    ]:
        if _need(col):
            columns[col] = _fetch_yf(ticker, col, start, end, grid)
            time.sleep(1)

    # ─────────────────────────────────────────────────────────────────────────
    # FRED MACRO RATES  (one call per series, ~0.3s each)
    # ─────────────────────────────────────────────────────────────────────────
    print("[macro] Fetching FRED macro rates...")

    fred_series = [
        # (fred_series_id,   col_name,        description)
        ("DGS10",            "us10y",          "10Y Treasury yield"),
        ("DGS2",             "us2y",           "2Y Treasury yield"),
        ("DFF",              "fed_funds",      "Effective Fed Funds Rate"),
        ("DFII10",           "tips_10y",       "10Y TIPS yield (real rate)"),
        ("T10YIE",           "breakeven_10y",  "10Y Breakeven Inflation"),
        ("BAMLH0A0HYM2",     "hy_spread",      "HY credit spread OAS"),
        ("BAMLC0A0CM",       "ig_spread",      "IG credit spread OAS"),
        ("DTWEXBGS",         "dxy",            "Broad USD Index"),
    ]

    for fred_id, col, desc in fred_series:
        if _need(col):
            print(f"  -> {desc}")
            columns[col] = _fetch_fred(fred_id, start, end, fred_key, col, grid)
            time.sleep(2)   # FRED is generous but polite calls help

    # ─────────────────────────────────────────────────────────────────────────
    # CRYPTO SENTIMENT  (Alternative.me — no key)
    # ─────────────────────────────────────────────────────────────────────────
    if _need("fear_greed"):
        print("[macro] Fetching Fear & Greed Index (alternative.me)...")
        columns["fear_greed"] = _fetch_fear_greed(start, end, grid)

    # ─────────────────────────────────────────────────────────────────────────
    # BTC DOMINANCE  (CoinGecko — no key)
    # ─────────────────────────────────────────────────────────────────────────
    if _need("btc_dominance_pct"):
        print("[macro] Fetching BTC dominance (CoinGecko)...")
        columns["btc_dominance_pct"] = _fetch_btc_dominance(start, end, grid)

    # ─────────────────────────────────────────────────────────────────────────
    # DERIVED FEATURES
    # All computed after raw fetches so they work whether the raw col came
    # from this run or from existing_macro_df.
    # ─────────────────────────────────────────────────────────────────────────
    print("[macro] Computing derived features...")

    # Merge raw fetched columns into a working frame
    raw_df = pd.DataFrame(columns, index=grid)
    if existing_macro_df is not None:
        # align index, prefer existing values for duplicate cols
        existing_reindexed = existing_macro_df.reindex(grid).ffill()
        for col in existing_reindexed.columns:
            if col not in raw_df.columns:
                raw_df[col] = existing_reindexed[col]

    def _get(col: str) -> pd.Series:
        """Safe column getter — returns NaN series if column missing."""
        if col in raw_df.columns:
            return raw_df[col]
        return pd.Series(np.nan, index=grid)

    derived = {}

    # Yield curve slope: 10Y - 2Y  (negative = recession signal)
    if _need("yield_curve_slope"):
        derived["yield_curve_slope"] = _get("us10y") - _get("us2y")

    # Real rate proxy: 10Y nominal - 10Y TIPS
    if _need("real_rate"):
        derived["real_rate"] = _get("us10y") - _get("tips_10y")

    # 24h pct changes (6 bars = 24h on a 4h grid)
    for col, base in [
        ("vix_1d_chg",          "vix"),
        ("dxy_1d_chg",          "dxy"),
        ("us10y_1d_chg",        "us10y"),
        ("gold_1d_chg",         "gold"),
        ("wti_1d_chg",          "wti"),
        ("fear_greed_chg_1d",   "fear_greed"),
        ("btc_dominance_chg",   "btc_dominance_pct"),
    ]:
        if _need(col):
            derived[col] = _pct_change_bars(_get(base), bars=6)

    # SPX daily return and short-term vol
    if _need("spx_ret_1d"):
        derived["spx_ret_1d"] = _pct_change_bars(_get("spx"), bars=6)
    if _need("spx_vol_7d"):
        derived["spx_vol_7d"] = _rolling_std(_pct_change_bars(_get("spx"), 1), bars=42)

    # Risk-off composite: DXY / Gold — rises in flight-to-dollar, falls in flight-to-gold
    if _need("dxy_gold_ratio"):
        derived["dxy_gold_ratio"] = _get("dxy") / (_get("gold") + 1e-8)

    # Credit stress composite: average of HY and IG spreads, z-scored over 30d
    if _need("credit_stress"):
        raw_stress = (_get("hy_spread") + _get("ig_spread")) / 2.0
        roll_mean  = raw_stress.rolling(180).mean()   # 30d on 4h bars
        roll_std   = raw_stress.rolling(180).std()
        derived["credit_stress"] = (raw_stress - roll_mean) / (roll_std + 1e-8)

    # VIX term structure proxy: VXN / VIX  (>1 = tech stress > broad stress)
    if _need("vxn_vix_ratio"):
        derived["vxn_vix_ratio"] = _get("vxn") / (_get("vix") + 1e-8)

    # Fear & Greed regime bucket: extreme_fear=0 fear=1 neutral=2 greed=3 extreme_greed=4
    if _need("fg_regime"):
        fg = _get("fear_greed")
        derived["fg_regime"] = pd.cut(
            fg,
            bins=[-1, 25, 45, 55, 75, 101],
            labels=[0, 1, 2, 3, 4],
        ).astype(float)

    # ─────────────────────────────────────────────────────────────────────────
    # Assemble final DataFrame
    # ─────────────────────────────────────────────────────────────────────────
    derived_df = pd.DataFrame(derived, index=grid)
    macro_df   = pd.concat([raw_df, derived_df], axis=1)

    # drop SPX level (used only for derivatives, not a regime feature itself)
    macro_df = macro_df.drop(columns=["spx"], errors="ignore")

    # final forward-fill pass to catch any gaps in derived cols
    macro_df = macro_df.ffill()

    # ─────────────────────────────────────────────────────────────────────────
    # Sanity report
    # ─────────────────────────────────────────────────────────────────────────
    nan_rate = macro_df.isna().mean().sort_values(ascending=False)
    high_nan = nan_rate[nan_rate > 0.05]
    if not high_nan.empty:
        print(f"\n[macro] WARNING — columns with >5% NaN:\n{high_nan.to_string()}")

    print(f"\n[macro] Done. Shape: {macro_df.shape}")
    print(f"[macro] Columns ({len(macro_df.columns)}):")
    for col in macro_df.columns:
        nn = macro_df[col].isna().mean()
        print(f"  {col:35s}  NaN={nn:.1%}")

    return macro_df

