class SoftRank(layers.Layer):
    def __init__(self, tau=0.1, **kwargs):
        super().__init__(**kwargs)
        self.tau = tau

    def call(self, x):
        """
        x: [batch, n_assets]
        returns: [batch, n_assets] soft ranks in [0,1]
        """
        # [batch, n_assets, 1]
        x_i = ops.expand_dims(x, axis=2)
        # [batch, 1, n_assets]
        x_j = ops.expand_dims(x, axis=1)

        # pairwise differences
        diff = x_i - x_j  # [batch, n_assets, n_assets]

        # soft indicator
        P = ops.sigmoid(diff / self.tau)  # [batch, n_assets, n_assets]

        # soft rank = mean across comparisons
        r = ops.mean(P, axis=2)  # [batch, n_assets]

        return r

    def compute_output_shape(self, input_shape):
        # input_shape: (batch, n_assets)
        return input_shape

    def get_config(self):
        config = super().get_config()
        config.update({"tau": self.tau})
        return config



def get_binance_k_lines(ticker, interval, value, myclient, n_records=0, end_time=None):

    all_data = {}

    if n_records == 0:
        n_records = 1000

    if end_time == None:
        k_values = myclient.klines(ticker, interval=interval, limit=n_records)
    else:
        k_values = myclient.klines(ticker, interval=interval, endTime=int(end_time*1000), limit=n_records)

    all_data["unix"] = []
    all_data[value + "_open"] = []
    all_data[value + '_high'] = []
    all_data[value + '_low'] = []
    all_data[value + '_close'] = []
    all_data[value + '_volume'] = []

    for i, value_series in enumerate(k_values):
        if i >= n_records:
            break

        if n_records > 1:
            all_data["unix"].append(value_series[0])
            all_data[value + "_open"].append(value_series[1])
            all_data[value + '_high'].append(value_series[2])
            all_data[value + '_low'].append(value_series[3])
            all_data[value + '_close'].append(value_series[4])
            all_data[value + '_volume'].append(value_series[5])
        elif n_records == 1:
            all_data["unix"] = value_series[0]
            all_data[value + "_open"] = value_series[1]
            all_data[value + '_high'] = value_series[2]
            all_data[value + '_low'] = value_series[3]
            all_data[value + '_close'] = value_series[4]
            all_data[value + '_volume'] = value_series[5]
    return all_data


def remove_ticker_not_in_binance(my_list, interval='1m', n_records=0, end_time=None):

    all_candles = {}
    if type(my_list) != list and type(my_list) != dict:
        my_list = [my_list]

    for i, value in enumerate(my_list):

        data = {}

        ticker = value +"USDT"
        # Get klines of BTCUSDT at 1m interval
        try:
            data[value] = get_binance_k_lines(ticker, interval, value, n_records=n_records, end_time=end_time)

        except Exception as err:

            client = Spot(key=BINANCE_API_KEY, secret=BINANCE_SECRET)
            data[value] = get_binance_k_lines(ticker, interval, value, myclient=client, end_time=end_time)
            print(err)

    return data



def return_chain_stats(start_date=None, end_date=None, training=True, indicators=None, ticker="btc"):

    ticker = ticker.lower()
    api_key = '<api_key>'
    #client = CoinMetricsClient()


    metrics_dfs = []
    step = 5 if len(indicators)>5 else 1
    iter_max = len(indicators) - step if len(indicators)>step else 1
    for i in range(0, iter_max+step, step):
        if i>0:
            time.sleep(5)

        client=None
        asset_metrics = client.get_asset_metrics(
                assets=f'{ticker}',
                metrics=indicators[i:i+step] if i+step<len(indicators)-1 else indicators[i::],
                frequency='1d',
                start_time='2024-01-02T00:00:00Z' if not start_date else start_date,
                end_time='2025-03-01T00:00:00Z' if not end_date else end_date,
                limit_per_asset=4000
            )
        asset_metrics_df = asset_metrics.to_dataframe()
        if len(asset_metrics_df.columns)>2:
            asset_metrics_df = asset_metrics_df.set_index("time").iloc[:, 1:]
            metrics_dfs.append(asset_metrics_df)

    asset_metrics_df = pd.concat(metrics_dfs, axis=1, ignore_index=False)

    if not training:
        asset_metrics_df = asset_metrics_df.tail(1000)

    return asset_metrics_df




def backtest_top_bottom_k(
    pred_scores,
    true_returns,
    k_long=5,
    k_short=5,
    zscore_preds=True,
    normalize_weights=True,
    vol_target=None,
    transaction_cost=0.003,
):
    """
    Cross-sectional long/short backtest using top-K and bottom-K selection.

    Parameters
    ----------
    pred_scores : np.ndarray
        Shape (n_samples, n_assets). Model scores per day per asset.
    true_returns : np.ndarray
        Shape (n_samples, n_assets). Realized next-period returns.
    k_long : int
        Number of assets to long each day.
    k_short : int
        Number of assets to short each day.
    zscore_preds : bool
        If True, z-score predictions cross-sectionally each day.
    normalize_weights : bool
        If True, normalize |weights| to sum to 1 each day.
    vol_target : float or None
        If not None, scale daily PnL to hit this realized volatility.
    transaction_cost : float
        Proportional cost per unit turnover.

    Returns
    -------
    final_cumret : float
    metrics : pd.DataFrame
    weights : np.ndarray
    """

    pred_scores = np.asarray(pred_scores, dtype=float).copy()
    true_returns = np.asarray(true_returns, dtype=float).copy()

    n_samples, n_assets = pred_scores.shape

    # ---------------------------------------------------------
    # 0. Handle NaNs in returns
    # ---------------------------------------------------------
    true_returns = np.nan_to_num(true_returns, nan=0.0)

    # ---------------------------------------------------------
    # 1. Optional z-score
    # ---------------------------------------------------------
    if zscore_preds:
        mean = np.mean(pred_scores, axis=1, keepdims=True)
        std = np.std(pred_scores, axis=1, keepdims=True) + 1e-8
        pred_scores = (pred_scores - mean) / std

    # ---------------------------------------------------------
    # 2. Build weights: top-K long, bottom-K short
    # ---------------------------------------------------------
    weights = np.zeros_like(pred_scores, dtype=np.float32)

    for t in range(n_samples):
        row = pred_scores[t]

        # argsort ascending
        idx_sorted = np.argsort(row)

        # bottom-K = lowest scores
        short_idx = idx_sorted[:k_short]

        # top-K = highest scores
        long_idx = idx_sorted[-k_long:]

        weights[t, long_idx] = 1.0
        weights[t, short_idx] = -1.0

    # ---------------------------------------------------------
    # 3. Normalize weights (constant gross exposure)
    # ---------------------------------------------------------
    if normalize_weights:
        abs_sum = np.sum(np.abs(weights), axis=1, keepdims=True) + 1e-8
        weights = weights / abs_sum

    # ---------------------------------------------------------
    # 4. Turnover + transaction costs
    # ---------------------------------------------------------
    turnover = np.zeros(n_samples)
    if transaction_cost > 0.0:
        w_prev = np.zeros(n_assets, dtype=np.float32)
        for t in range(n_samples):
            turnover[t] = np.sum(np.abs(weights[t] - w_prev))
            w_prev = weights[t]
        cost = turnover * transaction_cost
    else:
        cost = np.zeros(n_samples)

    # ---------------------------------------------------------
    # 5. Daily PnL
    # ---------------------------------------------------------
    daily_pnl = np.sum(weights * true_returns, axis=1) - cost

    # ---------------------------------------------------------
    # 6. Vol targeting
    # ---------------------------------------------------------
    if vol_target is not None:
        realized_vol = np.std(daily_pnl) + 1e-8
        scale = vol_target / realized_vol
        daily_pnl *= scale

    # ---------------------------------------------------------
    # 7. Cumulative return
    # ---------------------------------------------------------
    cumulative_return = np.cumprod(1.0 + daily_pnl) - 1.0

    # ---------------------------------------------------------
    # 8. IC and Rank-IC
    # ---------------------------------------------------------
    def safe_corr(a, b):
        if np.std(a) < 1e-12 or np.std(b) < 1e-12:
            return np.nan
        return np.corrcoef(a, b)[0, 1]

    daily_ic = np.array(
        [safe_corr(pred_scores[t], true_returns[t]) for t in range(n_samples)]
    )

    pred_rank = np.argsort(np.argsort(pred_scores, axis=1), axis=1)
    true_rank = np.argsort(np.argsort(true_returns, axis=1), axis=1)

    daily_rank_ic = np.array(
        [safe_corr(pred_rank[t], true_rank[t]) for t in range(n_samples)]
    )

    # ---------------------------------------------------------
    # 9. Metrics DataFrame
    # ---------------------------------------------------------
    metrics = pd.DataFrame({
        "daily_pnl": daily_pnl,
        "cumulative_return": cumulative_return,
        "turnover": turnover,
        "daily_ic": daily_ic,
        "daily_rank_ic": daily_rank_ic,
    })

    return cumulative_return[-1], metrics, weights



def backtest_weights(weights, returns):
    """
    weights: np.array (T, N)
    returns: np.array (T, N)
    """

    #T = weights.shape[0]

    # 1. portfolio PnL each period (T,)
    pnl = np.sum(weights * returns, axis=1)

    # 2. cumulative return (T,)
    # 3. turnover (T,)
    # turnover[t] = sum(|w[t] - w[t-1]|)
    print("BACKTEST WEIGHTS")
    raw_turnover = np.sum(np.abs(weights[1:] - weights[:-1]), axis=1)
    turnover = raw_turnover * 0.0005
    pnl[1:] = pnl[1:] - turnover

    equity = np.cumprod(1 + pnl)

    print("BACKTEST WEIGHTS 2")

    # 4. summary stats
    sharpe = np.mean(pnl) / (np.std(pnl) + 1e-12) * np.sqrt(365)
    max_dd = np.max(1 - equity / np.maximum.accumulate(equity))

    summary = {
        "mean_pnl": float(np.mean(pnl)),
        "std_pnl": float(np.std(pnl)),
        "sharpe": float(sharpe),
        "max_drawdown": float(max_dd),
        "avg_turnover": float(np.mean(turnover)),
        "final_equity": float(equity[-1]),
    }

    return {
        "pnl": pnl[1:],             # (T,)
        "equity": equity[1:],       # (T,)
        "turnover": turnover,   # (T,)
    }, summary



def prepare_features_from_wide_df2(
    df,
    btc_chain_df,
    macro_df,
    standardisation_type="standard",
    training=True,
    path_suffix="",
    selected_cols=[],
    selected_regime_cols=[],
    selected_macro_cols=[],
    standardisation_type_volume="robust"
):

    # -------------------------------------------------------------------------
    # Paths
    # -------------------------------------------------------------------------
    onchain_scaler_path = path_suffix + f"/scaler_{standardisation_type}_onchain.pkl"
    macro_scaler_path   = path_suffix + f"/scaler_{standardisation_type}_macro.pkl"
    vol_scaler_path     = path_suffix + f"/scaler_{standardisation_type_volume}_vol.pkl"


    # Select regime columns
    # -------------------------------------------------------------------------
    if selected_regime_cols:
        btc_chain_df = btc_chain_df[[c for c in selected_regime_cols if c in btc_chain_df.columns]]

    if selected_macro_cols:
        macro_df = macro_df[[c for c in selected_macro_cols if c in macro_df.columns]]

    chain_cols_to_standardise = ["br_liveliness", "br_difficulty", "br_vaulted_realized_price", "br_realized_loss", "br_realized_profit", "br_nvt"]
    macro_cols_to_standardise = [
        'macro_vix',
        'macro_gvz',
        'macro_ovx',
        'macro_vxn',
        'macro_gold',
        'macro_wti',
        'macro_dxy'
    ]
    # -------------------------------------------------------------------------
    # Copy and align
    # -------------------------------------------------------------------------

    df           = df.copy()
    btc_chain_df = btc_chain_df.copy()
    macro_df     = macro_df.copy()

    btc_chain_df = btc_chain_df.reindex(df.index).ffill().bfill()
    macro_df     = macro_df.reindex(df.index).ffill().bfill()

    df           = df.reset_index(drop=True)
    btc_chain_df = btc_chain_df.reset_index(drop=True)
    macro_df     = macro_df.reset_index(drop=True)

    # -------------------------------------------------------------------------
    # Extract tickers
    # -------------------------------------------------------------------------
    tickers = sorted({col.split("_")[0] for col in selected_cols})

    feature_frames    = []
    label_frames      = []
    mkt_label_frames  = []   # raw r1 for y_mkt

    # -------------------------------------------------------------------------
    # Helper functions (De Prado features)
    # -------------------------------------------------------------------------
    def rolling_ols_slope(series, window):
        idx = np.arange(window)
        def _slope(x):
            y = x.values
            cov = np.cov(idx, y)[0, 1]
            var = np.var(idx)
            return cov / (var + 1e-8)
        return series.rolling(window).apply(_slope, raw=False)

    def cusum_binary(series, threshold):
        """
        CUSUM shock detector.

        `threshold` can be a scalar or an array-like the same length as
        `series` (e.g. a rolling/expanding std computed causally). This is
        an inherently sequential/path-dependent recurrence (the running sums
        reset conditionally based on prior state), so it cannot be fully
        vectorised with numpy ufuncs -- but we drop the pandas Series
        overhead per step and operate purely on numpy arrays, which is the
        dominant cost in the original implementation.
        """
        vals = np.asarray(series.values, dtype=np.float64)
        n = len(vals)

        if np.isscalar(threshold):
            thr = np.full(n, float(threshold))
        else:
            thr = np.asarray(threshold, dtype=np.float64)
            if len(thr) != n:
                raise ValueError("threshold array must match series length")

        out = np.zeros(n, dtype=np.float64)
        diffs = np.diff(vals)  # vectorised: diff[i] = vals[i+1] - vals[i]

        s_pos = 0.0
        s_neg = 0.0
        for i in range(1, n):
            diff = diffs[i - 1]
            s_pos = max(0.0, s_pos + diff)
            s_neg = min(0.0, s_neg + diff)

            t = thr[i]
            if not np.isnan(t) and (s_pos > t or s_neg < -t):
                out[i] = 1.0
                s_pos = 0.0
                s_neg = 0.0

        return pd.Series(out, index=series.index)

    def dc_log(series, threshold, window):
        """
        Directional-change event counter.

        Same caveat as cusum_binary: the "last extreme" state is
        path-dependent, so the event-detection loop can't be removed, but
        `threshold` now accepts a per-timestep array (a causal rolling/
        expanding vol estimate) instead of a single global scalar, and we
        work on raw numpy arrays rather than pandas objects inside the loop.
        The final rolling-sum aggregation is fully vectorised via pandas.
        """
        vals = np.asarray(series.values, dtype=np.float64)
        n = len(vals)

        if np.isscalar(threshold):
            thr = np.full(n, float(threshold))
        else:
            thr = np.asarray(threshold, dtype=np.float64)
            if len(thr) != n:
                raise ValueError("threshold array must match series length")

        last_extreme = vals[0]
        direction = 0
        events = np.zeros(n, dtype=np.float64)

        for i in range(1, n):
            t = thr[i]
            if np.isnan(t):
                continue

            r = np.log(vals[i] / (last_extreme + 1e-8))

            if direction >= 0 and r >= t:
                direction = 1
                last_extreme = vals[i]
                events[i] = 1
            elif direction <= 0 and r <= -t:
                direction = -1
                last_extreme = vals[i]
                events[i] = 1

        return pd.Series(events, index=series.index).rolling(window).sum()

    def permutation_entropy(series, window=120, m=3):
        """
        Rolling permutation entropy.

        The original implementation recomputed `sliding_window_view` +
        `np.unique` from scratch inside every rolling window
        (O(n * window)). Here we:
          1. Compute the ordinal pattern for every length-m subsequence
             ONCE across the whole series (fully vectorised).
          2. Encode each pattern as an integer id (fully vectorised).
          3. Slide a fixed-size histogram over the pattern-id sequence,
             updating counts incrementally (O(1) amortised per step)
             instead of rebuilding the distribution from scratch.
        This turns an O(n * window) routine into O(n).
        """
        x = np.asarray(series.values, dtype=np.float64)
        n = len(x)
        out = np.full(n, np.nan)

        if n < m or window < m:
            return pd.Series(out, index=series.index)

        # Ordinal pattern (argsort) for every overlapping length-m window,
        # computed once for the whole series.
        sub = np.lib.stride_tricks.sliding_window_view(x, m)   # (n-m+1, m)
        order = np.argsort(sub, axis=1)                        # ordinal ranks

        # Encode each permutation as a unique base-m integer id. This is
        # unique per distinct permutation (ids need not be contiguous;
        # counts array is just sized m**m, which is trivial for m=3).
        weights = m ** np.arange(m - 1, -1, -1)
        pattern_ids = (order * weights).sum(axis=1)
        n_pattern_slots = m ** m

        n_patterns_total = len(pattern_ids)          # n - m + 1
        pe_window = window - m + 1                   # patterns per outer window
        if pe_window < 1:
            return pd.Series(out, index=series.index)

        counts = np.zeros(n_pattern_slots, dtype=np.int64)
        for i in range(n_patterns_total):
            counts[pattern_ids[i]] += 1
            drop_i = i - pe_window
            if drop_i >= 0:
                counts[pattern_ids[drop_i]] -= 1

            if i >= pe_window - 1:
                nz = counts[counts > 0]
                p = nz / pe_window
                ent = -np.sum(p * np.log(p + 1e-12))
                # This pattern-window ending at pattern-index i corresponds
                # to the original series index i + m - 1 (matches the
                # alignment of series.rolling(window).apply(...)).
                out[i + m - 1] = ent

        return pd.Series(out, index=series.index)

    def heterogeneous_volatility(ret):
        vol_fast = ret.ewm(span=18).std()
        vol_med  = ret.ewm(span=60).std()
        vol_slow = ret.ewm(span=120).std()
        return 0.4 * vol_fast + 0.3 * vol_med + 0.3 * vol_slow

    # -------------------------------------------------------------------------
    # Per-asset feature + label extraction
    # -------------------------------------------------------------------------
    for t in tickers:
        # ---------------------------------------------------------------------
        # FEATURE GENERATION (corrected, stable, economically meaningful)
        # ---------------------------------------------------------------------

        close  = df[f"{t}_close"]
        high   = df[f"{t}_high"]
        low    = df[f"{t}_low"]
        open_  = df[f"{t}_open"]
        volume = df[f"{t}_volume"]

        feats = pd.DataFrame(index=df.index)

        # -----------------------------
        # 1. RETURNS (stable)
        # -----------------------------
        ret_1d  = close.pct_change(1)
        ret_3d  = close.pct_change(3)
        ret_7d  = close.pct_change(7)
        ret_14d = close.pct_change(14)
        ret_30d = close.pct_change(30)

        feats[f"{t}_ret_1d"]  = ret_1d
        feats[f"{t}_ret_3d"]  = ret_3d
        feats[f"{t}_ret_7d"]  = ret_7d
        feats[f"{t}_ret_14d"] = ret_14d
        feats[f"{t}_ret_30d"] = ret_30d

        # -----------------------------
        # 2. VOLATILITY (stable)
        # -----------------------------
        ret = close.pct_change()

        feats[f"{t}_vol_3d"]  = ret.rolling(3).std()
        feats[f"{t}_vol_7d"]  = ret.rolling(7).std()
        feats[f"{t}_vol_14d"] = ret.rolling(14).std()
        feats[f"{t}_vol_30d"] = ret.rolling(30).std()

        feats[f"{t}_vol_of_vol_7d"]  = feats[f"{t}_vol_7d"].rolling(7).std()
        feats[f"{t}_vol_of_vol_14d"] = feats[f"{t}_vol_14d"].rolling(7).std()

        # Heterogeneous volatility (unchanged)
        vol_fast = ret.ewm(span=18).std()
        vol_med  = ret.ewm(span=60).std()
        vol_slow = ret.ewm(span=120).std()
        feats[f"{t}_hv"] = 0.4 * vol_fast + 0.3 * vol_med + 0.3 * vol_slow

        # -----------------------------
        # 3. TREND (corrected)
        # -----------------------------
        sma10  = close.rolling(10).mean()
        sma50  = close.rolling(50).mean()
        sma200 = close.rolling(200).mean()

        feats[f"{t}_sma_ratio_10_50"]  = sma10 / (sma50 + 1e-8) - 1.0
        feats[f"{t}_sma_ratio_50_200"] = sma50 / (sma200 + 1e-8) - 1.0

        # Proper regime indicator (binary)
        trend_raw = close / (sma200 + 1e-8) - 1.0
        feats[f"{t}_trend_regime"] = np.where(
            trend_raw > 0, 1.0,
            np.where(trend_raw < 0, -1.0, 0.0)
        )

        # MACD histogram (corrected)
        ema12  = close.ewm(span=12).mean()
        ema26  = close.ewm(span=26).mean()
        macd   = ema12 - ema26
        signal = macd.ewm(span=9).mean()
        feats[f"{t}_macd_hist"] = macd - signal

        # -----------------------------
        # 4. CANDLE STRUCTURE (stable)
        # -----------------------------
        body       = (close - open_) / close
        range_raw  = (high - low) / close
        upper_wick = (high - close) / close
        lower_wick = (close - low) / close

        min_range = 1e-4
        safe_range = range_raw.where(range_raw > min_range, np.nan)

        feats[f"{t}_candle_body"]      = body
        feats[f"{t}_candle_range"]     = range_raw
        feats[f"{t}_upper_wick_ratio"] = upper_wick / (safe_range + 1e-8)
        feats[f"{t}_lower_wick_ratio"] = lower_wick / (safe_range + 1e-8)
        feats[f"{t}_body_ratio"]       = body / (safe_range + 1e-8)

        # -----------------------------
        # 5. GAP
        # -----------------------------
        feats[f"{t}_gap"] = open_.pct_change()

        # -----------------------------
        # 6. VOLUME & LIQUIDITY (corrected)
        # -----------------------------
        log_volume = np.log1p(volume)

        feats[f"{t}_vol_change_1d"]  = log_volume.diff(1)
        feats[f"{t}_vol_change_7d"]  = log_volume.diff(7)
        feats[f"{t}_vol_change_30d"] = log_volume.diff(30)

        # Correct dollar volume
        dollar_vol = np.log1p(close * volume)
        feats[f"{t}_dollar_vol"]            = dollar_vol
        feats[f"{t}_dollar_vol_change_7d"]  = dollar_vol.diff(7)
        feats[f"{t}_dollar_vol_change_30d"] = dollar_vol.diff(30)

        # ---- FIX (vpt cumsum) --------------------------------------------
        # The original `(ret_1d * volume).cumsum()` is an unbounded running
        # sum whose value at any given date depends on wherever `df`
        # happened to start. That makes it non-reproducible across calls
        # (e.g. train vs. inference windows, or expanding-window retrains)
        # and it's also not a stationary quantity, which sits awkwardly
        # next to the rest of the (bounded, rolling) feature set. Replaced
        # with a bounded rolling-window VPT: same lookback length regardless
        # of how much history precedes the call, and comparable in scale to
        # the other volume features.
        vpt_incr = ret_1d * volume
        feats[f"{t}_vpt"] = vpt_incr.rolling(30, min_periods=1).sum()
        # --------------------------------------------------------------------

        # Liquidity regime
        vol_30 = log_volume.rolling(30).mean()
        feats[f"{t}_liq_regime"] = log_volume - vol_30

        # -----------------------------
        # 7. RANGE EXPANSION
        # -----------------------------
        feats[f"{t}_range_expansion"] = (high - low) / (close.shift(1) + 1e-8)

        # -----------------------------
        # 8. REGIME FEATURES (corrected)
        # -----------------------------
        feats[f"{t}_vol_regime"] = feats[f"{t}_vol_7d"] / (feats[f"{t}_vol_30d"] + 1e-8)

        # Correct momentum regime
        feats[f"{t}_mom_regime"] = ret_7d - ret_30d

        # -----------------------------
        # 9. INTERACTION FEATURES
        # -----------------------------
        feats[f"{t}_mom_vol_interact"]        = ret_7d * feats[f"{t}_vol_7d"]
        feats[f"{t}_mom_vol_change_interact"] = np.log1p(ret_7d.clip(lower=-0.999)) * feats[f"{t}_vol_change_7d"]
        feats[f"{t}_trend_vol_interact"]      = feats[f"{t}_sma_ratio_10_50"] * feats[f"{t}_vol_7d"]
        feats[f"{t}_vol_range_interact"]      = log_volume + np.log1p(feats[f"{t}_range_expansion"].clip(lower=-0.999))
        feats[f"{t}_body_vol_interact"]       = np.log1p(body.clip(lower=-0.999)) + log_volume

        dvi = np.sign(close - open_) * volume

        feats[f"{t}_dvi"] = dvi

        up_vol   = volume.where(close > open_, 0)
        down_vol = volume.where(close < open_, 0)
        imb = (up_vol - down_vol) / (up_vol + down_vol + 1e-8)
        feats[f"{t}_vol_imbalance"] = imb

        parkinson = (1/(4*np.log(2))) * (np.log(high/low)**2).rolling(20).mean()
        feats[f"{t}_vol_parkinson"] = parkinson

        gk = 0.5*(np.log(high/low)**2) - (2*np.log(2)-1)*(np.log(close/open_)**2)
        feats[f"{t}_vol_gk"] = gk.rolling(20).mean()

        rs = (np.log(high/open_) * np.log(high/close) + np.log(low/open_)  * np.log(low/close))
        feats[f"{t}_vol_rs"] = rs.rolling(20).mean()

        k = 0.34/(1.34 + (19/(ret_1d.rolling(20).std() + 1e-8)))
        yz = k*(np.log(open_/close.shift(1))**2) + \
             (1-k)*(np.log(high/low)**2) + \
             (np.log(close/open_)**2)
        feats[f"{t}_vol_yz"] = yz.rolling(20).mean()

        vol_ma = volume.rolling(30).mean()
        vol_std = volume.rolling(30).std()
        vol_shock = (volume - vol_ma) / (vol_std + 1e-8)
        feats[f"{t}_vol_shock"] = vol_shock

        #liq_stress = volume / ((high - low) + 1e-8)
        #feats[f"{t}_liq_stress"] = liq_stress

        downside = ret.clip(upper=0).rolling(30).std()
        feats[f"{t}_downside_vol"] = downside

        #mom_div = feats[f"{t}_macd_hist"] - feats[f"{t}_sma_ratio_10_50"]
        #feats[f"{t}_mom_div"] = mom_div

        #trend_sign = np.sign(ret_1d)
        #trend_persist = trend_sign.rolling(20).mean()
        #feats[f"{t}_trend_persist"] = trend_persist

        # -----------------------------
        # 10. DE PRADO FEATURES (corrected DC, causal thresholds)
        # -----------------------------
        # Rolling OLS slope unchanged
        for w in [10, 20, 50, 100#, 200
                 ]:
            feats[f"{t}_ts_slope_{w}"] = rolling_ols_slope(close, w)

        # ---- FIX (leaky global threshold) ---------------------------------
        # The original `thr = ret.std() * 0.5` computes std over the ENTIRE
        # frame passed in, so the threshold used at timestep 0 already
        # "knows" about volatility from timesteps far in the future. Replaced
        # with a causal rolling std, shifted by 1 bar so only information
        # strictly prior to the current bar informs the threshold at that
        # bar. min_periods gives a reasonable warm-up; early bars where the
        # threshold is still NaN produce no CUSUM/DC events (rather than
        # using an ill-defined threshold), which is the correct behaviour.
        causal_vol = ret.rolling(252, min_periods=60).std().shift(1)
        thr_arr = (causal_vol * 0.5).to_numpy(dtype=np.float64)
        # ----------------------------------------------------------------------

        feats[f"{t}_dc_count_30"] = dc_log(close, threshold=thr_arr, window=30)
        #feats[f"{t}_dc_count_60"] = dc_log(close, threshold=thr_arr, window=60)

        # Correct permutation entropy (larger windows, now vectorised)
        #feats[f"{t}_perm_entropy_90"]  = permutation_entropy(ret.fillna(0.0), window=90,  m=3)
        feats[f"{t}_perm_entropy_180"] = permutation_entropy(ret.fillna(0.0), window=180, m=3)

        # CUSUM regime (binary shock detector) - same causal threshold
        #feats[f"{t}_cusum_regime"] = cusum_binary(ret.fillna(0.0), threshold=thr_arr)

        feature_frames.append(feats)

        # ---------------------------------------------------------------------
        # RAW FORWARD RETURNS (for vol-scaling + y_mkt)
        # ---------------------------------------------------------------------
        r1_raw  = close.pct_change(1).shift(-1)
        r3_raw  = close.pct_change(3).shift(-3)
        r7_raw  = close.pct_change(7).shift(-7)
        r10_raw = close.pct_change(10).shift(-10)
        r13_raw = close.pct_change(13).shift(-13)
        r17_raw = close.pct_change(17).shift(-17)
        r24_raw = close.pct_change(24).shift(-24)

        # Vol for scaling
        ret_past = close.pct_change(1)
        vol = ret_past.rolling(60).std()

        # Winsorize raw returns before scaling
        for r in [r1_raw, r3_raw, r7_raw, r10_raw, r13_raw, r17_raw, r24_raw]:
            r.clip(
                lower=r.expanding().quantile(0.01),
                upper=r.expanding().quantile(0.99),
                inplace=True
            )

        eps = 1e-8
        r1_vol  = r1_raw  / (vol + eps)
        r3_vol  = r3_raw  / (vol + eps)
        r7_vol  = r7_raw  / (vol + eps)
        r10_vol = r10_raw / (vol + eps)
        r13_vol = r13_raw / (vol + eps)
        r17_vol = r17_raw / (vol + eps)
        r24_vol = r24_raw / (vol + eps)

        # Volatility-scaled label heads
        lab = pd.DataFrame(index=df.index)
        lab[f"{t}_r1"]  = r1_vol
        lab[f"{t}_r3"]  = r3_vol
        lab[f"{t}_r7"]  = r7_vol
        lab[f"{t}_r10"] = r10_vol
        lab[f"{t}_r13"] = r13_vol
        lab[f"{t}_r17"] = r17_vol
        lab[f"{t}_r24"] = r24_vol

        label_frames.append(lab)

        # Raw r1 for market-relative label
        mkt_lab = pd.DataFrame(index=df.index)
        mkt_lab[f"{t}_y_mkt_raw"] = r1_raw
        mkt_label_frames.append(mkt_lab)

    # -------------------------------------------------------------------------
    # Combine features and labels
    # -------------------------------------------------------------------------
    X            = pd.concat(feature_frames, axis=1)
    y            = pd.concat(label_frames, axis=1)
    y_mkt_raw_df = pd.concat(mkt_label_frames, axis=1)

    # -------------------------------------------------------------------------
    # Identify pre-standardisation features (VolDF)
    #
    # ---- FIX (column-routing bug) ------------------------------------------
    # The previous version matched columns via `any(k in c for ...)` substring
    # search on keywords like "_vol". That's a substring test, not a
    # word-boundary test, so it silently swept up unrelated columns that
    # merely CONTAIN "vol" as a substring -- notably every interaction
    # feature (`mom_vol_interact`, `trend_vol_interact`, `vol_range_interact`,
    # `body_vol_interact`, ...) and the traded-volume-change features
    # (`vol_change_1d/7d/30d`), none of which are volatility features. Those
    # columns were then wrongly excluded from `X`, skipped cross-sectional
    # normalisation entirely, scaled with the volume scaler instead of the
    # main feature scaler, and ended up in `Vol_np` (which is NOT reshaped
    # per-asset), silently corrupting/losing structure for those signals.
    #
    # Fixed by matching against an EXPLICIT set of base feature names (the
    # suffix after the "{ticker}_" prefix) rather than substring search.
    # This also removes the redundant keyword entries from before (e.g.
    # "vol_of_vol" and "_vol_regime" were already subsumed by "_vol").
    # -------------------------------------------------------------------------
    pre_std_base_features = {
            "vol_3d", "vol_7d", "vol_14d", "vol_30d",
            "vol_of_vol_7d", "vol_of_vol_14d",
            "hv",
            "dollar_vol", "dollar_vol_change_7d", "dollar_vol_change_30d",
            "vpt",
            "ts_slope_10", "ts_slope_20", "ts_slope_50", "ts_slope_100", "ts_slope_200",
            "dc_count_30",
            "dc_count_60",
            "dvi", "vol_imbalance", "vol_parkinson", "vol_gk", "vol_rs", "vol_yz", "vol_shock", "liq_stress", "downside_vol"
        }
    #pre_std_base_features = {c.split("_", 1)[-1] for c in X.columns if "_vol" in c}


    def base_feature_name(col, ticker):
        # column is always "{ticker}_{base_feature_name}"
        return col[len(ticker) + 1:]

    per_asset_cols = [c for c in X.columns if any(c.startswith(f"{t}_") for t in tickers)]

    pre_std_cols = []
    for c in per_asset_cols:
        t_owner = c.split("_", 1)[0]
        if base_feature_name(c, t_owner) in pre_std_base_features:
            pre_std_cols.append(c)
    post_std_cols = [c for c in per_asset_cols if c not in pre_std_cols]

    #print("Len ASSETS  Cols: ", {c.split("_", 1)[-1] for c in post_std_cols})
    #print("Len VOLUME  Cols: ", {c.split("_", 1)[-1] for c in pre_std_cols})

    VolDF = X[pre_std_cols].copy()
    X     = X[post_std_cols].copy()

    # -------------------------------------------------------------------------
    # Winsorize
    # -------------------------------------------------------------------------
    def winsorize(df, lower=0.02, upper=0.98, window=300):
        for col in df.columns:
            q_low  = df[col].rolling(window).quantile(lower)
            q_high = df[col].rolling(window).quantile(upper)
            df[col] = df[col].where(q_low.isna(), df[col].clip(q_low, q_high))
        return df

    # -------------------------------------------------------------------------
    # Standardise VolDF along time
    # -------------------------------------------------------------------------
    ScalerClassVolume = {
        "standard": StandardScaler,
        "robust":   RobustScaler,
        "minmax":   MinMaxScaler
    }[standardisation_type_volume]

    ScalerClass = {
        "standard": StandardScaler,
        "robust":   RobustScaler,
        "minmax":   MinMaxScaler
    }[standardisation_type]

    X            = winsorize(X)
    VolDF = winsorize(VolDF)
    btc_chain_df = winsorize(btc_chain_df)
    macro_df     = winsorize(macro_df)
    y_mkt_raw_df = winsorize(y_mkt_raw_df)

    # -------------------------------------------------------------------------
    # Cross-sectional normalisation (features only)
    # -------------------------------------------------------------------------
    def cs_standard(row):
        std = row.std()
        return (row - row.mean()) / (std + 1e-8) if std > 1e-12 else row*0.0

    def cs_minmax(row):
        mn, mx = row.min(), row.max()
        return (row - mn) / (mx - mn + 1e-8)

    def cs_robust(row):
        median = np.nanmedian(row)
        q1     = np.nanpercentile(row, 25)
        q3     = np.nanpercentile(row, 75)
        return (row - median) / (q3 - q1 + 1e-8)

    cs_fn = {
        "standard": cs_standard,
        "minmax":   cs_minmax,
        "robust":   cs_robust
    }[standardisation_type]

    cs_fn_vol = {
        "standard": cs_standard,
        "minmax":   cs_minmax,
        "robust":   cs_robust
    }[standardisation_type_volume]


    def cs_norm_by_base(X_df, fun=cs_fn):
        base_cols = list({c.split("_",1)[-1] for c in X_df.columns})
        for base in base_cols:
            cols = [f"{t}_{base}" for t in tickers if f"{t}_{base}" in X_df.columns]
            if cols:
                X_df[cols] = X_df[cols].apply(fun, axis=1)
        return X_df

    def rank_by_base(X_df):
        base_cols = list({c.split("_",1)[-1] for c in X_df.columns})
        for base in base_cols:
            cols = [f"{t}_{base}" for t in tickers if f"{t}_{base}" in X_df.columns]
            if cols:
                X_df[cols] = X_df[cols].rank(axis=1, method="average", pct=False)
        return X_df

    #####
    ##### APPLYING STANDARDISATION ###
    #####
    X            = cs_norm_by_base(X, fun=cs_fn)
    #X = X.apply(cs_fn, axis=1)
    #VolDF_scaled = cs_norm_by_base(VolDF_scaled, fun=cs_fn_vol)
    VolDF_scaled = cs_norm_by_base(VolDF, fun=cs_fn_vol)
    #VolDF_scaled = VolDF

    if training:
        scaler_vol = ScalerClassVolume()
        VolDF_scaled = pd.DataFrame(
            scaler_vol.fit_transform(VolDF_scaled),
            index=VolDF.index,
            columns=VolDF.columns
        )
        with open(vol_scaler_path, "wb") as f:
            pickle.dump(scaler_vol, f)

        if "robust" == standardisation_type_volume:
            scaler_std_vol = StandardScaler()
            _   = scaler_std_vol.fit(VolDF_scaled)
            with open(vol_scaler_path.replace("robust", "standard"), "wb") as f:
                pickle.dump(scaler_std_vol, f)

    else:
        with open(vol_scaler_path, "rb") as f:
            scaler_vol = pickle.load(f)
            VolDF_scaled = pd.DataFrame(
               scaler_vol.transform(VolDF_scaled),
               index=VolDF.index,
               columns=VolDF.columns
            )

    if training:
        scaler_o = ScalerClass()
        btc_chain_df[chain_cols_to_standardise] = scaler_o.fit_transform(btc_chain_df[chain_cols_to_standardise])

        with open(onchain_scaler_path, "wb") as f:
            pickle.dump(scaler_o, f)

        scaler_m = ScalerClass()
        macro_df[macro_cols_to_standardise] = scaler_m.fit_transform(macro_df[macro_cols_to_standardise])

        with open(macro_scaler_path, "wb") as f:
            pickle.dump(scaler_m, f)

        if "robust" == standardisation_type:
            scaler_std = StandardScaler()
            scaler_std_macro = StandardScaler()
            _ = scaler_std.fit(btc_chain_df[chain_cols_to_standardise])
            _   = scaler_std_macro.fit(macro_df[macro_cols_to_standardise])

            with open(onchain_scaler_path.replace("robust", "standard"), "wb") as f:
                pickle.dump(scaler_std, f)
            with open(macro_scaler_path.replace("robust", "standard"), "wb") as f:
                pickle.dump(scaler_std_macro, f)

    else:
        with open(onchain_scaler_path, "rb") as f:
            scaler = pickle.load(f)
            btc_chain_df[chain_cols_to_standardise] = scaler.transform(btc_chain_df[chain_cols_to_standardise])

        with open(macro_scaler_path, "rb") as f:
            scaler = pickle.load(f)
            macro_df[macro_cols_to_standardise] = scaler.transform(macro_df[macro_cols_to_standardise])


    # -------------------------------------------------------------------------
    # Drop NaNs
    # -------------------------------------------------------------------------
    valid_idx = X.index.intersection(VolDF_scaled.index)
    valid_idx = valid_idx.intersection(y.index)
    valid_idx = valid_idx.intersection(y_mkt_raw_df.index)
    valid_idx = valid_idx.intersection(btc_chain_df.index)
    valid_idx = valid_idx.intersection(macro_df.index)

    X            = X.loc[valid_idx]
    VolDF_scaled = VolDF_scaled.loc[valid_idx]
    y            = y.loc[valid_idx]
    y_mkt_cs     = y_mkt_raw_df.loc[valid_idx].sub(y_mkt_raw_df.mean(axis=1), axis=0)
    y_mkt_abs     = y_mkt_raw_df.loc[valid_idx]
    onchain_data = btc_chain_df.loc[valid_idx]
    macro_data   = macro_df.loc[valid_idx]

    # -------------------------------------------------------------------------
    # Convert to numpy
    # -------------------------------------------------------------------------
    X_np         = np.nan_to_num(X.to_numpy(dtype=np.float32))
    Vol_np       = np.nan_to_num(VolDF_scaled.to_numpy(dtype=np.float32))
    X_onchain_np = np.nan_to_num(onchain_data.to_numpy(dtype=np.float32))
    X_macro_np   = np.nan_to_num(macro_data.to_numpy(dtype=np.float32))
    y_np         = np.nan_to_num(y.to_numpy(dtype=np.float32))
    y_mkt_train  = np.nan_to_num(y_mkt_cs.to_numpy(dtype=np.float32))
    y_abs_train  = np.nan_to_num(y_mkt_abs.to_numpy(dtype=np.float32))

    # -------------------------------------------------------------------------
    # Reshape per-asset block
    #
    # ---- FIX (silent reshape corruption) ------------------------------------
    # `X_np.shape[1] // n_assets` silently assumed every ticker contributes
    # exactly the same number of columns to X. If that's ever untrue (e.g. a
    # column missing for one ticker upstream), the reshape below succeeds
    # but scrambles the feature tensor across assets/features without any
    # error -- a very hard bug to catch later. We now assert per-ticker
    # column counts are identical before reshaping, and assert the total
    # column count is exactly divisible, so a mismatch fails loudly here
    # instead of silently corrupting the training data.
    # -------------------------------------------------------------------------
    per_ticker_counts = {t: sum(1 for col in X.columns if col.startswith(f"{t}_")) for t in tickers}
    distinct_counts = set(per_ticker_counts.values())
    assert len(distinct_counts) == 1, (
        f"Per-asset feature count mismatch, cannot safely reshape into "
        f"(n_samples, n_assets, n_features_per_asset): {per_ticker_counts}"
    )

    n_samples = len(X_np)
    n_assets  = len(tickers)
    n_features_per_asset = distinct_counts.pop()

    assert X_np.shape[1] == n_features_per_asset * n_assets, (
        f"X_np has {X_np.shape[1]} columns, expected "
        f"{n_features_per_asset} features/asset * {n_assets} assets = "
        f"{n_features_per_asset * n_assets}"
    )

    X_assets = X_np.reshape(n_samples, n_assets, n_features_per_asset)

    # -------------------------------------------------------------------------
    # Per-head label arrays (vol-scaled)
    # -------------------------------------------------------------------------
    r1_cols  = [f"{t}_r1"  for t in tickers]
    r3_cols  = [f"{t}_r3"  for t in tickers]
    r7_cols  = [f"{t}_r7"  for t in tickers]
    r10_cols = [f"{t}_r10" for t in tickers]
    r13_cols = [f"{t}_r13" for t in tickers]
    r17_cols = [f"{t}_r17" for t in tickers]
    r24_cols = [f"{t}_r24" for t in tickers]

    r1_train  = np.nan_to_num(y[r1_cols].to_numpy(dtype=np.float32))
    r3_train  = np.nan_to_num(y[r3_cols].to_numpy(dtype=np.float32))
    r7_train  = np.nan_to_num(y[r7_cols].to_numpy(dtype=np.float32))
    r10_train = np.nan_to_num(y[r10_cols].to_numpy(dtype=np.float32))
    r13_train = np.nan_to_num(y[r13_cols].to_numpy(dtype=np.float32))
    r17_train = np.nan_to_num(y[r17_cols].to_numpy(dtype=np.float32))
    r24_train = np.nan_to_num(y[r24_cols].to_numpy(dtype=np.float32))


    # -------------------------------------------------------------------------
    # FAST IC COMPUTATION (Spearman) USING ONLY 5 ASSETS
    # -------------------------------------------------------------------------
    #import scipy.stats as ss
    # Pick 5 representative assets
    #tickers_small = tickers[:5]
    # Slice correctly (no NumPy slicing)
    #y_small = y_mkt_cs[[f"{t}_y_mkt_raw" for t in tickers_small]]
    #df_all = pd.concat([X, VolDF_scaled], axis=1)
    #
    #ic_results = {}
    #
    ## Extract base feature names (ret_1d, vol_7d, macd_hist, etc.)
    #base_features = sorted({c.split("_", 1)[1] for c in df_all.columns})
    #
    #for base in base_features:
    #    # Collect only the 5 assets for this feature
    #    cols = [f"{t}_{base}" for t in tickers_small if f"{t}_{base}" in df_all.columns]
    #    if len(cols) < 5:
    #        continue
    #
    #    F = df_all[cols]  # shape: (n_samples, 5)
    #
    #    daily_ic = []
    #    for idx in F.index:
    #        f_row = F.loc[idx].to_numpy()
    #        y_row = y_small.loc[idx].to_numpy()
    #
    #        # Skip constant rows
    #        if np.all(f_row == f_row[0]) or np.all(y_row == y_row[0]):
    #            continue
    #
    #        ic, _ = ss.spearmanr(f_row, y_row)
    #        daily_ic.append(ic)
    #
    #    if daily_ic:
    #        ic_results[base] = float(np.nanmean(daily_ic))
    #
    ## Sort IC results
    #ic_sorted = dict(sorted(ic_results.items(), key=lambda x: x[1], reverse=True))
    #print("\n================ FAST IC RESULTS (5 assets) ================")
    #for base, ic in ic_sorted.items():
    #    print(f"{base:30s}  IC = {ic: .4f}")
    #print("============================================================\n")



    # -------------------------------------------------------------------------
    # Return full arrays with original signature
    # -------------------------------------------------------------------------

    return (
        X_assets,      # X_assets_train
        X_onchain_np,  # X_onchain_train
        X_macro_np,    # X_macro_train
        y_abs_train,          # y_train (vol-scaled heads)
        y_mkt_train,   # y_mkt_train (cs-demeaned raw 1d returns)
        Vol_np,        # X_vol_train
        r1_train,
        r3_train,
        r7_train,
        r10_train,
        r13_train,
        r17_train,
        r24_train,
    )


def cvar_loss(returns, alpha=0.95):
    # returns: shape (T,)
    sorted_ret = tf.sort(returns)

    n = tf.shape(sorted_ret)[0]                         # Tensor
    n_f = tf.cast(n, tf.float32)                       # float32 tensor
    k_f = tf.floor((1.0 - alpha) * n_f)                # float32 tensor
    k = tf.cast(k_f, tf.int32)                         # int32 tensor

    # Avoid empty slice
    k = tf.maximum(k, 1)

    tail = sorted_ret[:k]
    return -tf.reduce_mean(tail)



def sharpe_with_cvar_loss(y_true, y_pred,
                          cost_rate=0.0005,
                          eps=1e-6,
                          alpha=0.95,
                          L_max=0.1,
                          lambda_cvar=10.0):

    y_true = tf.cast(y_true, tf.float32)
    y_pred = tf.cast(y_pred, tf.float32)

    # Gross returns
    gross = tf.reduce_sum(y_true * y_pred, axis=1)

    # Turnover
    w_prev = tf.concat([y_pred[:1], y_pred[:-1]], axis=0)
    turnover = tf.reduce_sum(tf.abs(y_pred - w_prev), axis=1)

    # Net returns
    net = gross - cost_rate * turnover

    # Sharpe
    mean_r = tf.reduce_mean(net)
    std_r = tf.sqrt(tf.reduce_mean(tf.square(net - mean_r)) + eps)
    sharpe = mean_r / std_r

    # CVaR constraint
    cvar = cvar_loss(net, alpha=alpha)

    # Penalty
    penalty = tf.nn.relu(cvar - L_max)

    return -(sharpe) + lambda_cvar * penalty



def sharpe_loss(y_true, y_pred, cost_rate=0.0005, eps=1e-6):
    y_true = tf.cast(y_true, tf.float32)
    y_pred = tf.cast(y_pred, tf.float32)

    # Gross returns: sum_i w_{t,i} * r_{t,i}
    gross = tf.reduce_sum(y_true * y_pred, axis=1)  # shape (T,)

    # Previous weights (shifted by 1)
    w_prev = tf.concat([y_pred[:1], y_pred[:-1]], axis=0)

    # Turnover: sum_i |w_t - w_{t-1}|
    turnover = tf.reduce_sum(tf.abs(y_pred - w_prev), axis=1)

    # Transaction costs
    tcost = cost_rate * turnover

    # Net returns
    net = gross - tcost

    # Sharpe ratio
    mean_r = tf.reduce_mean(net)
    std_r = tf.sqrt(tf.reduce_mean(tf.square(net - mean_r)) + eps)

    return -(mean_r / std_r)


def continuous_quantile_longshort_loss(y_true, y_pred, q_low=0.2, q_high=0.8, sharpness=10.0, tau=0.1):
  # soft ranks in [0,1]
  r = soft_rank(y_pred, tau=tau)

  # smooth gates
  long_gate = tf.nn.sigmoid(sharpness * (r - q_high))
  short_gate = tf.nn.sigmoid(sharpness * (q_low - r))

  # weights in [-1,1]
  weights = long_gate - short_gate

  # portfolio pnl
  pnl = tf.reduce_mean(weights * y_true)

  return -pnl


def pearson_corr_loss(y_true, y_pred, eps=1e-6):
    # center
    x = y_pred - tf.reduce_mean(y_pred)
    y = y_true - tf.reduce_mean(y_true)

    # normalize
    x_norm = x / (tf.sqrt(tf.reduce_mean(tf.square(x))) + eps)
    y_norm = y / (tf.sqrt(tf.reduce_mean(tf.square(y))) + eps)

    # scalar correlation
    corr = tf.reduce_mean(x_norm * y_norm)

    return 1.0 - corr


@tf.keras.utils.register_keras_serializable(package="custom")
class MixedSharpePearsonPnl(tf.keras.losses.Loss):
    def __init__(self, alpha=0.0, ema_decay=0.99,
                 reduction=tf.keras.losses.Reduction.SUM_OVER_BATCH_SIZE,
                 name="mixed_loss"):
        super().__init__(name=name, reduction=reduction)

        # store hyperparameters
        self.alpha_init = float(alpha)
        self.ema_decay = float(ema_decay)

        # --- STATEFUL VARIABLES (not tracked by Keras) ---
        self.alpha = tf.Variable(self.alpha_init, trainable=False, dtype=tf.float32)
        self.ic_ema = tf.Variable(1.0, trainable=False, dtype=tf.float32)
        self.pnl_ema = tf.Variable(1.0, trainable=False, dtype=tf.float32)
        self.sharpe_ema = tf.Variable(1.0, trainable=False, dtype=tf.float32)

    def update_ema(self, ema_var, value):
        new_val = self.ema_decay * ema_var + (1.0 - self.ema_decay) * tf.abs(value)
        ema_var.assign(new_val)

    def call(self, y_true, y_pred):
        ic = pearson_corr_loss(y_true, y_pred)
        pnl = pnl_loss(y_true, y_pred)
        sharpe = sharpe_loss(y_true, y_pred)

        # update EMAs
        self.update_ema(self.ic_ema, ic)
        self.update_ema(self.pnl_ema, pnl)
        self.update_ema(self.sharpe_ema, sharpe)

        # normalize
        ic_norm = ic / (self.ic_ema + 1e-6)
        pnl_norm = pnl / (self.pnl_ema + 1e-6)
        sharpe_norm = sharpe / (self.sharpe_ema + 1e-6)

        alpha = self.alpha
        w_ic = 1.0 - alpha
        w_pnl = tf.where(alpha <= 2/3, 1.5 * alpha, -1.5 * alpha + 2.0)
        w_sharpe = alpha ** 3

        return w_ic * ic_norm + w_pnl * pnl_norm + w_sharpe * sharpe_norm

    def get_config(self):
        base = super().get_config()
        base.update({
            "alpha": float(self.alpha_init),
            #"ema_decay": float(self.ema_decay),
        })
        return base

    @classmethod
    def from_config(cls, config):
        return cls(**config)



class AlphaLRScheduler(tf.keras.callbacks.Callback):
    def __init__(self, loss_obj, optimizer, warmup=5, ramp=10, alpha_max=0.6, verbose=False, is_warmup=False):
        super().__init__()
        self.loss_obj = loss_obj
        self.optimizer = optimizer
        self.warmup = warmup
        self.ramp = ramp
        self.alpha_max = alpha_max
        self.verbose = verbose
        self.is_warmup = is_warmup

        # store initial LR
        #self.initial_lr = float(tf.keras.backend.get_value(optimizer.learning_rate))

    def on_epoch_begin(self, epoch, logs=None):

        # -------------------------
        # 1. LR warmup
        # -------------------------
        #if self.is_warmup and epoch < self.warmup:
        #    warmup_lr = (self.initial_lr / 10.0) + \
        #                (epoch / self.warmup) * (self.initial_lr - self.initial_lr / 10.0)

        #    opt = self.optimizer

        #    if hasattr(opt, "lr") and isinstance(opt.lr, tf.Variable):
        #        opt.lr.assign(warmup_lr)

        #    elif hasattr(opt, "learning_rate") and isinstance(opt.learning_rate, tf.Variable):
        #        opt.learning_rate.assign(warmup_lr)

        #    else:
        #        # fallback: reassign the attribute entirely
        #        opt.learning_rate = warmup_lr

        #    #tf.keras.backend.set_value(self.optimizer.learning_rate, warmup_lr)
        #    lr_phase = "LR warmup"
        #elif self.is_warmup:

        #    opt = self.optimizer

        #    if hasattr(opt, "lr") and isinstance(opt.lr, tf.Variable):
        #        opt.lr.assign(self.initial_lr)

        #    elif hasattr(opt, "learning_rate") and isinstance(opt.learning_rate, tf.Variable):
        #        opt.learning_rate.assign(self.initial_lr)

        #    else:
        #        # fallback: reassign the attribute entirely
        #        opt.learning_rate = self.initial_lr

        #    #tf.keras.backend.set_value(self.optimizer.learning_rate, self.initial_lr)
        #    lr_phase = "LR steady"
        #else:
        #    lr_phase = "LR warmup deactivated"

        # -------------------------
        # 2. Alpha warmup + ramp
        # -------------------------
        if self.is_warmup and epoch < self.warmup:
            alpha_val = 0.0
            alpha_phase = "alpha=0 (warmup)"
        else:
            t = min(1.0, (epoch - self.warmup) / self.ramp)
            alpha_val = max([0, t * self.alpha_max])
            alpha_phase = f"alpha ramp ({alpha_val:.4f})"

        # update alpha safely
        tf.keras.backend.set_value(self.loss_obj["exposures"].alpha, alpha_val)

        tf.keras.backend.set_value(self.loss_obj["exposures_h1"].alpha, alpha_val)
        tf.keras.backend.set_value(self.loss_obj["exposures_h3"].alpha, alpha_val)
        tf.keras.backend.set_value(self.loss_obj["exposures_h7"].alpha, alpha_val)
        tf.keras.backend.set_value(self.loss_obj["exposures_h10"].alpha, alpha_val)
        tf.keras.backend.set_value(self.loss_obj["exposures_h13"].alpha, alpha_val)
        tf.keras.backend.set_value(self.loss_obj["exposures_h17"].alpha, alpha_val)
        tf.keras.backend.set_value(self.loss_obj["exposures_h24"].alpha, alpha_val)

        # -------------------------
        # Verbose logging
        # -------------------------
        if self.verbose:
            lr_val = float(tf.keras.backend.get_value(self.optimizer.learning_rate))
            print(
                f"[Epoch {epoch}] "
                #f"LR={lr_val:.6f} ({lr_phase}), "
                f"alpha={alpha_val:.4f} ({alpha_phase})"
            )


def pnl_loss(y_true, weights, tx_cost=0.0005):
    # 1) Raw pnl (no shift)
    pnl = tf.reduce_sum(weights * y_true, axis=-1)   # shape (T,)

    # Previous weights (shifted by 1)
    w_prev = tf.concat([weights[:1], weights[:-1]], axis=0)

    # Turnover: sum_i |w_t - w_{t-1}|
    turnover = tf.reduce_sum(tf.abs(weights - w_prev), axis=1)

    # 4) Net pnl
    net_pnl = pnl - turnover

    # 5) Loss
    return -tf.reduce_mean(net_pnl)


def pnl_loss_with_cvar(y_true, weights,
                       tx_cost=0.0005,
                       alpha=0.95,
                       L_max=0.1,
                       lambda_cvar=10.0):

    # 1) Raw pnl
    pnl = tf.reduce_sum(weights * y_true, axis=-1)

    # 2) Turnover
    w_prev = tf.concat([weights[:1], weights[:-1]], axis=0)
    turnover = tf.reduce_sum(tf.abs(weights - w_prev), axis=1)

    # 3) Net pnl
    net_pnl = pnl - tx_cost * turnover

    # 4) Mean pnl (objective)
    mean_pnl = tf.reduce_mean(net_pnl)

    # 5) CVaR constraint
    sorted_ret = tf.sort(net_pnl)
    n = tf.shape(sorted_ret)[0]
    k = tf.cast(tf.floor((1.0 - alpha) * tf.cast(n, tf.float32)), tf.int32)
    tail = sorted_ret[:k]
    cvar = -tf.reduce_mean(tail)

    penalty = tf.nn.relu(cvar - L_max)

    # 6) Final loss
    return -(mean_pnl) + lambda_cvar * penalty


def quantile_longshort_loss(y_true, y_pred, q_low=0.2, q_high=0.8, sharpness=20.0):
    """
    Differentiable long/short quantile portfolio loss without TFP.

    y_true: (batch, assets)
    y_pred: (batch, assets)
    """

    # Sort predictions per batch
    sorted_pred = tf.sort(y_pred, axis=1)

    batch_size = tf.shape(y_pred)[0]
    n_assets = tf.shape(y_pred)[1]

    # Compute quantile indices
    idx_low = tf.cast(tf.round(q_low * tf.cast(n_assets - 1, tf.float32)), tf.int32)
    idx_high = tf.cast(tf.round(q_high * tf.cast(n_assets - 1, tf.float32)), tf.int32)

    # Build batch indices for gather
    batch_idx = tf.range(batch_size)
    batch_idx = tf.reshape(batch_idx, (-1, 1))

    # Gather quantile values
    q_low_val = tf.gather(sorted_pred, idx_low, axis=1)
    q_high_val = tf.gather(sorted_pred, idx_high, axis=1)

    # Reshape to (batch, 1)
    q_low_val = tf.expand_dims(q_low_val, 1)
    q_high_val = tf.expand_dims(q_high_val, 1)

    # Smooth long gate: sigmoid(pred - q_high)
    long_gate = tf.nn.sigmoid(sharpness * (y_pred - q_high_val))

    # Smooth short gate: sigmoid(q_low - pred)
    short_gate = tf.nn.sigmoid(sharpness * (q_low_val - y_pred))

    # Final exposure weights in [-1, +1]
    weights = long_gate - short_gate

    # Portfolio PnL
    pnl = tf.reduce_mean(weights * y_true)

    # Loss = negative PnL
    return -pnl



@tf.keras.utils.register_keras_serializable(package="custom")
class DirectionalTailLoss(tf.keras.losses.Loss):
    def __init__(self, lower_q=0.2, upper_q=0.8, scale=5.0, name="directional_tail_loss"):
        super().__init__(name=name)
        self.lower_q = lower_q
        self.upper_q = upper_q
        self.scale = scale

    def call(self, y_true, y_pred):
        """
        y_true: (B, A) raw next-day returns
        y_pred: (B, A) model scores BEFORE SoftQuantilePortfolio
        """

        # ----- 1. Compute per-day quantiles -----
        q_low  = tfp.stats.percentile(y_true, self.lower_q * 100, axis=1, keepdims=True)
        q_high = tfp.stats.percentile(y_true, self.upper_q * 100, axis=1, keepdims=True)

        # ----- 2. Build masks for tails -----
        mask_long  = tf.cast(y_true > q_high, tf.float32)   # upper tail
        mask_short = tf.cast(y_true < q_low,  tf.float32)   # lower tail
        mask = mask_long + mask_short                       # 1 where label exists

        # ----- 3. Directional labels -----
        # +1 for long tail, -1 for short tail
        y_dir = mask_long - mask_short                      # shape (B, A)

        # ----- 4. Smooth sign surrogate for predictions -----
        # This removes magnitude influence and keeps gradients smooth
        y_pred_sign = tf.tanh(self.scale * y_pred)

        # ----- 5. Logistic loss on directional agreement -----
        # agreement = +1 if signs match, -1 if mismatch
        agreement = y_dir * y_pred_sign
        raw_loss = tf.math.log(1.0 + tf.exp(-agreement))

        # ----- 6. Mask out middle assets -----
        masked_loss = raw_loss * mask

        # ----- 7. Normalize by number of labeled assets -----
        denom = tf.reduce_sum(mask) + 1e-6
        return tf.reduce_sum(masked_loss) / denom



@tf.keras.utils.register_keras_serializable(package="custom")
class RegimeStatsLayer(layers.Layer):
    def __init__(self, eps=1e-6, **kwargs):
        super().__init__(**kwargs)
        self.eps = eps
        self.num_stats = 10

    def call(self, scores):
        eps = self.eps

        mean = ops.mean(scores, axis=1, keepdims=True)
        std  = ops.std(scores, axis=1, keepdims=True)
        minv = ops.min(scores, axis=1, keepdims=True)
        maxv = ops.max(scores, axis=1, keepdims=True)
        rng  = maxv - minv

        centered = scores - mean
        m3 = ops.mean(centered**3, axis=1, keepdims=True)
        skew = m3 / (std**3 + eps)

        m4 = ops.mean(centered**4, axis=1, keepdims=True)
        kurt = m4 / (std**4 + eps)

        norm = (scores - minv) / (rng + eps)
        entropy = -ops.mean(norm * ops.log(norm + eps), axis=1, keepdims=True)

        snr = ops.abs(mean) / (std + eps)
        dispersion = std

        return ops.concatenate([
            mean, std, minv, maxv, rng,
            skew, kurt, entropy,
            snr, dispersion
        ], axis=1)

    def compute_output_shape(self, input_shape):
        # TimeDistributed will pass (batch, features) here
        # Output is (batch, num_stats)
        return (input_shape[0], self.num_stats)

    def get_config(self):
        return {**super().get_config(), "eps": self.eps}



class SoftRank(layers.Layer):
    def __init__(self, tau=0.1, **kwargs):
        super().__init__(**kwargs)
        self.tau = tau

    def call(self, x):
        """
        x: [batch, n_assets]
        returns: [batch, n_assets] soft ranks in [0,1]
        """
        # [batch, n_assets, 1]
        x_i = ops.expand_dims(x, axis=2)
        # [batch, 1, n_assets]
        x_j = ops.expand_dims(x, axis=1)

        # pairwise differences
        diff = x_i - x_j  # [batch, n_assets, n_assets]

        # soft indicator
        P = ops.sigmoid(diff / self.tau)  # [batch, n_assets, n_assets]

        # soft rank = mean across comparisons
        r = ops.mean(P, axis=2)  # [batch, n_assets]

        return r

    def compute_output_shape(self, input_shape):
        # input_shape: (batch, n_assets)
        return input_shape

    def get_config(self):
        config = super().get_config()
        config.update({"tau": self.tau})
        return config



def soft_rank(x, tau=1.0):
    """
    Differentiable soft rank in [0,1].
    x: (batch, assets)
    """
    x_expanded = tf.expand_dims(x, 2)
    y_expanded = tf.expand_dims(x, 1)

    # pairwise comparisons
    P = tf.nn.sigmoid((x_expanded - y_expanded) / tau)

    # soft rank = mean of comparisons
    r = tf.reduce_mean(P, axis=2)

    # normalize to [0,1]
    return r



class CyclicalLearningRate(keras.callbacks.Callback):
    def __init__(self, base_lr=1e-4, max_lr=1.5e-3, step_size=2000, scale_mode="cycle"):
        super().__init__()
        self.base_lr = base_lr
        self.max_lr = max_lr
        self.step_size = step_size
        self.scale_mode = scale_mode
        self.iterations = 0

    def clr(self):
        cycle = tf.floor(1 + self.iterations / (2 * self.step_size))
        x = tf.abs(self.iterations / self.step_size - 2 * cycle + 1)
        lr = self.base_lr + (self.max_lr - self.base_lr) * tf.maximum(0.0, (1 - x))
        return lr

    def on_train_batch_begin(self, batch, logs=None):
        self.iterations += 1
        lr = self.clr()
        opt = self.model.optimizer

        if hasattr(opt, "lr") and isinstance(opt.lr, tf.Variable):
            opt.lr.assign(lr)

        elif hasattr(opt, "learning_rate") and isinstance(opt.learning_rate, tf.Variable):
            opt.learning_rate.assign(lr)

        else:
            # fallback: reassign the attribute entirely
            opt.learning_rate = lr

        #tf.keras.backend.set_value(self.model.optimizer.learning_rate, lr)


