@tf.keras.utils.register_keras_serializable(package="custom")
class ExpandDims(layers.Layer):
    def __init__(self, axis=-1, **kwargs):
        super().__init__(**kwargs)
        self.axis = axis

    def call(self, x):
        return ops.expand_dims(x, axis=self.axis)

    def compute_output_shape(self, input_shape):
        # input_shape is a tuple like (batch, ..., features)
        input_shape = tuple(input_shape)
        rank = len(input_shape)

        # Normalize negative axis
        if self.axis < 0:
            axis = rank + 1 + self.axis  # +1 because we’re inserting a new dim
        else:
            axis = self.axis

        # Insert a 1 at the right position
        return input_shape[:axis] + (1,) + input_shape[axis:]

    def get_config(self):
        return {**super().get_config(), "axis": self.axis}


@tf.keras.utils.register_keras_serializable(package="custom")
class RepeatAxis(layers.Layer):
    def __init__(self, repeats, axis=1, **kwargs):
        super().__init__(**kwargs)
        self.repeats = repeats
        self.axis = axis

    def call(self, x):
        return ops.repeat(x, repeats=self.repeats, axis=self.axis)

    def compute_output_shape(self, input_shape):
        input_shape = list(input_shape)
        rank = len(input_shape)

        # normalize negative axis
        axis = self.axis if self.axis >= 0 else self.axis + rank

        input_shape[axis] = input_shape[axis] * self.repeats
        return tuple(input_shape)

    def get_config(self):
        return {
            **super().get_config(),
            "repeats": self.repeats,
            "axis": self.axis
        }


@tf.keras.utils.register_keras_serializable(package="custom")
class AssetIndex(layers.Layer):
    def call(self, x):
        batch = ops.shape(x)[0]
        n_assets = ops.shape(x)[1]

        ids = ops.arange(n_assets)          # (A,)
        ids = ops.expand_dims(ids, 0)       # (1, A)
        ids = ops.tile(ids, (batch, 1))     # (B, A)
        return ids


