@keras.utils.register_keras_serializable(package="custom")
class DynamicGroupNorm(keras.layers.Layer):
    def __init__(self, channels_per_group=16, **kwargs):
        super().__init__(**kwargs)
        self.channels_per_group = channels_per_group

    def build(self, input_shape):
        channels = input_shape[-1]

        groups = max(1, channels // self.channels_per_group)
        while channels % groups != 0 and groups > 1:
            groups -= 1

        self.groupnorm = keras.layers.GroupNormalization(
            groups=groups,
            axis=-1,
            name=f"{self.name}_gn"
        )

    def call(self, x):
        return self.groupnorm(x)

    def get_config(self):
        config = super().get_config()
        config.update({
            "channels_per_group": self.channels_per_group
        })
        return config


@keras.utils.register_keras_serializable(package="custom")
class AdaptiveELU(keras.layers.Layer):
    def __init__(self, alpha_init=1.0, **kwargs):
        super().__init__(**kwargs)
        self.alpha_init = alpha_init

    def build(self, input_shape):
        self.alpha = self.add_weight(
            name="alpha",
            shape=(),
            initializer=tf.keras.initializers.Constant(self.alpha_init),
            trainable=True
        )

    def call(self, x):
        return tf.where(
            x > 0,
            x,
            self.alpha * (tf.exp(x) - 1)
        )

    def get_config(self):
        config = super().get_config()
        config.update({
            "alpha_init": self.alpha_init
        })
        return config


# ══════════════════════════════════════════════════════════════════════════════
# F03  _soft_cummax — robust to dynamic batch sizes
# ══════════════════════════════════════════════════════════════════════════════

def _soft_cummax(x):
    """
    Differentiable soft running-maximum via cumulative logsumexp.

        soft_cummax[t] = log( Σ_{s=0}^{t} exp(x[s]) )

    Static-B path  : O(B²) triangular logsumexp — fast on GPU, safe when
                     batch size is fixed at graph-build time.
    Dynamic-B path : O(B) sequential tf.scan — used when B is None at
                     graph-build time, avoiding silent shape errors.
    """
    static_B = x.shape[0]

    if static_B is not None:
        # ── static path ──────────────────────────────────────────────────────
        B        = static_B
        x_tiled  = ops.broadcast_to(x[None, :], (B, B))
        idx      = ops.arange(B)
        mask     = ops.cast(idx[:, None] >= idx[None, :], x.dtype)
        neg_inf  = ops.full((B, B), -1e9, dtype=x.dtype)
        x_masked = ops.where(mask == 1, x_tiled, neg_inf)
        return ops.logsumexp(x_masked, axis=-1)
    else:
        # ── dynamic path — sequential log-add-exp scan ────────────────────
        # tf.scan has no keras.ops equivalent. This path is TF-backend only.
        # On JAX/PyTorch backends with a dynamic batch size, use a fixed
        # batch size at graph-build time to take the static path above.

        if K.backend() != "tensorflow":
            raise NotImplementedError(
                "_soft_cummax dynamic path requires the TensorFlow backend. "
                "Use a fixed batch size so the static path is taken instead."
            )
        def scan_fn(prev_lse, x_t):
            m       = ops.maximum(prev_lse, x_t)
            new_lse = m + ops.log(ops.exp(prev_lse - m) + ops.exp(x_t - m))
            return new_lse, new_lse

        init      = x[0]
        _, result = tf.scan(scan_fn, x[1:], initializer=init)
        return tf.concat([[x[0]], result], axis=0)



def create_windowed_inputs(x, y_abs, y_rel, window):
    """
    x:     np.array (S, A, F)
    y_abs: np.array (S, A)
    y_rel: np.array (S, A)
    window: int

    Returns:
        x_win:     (S - window, window, A, F)
        y_win:     (S - window, window, A)
        yrel_win:  (S - window, window, A)
    """
    S, A, F = x.shape
    assert y_abs.shape == (S, A)
    assert y_rel.shape == (S, A)

    out_len = S - window + 1
    if out_len <= 0:
        raise ValueError("Window is too large for the number of samples")

    # --- X WINDOWING ---
    x_strides = (x.strides[0], x.strides[0], x.strides[1], x.strides[2])
    x_win = np.lib.stride_tricks.as_strided(
        x,
        shape=(out_len, window, A, F),
        strides=x_strides,
        writeable=False
    )

    # --- Y ABS WINDOWING ---
    y_strides = (y_abs.strides[0], y_abs.strides[0], y_abs.strides[1])
    y_win = np.lib.stride_tricks.as_strided(
        y_abs,
        shape=(out_len, window, A),
        strides=y_strides,
        writeable=False
    )

    # --- Y REL WINDOWING ---
    y_strides_rel = (y_rel.strides[0], y_rel.strides[0], y_rel.strides[1])
    yrel_win = np.lib.stride_tricks.as_strided(
        y_rel,
        shape=(out_len, window, A),
        strides=y_strides_rel,   # same stride pattern
        writeable=False
    )

    # --- Y REL WINDOWING ---
    #x_reg_strides = (x_reg.strides[0], x_reg.strides[0], x_reg.strides[1])
    #x_reg_win = np.lib.stride_tricks.as_strided(
    #    x_reg,
    #    shape=(out_len, window, x_reg.shape[-1]),
    #    strides=x_reg_strides,   # same stride pattern
    #    writeable=False
    #)

    return x_win, y_win, yrel_win#, x_reg_win

"""# **SECOND LSTM**"""

def order_columns_by_ticker(df, tickers):
    """
    Sort dataframe columns so that:
      1. Columns starting with a ticker_ prefix are grouped by ticker
      2. Within each ticker group, columns are sorted alphabetically
      3. Columns without any ticker prefix go last, sorted alphabetically
      4. The process is deterministic
    """

    tickers = sorted(tickers)  # ensure deterministic order

    ticker_groups = {t: [] for t in tickers}
    no_ticker = []

    for col in df.columns:
        matched = False
        for t in tickers:
            prefix = f"{t}_"
            if col.startswith(prefix):
                ticker_groups[t].append(col)
                matched = True
                break
        if not matched:
            no_ticker.append(col)

    # Sort each group deterministically
    for t in tickers:
        ticker_groups[t] = sorted(ticker_groups[t])

    no_ticker = sorted(no_ticker)

    # Flatten in correct order
    ordered_cols = []
    for t in tickers:
        ordered_cols.extend(ticker_groups[t])
    ordered_cols.extend(no_ticker)
    return df[ordered_cols]


def join_economic_data(initial_data, start="2010-01-01", end=datetime.today().strftime("%Y-%m-%d"), ranges=[10, 50, 200], tickers=None):

    # Define tickers
    if tickers is None:
        tickers = [
            '^GSPC', '^DJI', '^IXIC', '^VIX', 'EURUSD=X', 'JPY=X', 'GBPUSD=X',
            'CL=F', 'HG=F', 'GC=F', #'^TNX', '^IRX',
            'XLB', 'XLI', 'XLE', 'XLF', 'XLK'
        ]

    # Download data
    raw_data = yf.download(tickers, start=start, end=end, interval='1d', auto_adjust=False)

    # Extract 'Close' prices from MultiIndex
    data = raw_data.loc[:, 'Close']
    data = data.asfreq("d")

    # Drop rows with missing values
    data = data.ffill().dropna()
    z_datas = []
    for rang in ranges:

        rolling_mean = data.rolling(window=rang).mean()
        rolling_std = data.rolling(window=rang).std()
        z_data = (data - rolling_mean) / rolling_std

        # Normalize using z-score
        #z_data = data.apply(zscore)

        # Compute indices
        z_data['GESI'] = z_data[['^GSPC', '^DJI', '^IXIC']].mean(axis=1) - z_data['^VIX'] + z_data[
            ['EURUSD=X', 'JPY=X', 'GBPUSD=X']].mean(axis=1)
        z_data['IPI'] = z_data[['CL=F', 'HG=F', 'GC=F']].mean(axis=1) + z_data[['XLB', 'XLI', 'XLE']].mean(axis=1)
        #z_data['IEI'] = z_data[['^TNX', '^IRX']].mean(axis=1) + z_data[['CL=F', 'GC=F']].mean(axis=1) - z_data['EURUSD=X']
        #z_data['MSI'] = z_data['^VIX'] + z_data['^IRX'] - z_data[['^GSPC', '^DJI', '^IXIC']].mean(axis=1)

        z_data['CPIx'] = z_data[['CL=F', 'HG=F', 'GC=F']].mean(axis=1)
        #z_data['DMSIx'] = z_data[['^TNX', '^IRX']].mean(axis=1) + (z_data['^TNX'] - z_data['^IRX'])
        z_data['LPIx'] = z_data[['EURUSD=X', 'JPY=X', 'GBPUSD=X']].mean(axis=1) - z_data['^VIX'] + z_data[
            ['XLF', 'XLK']].mean(axis=1)
        z_data['MMIx'] = z_data[['^GSPC', '^DJI', '^IXIC']].mean(axis=1) - z_data['^VIX'] + z_data[
            ['XLB', 'XLI', 'XLE', 'XLF', 'XLK']].mean(axis=1)

        z_data['MFIx'] = z_data[['CPIx', 'LPIx', 'MMIx']].mean(axis=1)

        # Print latest values
        z_data = z_data[['GESI', 'IPI', 'CPIx', 'LPIx', 'MMIx', 'MFIx']].ffill()
        z_data = z_data.tz_localize("utc")
        z_data = z_data.add_prefix(f"eco_{rang}_")
        z_datas.append(z_data)

    z_data = pd.concat(z_datas, axis=1, ignore_index=False)
    #initial_data.set_index(pd.to_datetime(initial_data['unix'], unit='ns'), inplace=True)
    initial_data = initial_data.join(z_data, how="inner")
    initial_data = initial_data.dropna()
    return initial_data

def soft_rank(scores, tau=1.0):
    x_i = ops.expand_dims(scores, axis=2)
    x_j = ops.expand_dims(scores, axis=1)
    P   = ops.sigmoid((x_i - x_j) / tau)
    r   = ops.mean(P, axis=2)
    r_min = ops.min(r, axis=-1, keepdims=True)
    r_max = ops.max(r, axis=-1, keepdims=True)
    return (r - r_min) / (r_max - r_min + 1e-6)


@keras.utils.register_keras_serializable(package="custom")
class CrossSectionalNorm(layers.Layer):
    def call(self, t):
        mean = ops.mean(t, axis=1, keepdims=True)
        std  = ops.expand_dims(ops.sqrt(ops.var(t, axis=1) + 1e-6), axis=1)
        return (t - mean) / std


def soft_rank(scores, tau=1.0):
    x_i = ops.expand_dims(scores, axis=2)
    x_j = ops.expand_dims(scores, axis=1)
    P   = ops.sigmoid((x_i - x_j) / tau)
    r   = ops.mean(P, axis=2)
    r_min = ops.min(r, axis=-1, keepdims=True)
    r_max = ops.max(r, axis=-1, keepdims=True)
    return (r - r_min) / (r_max - r_min + 1e-6)


@keras.utils.register_keras_serializable(package="custom")
class SoftQuantilePortfolio(layers.Layer):
    def __init__(self, tau=1.0, sharpness=1.0, deadzone=0.02, **kwargs):
        super().__init__(**kwargs)
        self.tau   = tau
        self.sharpness = sharpness
        self.deadzone = deadzone #0.02
        #self.neutral_low = 0.2
        #self.neutral_high = 0.8

    def soft_deadzone(self, x, eps):
        # Smooth L0-like shrinkage
        # Equivalent to: sign(x) * max(|x| - eps, 0)
        abs_x = ops.abs(x)
        return ops.sign(x) * ops.maximum(abs_x - eps, 0.0)

    def logistic_gate(self, r, k):
        low_gate  = ops.sigmoid(k - r)
        high_gate = ops.sigmoid(r - (1.0 - k))
        return low_gate + high_gate

    def call(self, inputs):
        # inputs MUST be a list/tuple
        if isinstance(inputs, (list, tuple)):
            if len(inputs)>1:
              scores, agreement = inputs
            else:
              scores = inputs[0]
              agreement = None
        else:
            scores = inputs
            agreement = None

        # 1. Soft-rank
        r = soft_rank(scores, tau=self.tau)

        # 2. Long/short signal
        target = (r - 0.5) * 2.0 * self.sharpness
        target = target - ops.mean(target, axis=1, keepdims=True)

        # 3. Adaptive gate
        if agreement is not None:
            gate = self.logistic_gate(r, agreement)
            target = target * gate

        # 4. Deadzone shrinkage
        target = self.soft_deadzone(target, self.deadzone)

        # 5. L1 normalization
        l1 = ops.sum(ops.abs(target), axis=1, keepdims=True) + 1e-6
        return target / l1

    #def call(self, scores):
    #    # Soft ranks in [0,1]
    #    r = soft_rank(scores, tau=self.tau)

    #    # Convert to centered long/short signal
    #    target = (r - 0.5) * 2.0 * self.sharpness

    #    # --- NEW: soft masking of mid-quantiles ---
    #    # mask = 1 outside neutral zone, 0 inside
    #    mask = ops.cast(
    #        (r < self.neutral_low) | (r > self.neutral_high),
    #        dtype=target.dtype
    #    )

    #    # Apply mask
    #    target = target * mask

    #    # Zero-mean (market-neutral)
    #    target = target - ops.mean(target, axis=1, keepdims=True)

    #    # L1-normalize (constant leverage)
    #    l1 = ops.sum(ops.abs(target), axis=1, keepdims=True) + 1e-6
    #    return target / l1

    def compute_output_spec(self, inputs):
        if isinstance(inputs, (list, tuple)):
            scores = inputs[0]
        else:
            scores = inputs
        return keras.KerasTensor(shape=scores.shape, dtype=scores.dtype, sparse=False)

    def get_config(self):
        config = super().get_config()
        config.update({
            "tau": self.tau,
            "sharpness": self.sharpness,
            "deadzone": self.deadzone
        })
        return config


@keras.utils.register_keras_serializable(package="custom")
class TemporalToScalar(layers.Layer):
    """(B, W, A) -> (B, A) using separable conv"""
    def __init__(self, kernel_size=5, seed=42, activation='relu', **kwargs):
        super().__init__(**kwargs)
        self.kernel_size = kernel_size
        self.activation = activation
        self.seed = seed

    def build(self, input_shape):
        B, W, A = input_shape
        #self.sep_conv = layers.Conv1D(
        #    filters=A,  # One per asset
        #    kernel_size=self.kernel_size,
        #    padding='same',
        #    activation=self.activation,
        #    name="temp_sep_conv",
        #    kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed)
        #)

        self.sep_conv = layers.SeparableConv1D(
            filters=A,                     # one per asset
            #depth_multiplier=1,
            kernel_size=self.kernel_size,
            padding='same',
            activation=None,
            name="temp_sep_conv",
            #kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed),
            depthwise_initializer=keras.initializers.GlorotUniform(seed=self.seed),
            pointwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+1)
        )

        self.attention = layers.Dense(1, activation='sigmoid', name="temp_attention", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+2))
        #self.attention = layers.LSTM(1, activation='sigmoid', name="temp_attention", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed)
        #                                  , seed=self.seed, return_sequences=True)
        self.sep_conv.build((None, W, A))
        self.attention.build((None, W, A))

    def call(self, x):
        x = tf.cast(x, self.sep_conv.compute_dtype)  # e.g., float16
        h = self.sep_conv(x)  # (B, W, A)
        #h = h + x                     # (B, W, A)
        attn = self.attention(h)  # (B, W, 1)
        attn = attn / (ops.sum(attn, axis=1, keepdims=True) + 1e-6)
        weighted = h * attn
        weighted = weighted + x       # (B, W, A)
        return ops.sum(weighted, axis=1)  # (B, A)

    def compute_output_shape(self, input_shape):
        # input_shape: (batch, window, assets)
        return (input_shape[0], input_shape[2])

    def get_config(self):
        config = super().get_config()
        config.update({
            "kernel_size": self.kernel_size,
            "activation": self.activation,
            "seed": self.seed
        })
        return config



