# Vol — R is dynamic (n_assets), use depthwise or project first
@keras.utils.register_keras_serializable(package="custom")
class VolumeMultiScaleEncoder(layers.Layer):
    """
    (B, W, Ak) -> (B, hidden_dim)
    Pure temporal depthwise convolution per asset.
    No pointwise conv, no cross-asset mixing.
    """
    def __init__(self, kernel_size=3, hidden_dim=32, activation='relu', **kwargs):
        super().__init__(**kwargs)
        self.kernel_size = kernel_size
        self.hidden_dim = hidden_dim
        self.activation = activation

        # Pure temporal convolution per asset
        self.depthwise = layers.DepthwiseConv2D(
            kernel_size=(1, kernel_size),
            padding="same",
            depth_multiplier=1,
            activation=activation,
        )

        # Final projection after pooling across assets
        self.fusion = layers.Dense(hidden_dim, activation="relu")

    def call(self, x):
        # x: (B, W, Ak)
        x = ops.transpose(x, (0, 2, 1))   # (B, Ak, W)
        x = ops.expand_dims(x, -1)        # (B, Ak, W, 1)

        h = self.depthwise(x)             # (B, Ak, W, 1)

        pooled_time = ops.mean(h, axis=2) # (B, Ak, 1)
        pooled_assets = ops.mean(pooled_time, axis=1)  # (B, 1)

        return self.fusion(pooled_assets) # (B, hidden_dim)

    def get_config(self):
        return {
            **super().get_config(),
            "kernel_size": self.kernel_size,
            "hidden_dim": self.hidden_dim,
            "activation": self.activation,
        }



@keras.utils.register_keras_serializable(package="custom")
class RegimeMultiScaleEncoder(layers.Layer):
    """(B, W, R) -> (B, H) with multiple kernel sizes"""
    def __init__(self, hidden_dim=32, seed=42, activation='relu', use_lstm=False, temporal_attention_type="None", dropout=0.1, **kwargs):
        super().__init__(**kwargs)
        self.hidden_dim = hidden_dim
        self.activation = activation
        self.dropout = dropout
        self.seed = seed
        self.use_lstm = use_lstm
        self.temporal_attention_type = temporal_attention_type

    def build(self, input_shape):
        B, W, R = input_shape

        # Conv layers use the activation parameter
        self.conv_short = layers.DepthwiseConv1D(
            #self.hidden_dim,
            depth_multiplier=1,
            kernel_size=2, padding='same',
            activation=None,#self.activation,
            name="conv_short",
            #kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed)
            #kernel_initializer=keras.initializers.Orthogonal(seed=self.seed),
            #kernel_regularizer=keras.regularizers.L1(1e-4),
            #kernel_constraint=keras.constraints.MaxNorm(3.0),
            depthwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+1),
            #pointwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+2),
        )
        self.conv_medium = layers.DepthwiseConv1D(
            #self.hidden_dim,
            depth_multiplier=1,
            kernel_size=5, padding='same',
            activation=None,#self.activation,
            name="conv_medium",
            #kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+1)
            #kernel_initializer=keras.initializers.Orthogonal(seed=self.seed+1),
            #kernel_regularizer=keras.regularizers.L1(1e-4),
            #kernel_constraint=keras.constraints.MaxNorm(3.0),
            depthwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+2),
            #pointwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+3),
        )
        self.conv_long = layers.DepthwiseConv1D(
            #self.hidden_dim,
            depth_multiplier=1,
            kernel_size=9, padding='same',
            activation=None,#self.activation,
            name="conv_long",
            #kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+2)
            #kernel_initializer=keras.initializers.Orthogonal(seed=self.seed+2),
            #kernel_regularizer=keras.regularizers.L1(1e-4),
            #kernel_constraint=keras.constraints.MaxNorm(3.0),
            depthwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+3),
            #pointwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+4),

        )
        #self.conv_long2 = layers.Conv1D(
        #    self.hidden_dim, 15, padding='same',
        #    activation=self.activation,
        #    name="conv_long",
        #    kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+2)
        #)


        if self.use_lstm:
            self.lstm = layers.LSTM(
                self.hidden_dim,
                return_sequences=False,
                kernel_initializer=keras.initializers.GlorotUniform(self.seed+3),
                name="temporal_lstm"
            )
            self.lstm.build((None, W, 3*R))


        # Fusion layer uses relu
        if not self.use_lstm:
            # Attention always uses sigmoid (gates need (0,1))
            if self.temporal_attention_type=="None":
                self.attention = layers.Dense(1, activation='sigmoid', name="attention", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+5))

            elif self.temporal_attention_type == "RNN":
                self.attention = layers.SimpleRNN(1, activation='sigmoid', name="temp_attention", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+5)
                                              , seed=self.seed, return_sequences=True)
            else:
                self.attention = layers.LSTM(1, activation='sigmoid', name="temp_attention", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+5)
                                          , seed=self.seed, return_sequences=True)

            self.fusion = layers.Dense(self.hidden_dim, activation='relu', name="fusion", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+6))


        self.conv_short.build((None, W, R))
        self.conv_medium.build((None, W, R))
        self.conv_long.build((None, W, R))
        #self.conv_long2.build((None, W, R))
        if not self.use_lstm:
            self.attention.build((None, W, R))
            self.fusion.build((None, R * 3))

        self.bn = layers.GroupNormalization(groups=R, axis=-1)
        self.bn.build(input_shape)


    def _pool(self, h):
        attn = self.attention(h)  # (B, W, 1) - always sigmoid
        attn = attn / (ops.sum(attn, axis=1, keepdims=True) + 1e-6)
        return ops.sum(h * attn, axis=1)  # (B, H)

    def call(self, x):

        #x = self.bn(x)

        if not self.use_lstm:
            cs = self.conv_short(x)
            #cs = cs + cs * 0.1
            s = self._pool(cs)
            cm = self.conv_medium(x)
            #cm = cm + cm * 0.1
            m = self._pool(cm)
            cl = self.conv_long(x)
            #cl = cl + cl * 0.1
            l = self._pool(cl)
        #l2 = self._pool(self.conv_long2(x))
        else:
            s = self.conv_short(x)
            m = self.conv_medium(x)
            l = self.conv_long(x)

        combined = layers.Concatenate(axis=-1, name="regime_multiscale_concat")([s, m, l#, l2
                                                                                ])
        if self.use_lstm:
            fused = self.lstm(combined)
        else:
            fused = self.fusion(combined)  # (B, H)

        return fused


    def compute_output_shape(self, input_shape):
        # input_shape: (batch, window, features)
        return (input_shape[0], self.hidden_dim)

    def get_config(self):
        config = super().get_config()
        config.update({
            "hidden_dim": self.hidden_dim,
            "activation": self.activation,
            "dropout": self.dropout,
            "seed": self.seed,
            "use_lstm": self.use_lstm,
            "temporal_attention_type": self.temporal_attention_type,
        })
        return config



@keras.utils.register_keras_serializable(package="custom")
class RegimeMultiScaleEncoder2D(layers.Layer):
    """(B, A, W, R) -> (B, A) with multi-scale depthwise conv over (W, R)."""

    def __init__(self, hidden_dim=32, seed=42, activation='relu', dropout=0.1, temporal_attention_type="None", **kwargs):
        super().__init__(**kwargs)
        self.hidden_dim = hidden_dim
        self.activation = activation
        self.dropout = dropout
        self.seed = seed

        self.conv_short = None
        self.conv_medium = None
        self.conv_long = None
        self.attention = None
        self.fusion = None
        self.temporal_attention_type = temporal_attention_type

    def build(self, input_shape):
        B, A, W, R = input_shape

        # Depthwise conv over (W, R)
        self.conv_short = layers.DepthwiseConv2D(
            #self.hidden_dim,
            depth_multiplier=1,
            kernel_size=(1, 3),
            padding='same',
            #depth_multiplier=1,
            activation=None,#self.activation,
            name="conv_short",
            #kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed),
            #kernel_initializer=keras.initializers.Orthogonal(seed=self.seed),
            #kernel_regularizer=keras.regularizers.L1(1e-4),
            #kernel_constraint=keras.constraints.MaxNorm(3.0),
            depthwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+2),

        )
        self.conv_short.build((None, None, W, R))

        self.conv_medium = layers.DepthwiseConv2D(
            #self.hidden_dim,
            depth_multiplier=1,
            kernel_size=(1, 7),
            padding='same',
            #depth_multiplier=1,
            activation=None,#self.activation,
            name="conv_medium",
            #kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+1),
            #kernel_initializer=keras.initializers.Orthogonal(seed=self.seed+1),
            #kernel_regularizer=keras.regularizers.L1(1e-4),
            #kernel_constraint=keras.constraints.MaxNorm(3.0),
            depthwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+2),
        )
        self.conv_medium.build((None, None, W, R))

        self.conv_long = layers.DepthwiseConv2D(
            #self.hidden_dim,
            depth_multiplier=1,
            kernel_size=(1, 9),
            dilation_rate=1,
            padding='same',
            #depth_multiplier=1,
            activation=None,#self.activation,
            name="conv_long",
            #kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+2),
            #kernel_initializer=keras.initializers.Orthogonal(seed=self.seed+2),
            #kernel_regularizer=keras.regularizers.L1(1e-4),
            #kernel_constraint=keras.constraints.MaxNorm(3.0),
            depthwise_initializer=keras.initializers.GlorotUniform(seed=self.seed+3),

        )
        self.conv_long.build((None, None, W, R))

        # Attention over W
        if self.temporal_attention_type == "None":
            self.attention = layers.Dense(
                1,
                activation='sigmoid',
                name="attention",
                kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+4),
            )
        elif self.temporal_attention_type == "RNN":
            self.attention = layers.SimpleRNN(1, activation='sigmoid', name="temp_attention", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+4)
                                              , seed=self.seed, return_sequences=True)
        else:
            self.attention = layers.LSTM(1, activation='sigmoid', name="temp_attention", kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+4)
                                              , seed=self.seed, return_sequences=True)

        self.attention.build((None, W, R))

        # Fusion to A
        self.fusion = layers.Dense(
            self.hidden_dim,
            activation='relu',
            name="fusion",
            kernel_initializer=keras.initializers.GlorotUniform(seed=self.seed+5),
        )
        self.fusion.build((None, A, R * 3))

        #self.asset_scores = layers.Dense(1, name="asset_scores_Encoder2D")
        #self.asset_scores.build((None, A, self.hidden_dim))

        self.bn = layers.GroupNormalization(groups=A, axis=1)
        self.bn.build(input_shape)

        super().build(input_shape)


    def _pool(self, h):
        # h: (B, A, W, C)
        B = ops.shape(h)[0]
        A = ops.shape(h)[1]
        W = ops.shape(h)[2]
        C = ops.shape(h)[3]

        # Flatten feature maps per asset: (B, A, W, C) -> (B*A, W, C)
        h_flat = ops.reshape(h, (B * A, W, C))

        attn = self.attention(h_flat)  # (B*A, W, 1)
        attn = attn / (ops.sum(attn, axis=1, keepdims=True) + 1e-6)
        pooled = ops.sum(h_flat * attn, axis=1)  # (B*A, C)

        # Reshape back to (B, A, C)
        return ops.reshape(pooled, (B, A, C))

    def call(self, x):
        # x: (B, A, W, R)
        #x = self.bn(x)
        cs = self.conv_short(x)
        #cs = cs + cs * 0.1
        s = self._pool(cs)
        cm = self.conv_medium(x)
        #cm = cm + cm * 0.1
        m = self._pool(cm)
        cl = self.conv_long(x)
        #cl = cl + cl * 0.1
        l = self._pool(cl)

        combined = ops.concatenate([s, m, l], axis=-1)  # (B, A, 3*C)
        y = self.fusion(combined)                       # (B, A, H)

        #y = self.asset_scores(y)                        # (B, A, 1)
        #y = ops.squeeze(y, axis=-1)

        # If you really want (B, A) as final shape, reduce last dim:
        # e.g., mean over last axis
        #y = ops.mean(y, axis=-1)                        # (B, A)


        return y


    def compute_output_shape(self, input_shape):
        # input_shape: (B, A, W, R)
        return (input_shape[0], input_shape[1], self.hidden_dim)

    def get_config(self):
        config = super().get_config()
        config.update({
            "hidden_dim": self.hidden_dim,
            "activation": self.activation,
            "dropout": self.dropout,
            "seed": self.seed,
            "temporal_attention_type": self.temporal_attention_type,
        })
        return config



