def compute_horizon_quality(y_list, exposures_list=None, eps=1e-8, window=20):
    n_horizons = len(y_list)
    N = y_list[0].shape[0]
    sharpes = np.zeros((N, n_horizons))

    half = window // 2

    for i, y in enumerate(y_list):
        if exposures_list is not None:
            pnl = (y * exposures_list[i]).sum(axis=-1)
        else:
            # Inverse-vol weighting instead of equal weight
            vol = y.std(axis=0, keepdims=True) + eps   # (1, n_assets)
            inv_vol_weights = (1.0 / vol)
            inv_vol_weights /= inv_vol_weights.sum()
            pnl = (y * inv_vol_weights).sum(axis=-1)

        # BOTH use same centered window with proper edge handling
        rolled_mean = np.zeros(N)
        rolled_std = np.zeros(N)

        for t in range(N):
            start = max(0, t - half)
            end = min(N, t + half + 1)
            window_data = pnl[start:end]

            rolled_mean[t] = pnl[t] #window_data.mean()
            rolled_std[t] = pnl.std() + eps

        sharpes[:, i] = rolled_mean / rolled_std

    soft_labels = softmax(sharpes * 5.0, axis=-1)
    return soft_labels.astype("float32")


@keras.utils.register_keras_serializable(package="custom")
class VolScaledPortfolio(layers.Layer):
    def __init__(self, tau=1.0, sharpness=1.0, vol_floor=1e-4, vol_cap=5.0,
                 deadzone=0.02, vol_eps=1e-6, **kwargs):
        super().__init__(**kwargs)
        self.tau = tau
        self.sharpness = sharpness
        self.vol_floor = vol_floor
        self.vol_cap = vol_cap          # NEW: caps inv_vol explosion
        self.deadzone = deadzone
        self.vol_eps = vol_eps

    def soft_deadzone(self, x, eps):
        abs_x = ops.abs(x)
        return ops.sign(x) * ops.maximum(abs_x - eps, 0.0)

    def compute_realized_vol(self, y_window):
        mean = ops.mean(y_window, axis=1, keepdims=True)
        var = ops.mean(ops.square(y_window - mean), axis=1)
        return ops.stop_gradient(ops.sqrt(var + self.vol_eps))

    def call(self, inputs):
        scores, y_window = inputs
        realized_vol = self.compute_realized_vol(y_window)

        r = soft_rank(scores, tau=self.tau)
        raw_target = (r - 0.5) * 2.0 * self.sharpness
        raw_target = raw_target - ops.mean(raw_target, axis=1, keepdims=True)

        inv_vol = 1.0 / ops.maximum(realized_vol, self.vol_floor)
        inv_vol = ops.minimum(inv_vol, self.vol_cap)          # NEW: cap blowups

        scaled = raw_target * inv_vol

        #target = self.soft_deadzone(scaled, self.deadzone)

        l1 = ops.sum(ops.abs(scaled), axis=1, keepdims=True) + 1e-6
        return scaled / l1

    def compute_output_shape(self, input_shape):
        scores_shape, _ = input_shape
        return scores_shape

    def get_config(self):
        config = super().get_config()
        config.update({
            "tau": self.tau, "sharpness": self.sharpness,
            "vol_floor": self.vol_floor, "vol_cap": self.vol_cap,
            "deadzone": self.deadzone, "vol_eps": self.vol_eps,
        })
        return config




@keras.utils.register_keras_serializable(package="custom")
class DynamicGroupedQueryAttention(layers.Layer):
    """
    Stable DGQA: Dynamic Key-Driven Grouped Query Attention
    x: (B, L, D) → y: (B, L, D)

    - Independent seeds per weight (no correlated initializations)
    - Soft key-norm grouping (stable for finance)
    - Deterministic Dropout (seeded via global seed)
    """

    def __init__(
        self,
        num_query_heads,
        num_key_value_heads,
        head_dim,
        dropout=0.0,
        use_bias=True,
        seed=42,
        **kwargs,
    ):
        super().__init__(**kwargs)
        self.num_query_heads = int(num_query_heads)
        self.num_key_value_heads = int(num_key_value_heads)
        self.head_dim = int(head_dim)
        self.dropout = float(dropout)
        self.use_bias = bool(use_bias)
        self.seed = int(seed)

        self.w_q = None
        self.w_k = None
        self.w_v = None
        self.b_q = None
        self.b_k = None
        self.b_v = None
        self.w_o = None
        self.b_o = None

        self.dropout_layer = layers.Dropout(self.dropout)

    def build(self, input_shape):
        d_model = int(input_shape[-1])

        # Q/K/V projections with independent seeds
        self.w_q = self.add_weight(
            shape=(d_model, self.num_query_heads * self.head_dim),
            initializer=keras.initializers.GlorotUniform(seed=self.seed + 1),
            trainable=True,
            name="w_q",
        )
        self.w_k = self.add_weight(
            shape=(d_model, self.num_key_value_heads * self.head_dim),
            initializer=keras.initializers.GlorotUniform(seed=self.seed + 2),
            trainable=True,
            name="w_k",
        )
        self.w_v = self.add_weight(
            shape=(d_model, self.num_key_value_heads * self.head_dim),
            initializer=keras.initializers.GlorotUniform(seed=self.seed + 3),
            trainable=True,
            name="w_v",
        )

        if self.use_bias:
            self.b_q = self.add_weight(
                shape=(self.num_query_heads * self.head_dim,),
                initializer=keras.initializers.Zeros(),
                trainable=True,
                name="b_q",
            )
            self.b_k = self.add_weight(
                shape=(self.num_key_value_heads * self.head_dim,),
                initializer=keras.initializers.Zeros(),
                trainable=True,
                name="b_k")

            self.b_v = self.add_weight(
                shape=(self.num_key_value_heads * self.head_dim,),
                initializer=keras.initializers.Zeros(),
                trainable=True,
                name="b_v",
            )
        else:
            self.b_q = None
            self.b_k = None
            self.b_v = None

        # Output projection
        self.w_o = self.add_weight(
            shape=(self.num_query_heads * self.head_dim, d_model),
            initializer=keras.initializers.GlorotUniform(seed=self.seed + 4),
            trainable=True,
            name="w_o",
        )
        if self.use_bias:
            self.b_o = self.add_weight(
                shape=(d_model,),
                initializer=keras.initializers.Zeros(),
                trainable=True,
                name="b_o",
            )
        else:
            self.b_o = None

        super().build(input_shape)

    def _project_qkv(self, x):
        # x: (B, L, D)
        q = ops.matmul(x, self.w_q)
        k = ops.matmul(x, self.w_k)
        v = ops.matmul(x, self.w_v)

        if self.use_bias:
            q = q + self.b_q
            k = k + self.b_k
            v = v + self.b_v

        B = ops.shape(x)[0]
        L = ops.shape(x)[1]
        Hq = self.num_query_heads
        Hkv = self.num_key_value_heads
        d = self.head_dim

        q = ops.reshape(q, (B, L, Hq, d))
        k = ops.reshape(k, (B, L, Hkv, d))
        v = ops.reshape(v, (B, L, Hkv, d))

        q = ops.transpose(q, (0, 2, 1, 3))   # (B, Hq, L, d)
        k = ops.transpose(k, (0, 2, 1, 3))   # (B, Hkv, L, d)
        v = ops.transpose(v, (0, 2, 1, 3))   # (B, Hkv, L, d)

        return q, k, v

    def _soft_group_weights(self, k):
        """
        Richer, optimal KV-head weighting using:
        - mean(k_norm)          → signal strength
        - std(k_norm)           → dispersion / richness
        - entropy(p)            → diversification
        - concentration index C → tail penalty (scale-free)
        """

        # k: (B, Hkv, L, d)
        k_norm = ops.sqrt(ops.sum(ops.square(k), axis=-1) + 1e-6)  # (B, Hkv, L)

        # ---------------------------------------------------------
        # 1. Mean (signal strength)
        # ---------------------------------------------------------
        mean = ops.mean(k_norm, axis=-1)  # (B, Hkv)

        # ---------------------------------------------------------
        # 2. Std (cross-sectional dispersion)
        # ---------------------------------------------------------
        std = ops.std(k_norm, axis=-1)    # (B, Hkv)

        # ---------------------------------------------------------
        # 3. Entropy (diversification)
        # ---------------------------------------------------------
        p = k_norm / (ops.sum(k_norm, axis=-1, keepdims=True) + 1e-6)  # (B, Hkv, L)
        entropy = -ops.sum(p * ops.log(p + 1e-6), axis=-1)             # (B, Hkv)

        # ---------------------------------------------------------
        # 4. Concentration index C (optimal tail penalty)
        # ---------------------------------------------------------
        # C = 1 - H / log(L)
        L = ops.cast(ops.shape(k_norm)[-1], entropy.dtype)
        C = 1.0 - entropy / (ops.log(L + 1e-6))  # (B, Hkv)

        # ---------------------------------------------------------
        # Combine signals
        # ---------------------------------------------------------
        # Recommended stable coefficients for finance
        alpha = 0.5   # std weight
        beta  = 0.3   # entropy weight
        gamma = 0.4   # concentration penalty weight

        base_scores = (
            mean
            + alpha * std
            #+ beta  * entropy
            - gamma * C
        )

        # ---------------------------------------------------------
        # Softmax over KV heads
        # ---------------------------------------------------------
        return keras.activations.softmax(base_scores, axis=-1)


    def call(self, x, training=None):
        q, k, v = self._project_qkv(x)

        B = ops.shape(x)[0]
        L = ops.shape(x)[1]
        Hq = self.num_query_heads
        Hkv = self.num_key_value_heads

        # Grouping weights over KV heads
        weights = self._soft_group_weights(k)          # (B, Hkv)
        w_exp = ops.expand_dims(weights, axis=-1)      # (B, Hkv, 1)
        w_exp = ops.expand_dims(w_exp, axis=-1)        # (B, Hkv, 1, 1)

        # Weighted KV
        k_weighted = k * w_exp                         # (B, Hkv, L, d)
        v_weighted = v * w_exp                         # (B, Hkv, L, d)

        w_sum = ops.sum(w_exp, axis=1, keepdims=True) + 1e-6  # (B, 1, 1, 1)
        k_eff = ops.sum(k_weighted, axis=1, keepdims=True) / w_sum  # (B, 1, L, d)
        v_eff = ops.sum(v_weighted, axis=1, keepdims=True) / w_sum  # (B, 1, L, d)

        # Tile effective KV for all Q heads
        k_eff = ops.tile(k_eff, (1, Hq, 1, 1))         # (B, Hq, L, d)
        v_eff = ops.tile(v_eff, (1, Hq, 1, 1))         # (B, Hq, L, d)

        scale = 1.0 / tf.sqrt(tf.cast(self.head_dim, tf.float32))
        attn_scores = ops.matmul(
            q, ops.transpose(k_eff, (0, 1, 3, 2))
        ) * scale                                      # (B, Hq, L, L)

        attn_weights = keras.activations.softmax(attn_scores, axis=-1)
        attn_weights = self.dropout_layer(attn_weights, training=training)

        attn_output = ops.matmul(attn_weights, v_eff)  # (B, Hq, L, d)

        attn_output = ops.transpose(attn_output, (0, 2, 1, 3))      # (B, L, Hq, d)
        attn_output = ops.reshape(attn_output, (B, L, Hq * self.head_dim))  # (B, L, D)

        y = ops.matmul(attn_output, self.w_o)          # (B, L, D)
        if self.use_bias and self.b_o is not None:
            y = y + self.b_o

        return y

    def compute_output_shape(self, input_shape):
        return input_shape

    def get_config(self):
        config = super().get_config()
        config.update(
            {
                "num_query_heads": self.num_query_heads,
                "num_key_value_heads": self.num_key_value_heads,
                "head_dim": self.head_dim,
                "dropout": self.dropout,
                "use_bias": self.use_bias,
                "seed": self.seed,
            }
        )
        return config



# Option 1: train_step override (exact gradient norm, recommended)
# ---------------------------------------------------------------------
@keras.saving.register_keras_serializable()
class ZenithModel(keras.Model):
    """A keras.Model that applies the ZENITH LR schedule using the true
    global gradient norm computed each training step."""

    def zenith_init(self, eta0: float, window: int = 5000):
        self.zenith_eta0 = tf.constant(eta0, dtype=tf.float32)
        self.zenith_W = window
        # Circular buffer of gradient norms + running sum for O(1) rolling mean
        self.zenith_queue = tf.Variable(
            tf.zeros([window], dtype=tf.float32), trainable=False
        )
        self.zenith_count = tf.Variable(0, dtype=tf.int32, trainable=False)  # steps seen (capped at W)
        self.zenith_ptr = tf.Variable(0, dtype=tf.int32, trainable=False)    # write pointer
        self.zenith_sum = tf.Variable(0.0, dtype=tf.float32, trainable=False)
        self.zenith_Z = tf.Variable(0.0, dtype=tf.float32, trainable=False)

    def train_step(self, data):
        # Standard Keras 3-tuple unpacking: works for single or multiple
        # inputs/outputs, since x/y/sample_weight can each be a list, dict,
        # or plain tensor -- Keras handles the structure transparently as
        # long as it matches what you pass into model.fit(...).
        x, y, sample_weight = keras.utils.unpack_x_y_sample_weight(data)

        with tf.GradientTape() as tape:
            y_pred = self(x, training=True)
            loss = self.compute_loss(
                x=x, y=y, y_pred=y_pred, sample_weight=sample_weight
            )

        self._loss_tracker.update_state(loss)

        trainable_vars = self.trainable_variables
        gradients = tape.gradient(loss, trainable_vars)

        # --- Global L2 gradient norm (pooled across ALL outputs/heads) ---
        grad_norm = tf.linalg.global_norm(gradients)

        # --- Update rolling window (circular buffer) ---
        old_val = self.zenith_queue[self.zenith_ptr]
        is_full = tf.cast(self.zenith_count >= self.zenith_W, tf.float32)
        # subtract the value being overwritten only once the buffer has wrapped
        self.zenith_sum.assign_add(grad_norm - old_val * is_full)
        self.zenith_queue.scatter_nd_update([[self.zenith_ptr]], [grad_norm])
        self.zenith_ptr.assign((self.zenith_ptr + 1) % self.zenith_W)
        self.zenith_count.assign(tf.minimum(self.zenith_count + 1, self.zenith_W))

        # --- Compute LR only once window is full, else keep eta0 ---
        denom = tf.cast(self.zenith_count, tf.float32)
        mu = self.zenith_sum / denom

        window_full = self.zenith_count >= self.zenith_W

        def apply_decay():
            new_Z = tf.maximum(self.zenith_Z, mu)
            self.zenith_Z.assign(new_Z)
            eta = self.zenith_eta0 * (mu / new_Z)
            return eta

        eta = tf.cond(window_full, apply_decay, lambda: self.zenith_eta0)
        self.optimizer.learning_rate.assign(eta)

        # --- Apply gradients as usual ---
        self.optimizer.apply_gradients(zip(gradients, trainable_vars))

        # --- Update metrics (handles dict/list multi-output automatically) ---
        self.compute_metrics(x, y, y_pred, sample_weight)

        results = {m.name: m.result() for m in self.metrics}
        results["lr"] = eta
        return results

    def get_config(self):
        config = super().get_config()
        config.update({
            "zenith_eta0": float(self.zenith_eta0.numpy()),
            "zenith_W": int(self.zenith_W),
        })
        return config

    @classmethod
    def from_config(cls, config):
        # Step 1: Let Keras reconstruct the functional graph
        obj = super(ZenithModel, cls).from_config(config)

        # Step 2: Reinitialize Zenith LR buffers
        obj.zenith_init(
            eta0=config["zenith_eta0"],
            window=config["zenith_W"]
        )

        return obj



@keras.utils.register_keras_serializable(package="custom")
class GraphAttentionFC(layers.Layer):
    def __init__(self, hidden_dim, k_pos=10, k_neg=10, dropout=0.0, seed=42, **kwargs):
        super().__init__(**kwargs)
        self.hidden_dim = hidden_dim
        self.k_pos = k_pos
        self.k_neg = k_neg
        self.dropout_rate = dropout
        self.seed = seed

        self.phi = keras.Sequential([
            layers.Dense(hidden_dim, activation="relu", kernel_initializer=keras.initializers.GlorotUniform(seed=seed)),
            layers.Dense(hidden_dim, activation="relu", kernel_initializer=keras.initializers.GlorotUniform(seed=seed)),
        ])
        self.att_mlp = keras.Sequential([
            layers.Dense(hidden_dim, activation="relu", kernel_initializer=keras.initializers.GlorotUniform(seed=seed)),
            layers.Dense(hidden_dim, activation="relu", kernel_initializer=keras.initializers.GlorotUniform(seed=seed)),
            layers.Dense(1, kernel_initializer=keras.initializers.GlorotUniform(seed=seed))
        ])
        self.out_proj = layers.Dense(hidden_dim, kernel_initializer=keras.initializers.GlorotUniform(seed=seed))
        self.dropout = layers.Dropout(dropout, seed=seed)


    # ---------------------------------------------------------
    # BUILD
    # ---------------------------------------------------------
    def build(self, input_shape):
        # x: (B, A, F)
        self.A = input_shape[1]
        self.F = input_shape[2]
        self.K = self.k_pos + self.k_neg

        # --- Explicitly build each sublayer ---
        # phi: takes (B, A, F)
        self.phi.build(input_shape)

        # att_mlp: takes pair (B, A, K, 2H)
        # we only know H = hidden_dim here, so:
        att_input_shape = (input_shape[0], self.A, self.K, 2 * self.hidden_dim)
        self.att_mlp.build(att_input_shape)

        # out_proj: takes (B, A, H)
        out_input_shape = (input_shape[0], self.A, self.hidden_dim)
        self.out_proj.build(out_input_shape)

        # dropout: same as out_proj
        self.dropout.build(out_input_shape)

        super().build(input_shape)

    # ---------------------------------------------------------
    # CALL
    # ---------------------------------------------------------
    def call(self, x):
        # x: (B, A, F)
        B = ops.shape(x)[0]
        A = self.A

        h = self.phi(x)  # (B, A, H) -- embeddings used for the actual attention/output

        # -----------------------------------------------------
        # 1) Per-sample asset-to-asset correlation, computed from x
        #    (cosine-similarity-style correlation across the F axis)
        # -----------------------------------------------------
        x_centered = x - ops.mean(x, axis=-1, keepdims=True)           # (B, A, F)
        x_std = ops.std(x, axis=-1, keepdims=True) + 1e-6
        x_norm = x_centered / x_std                                     # (B, A, F)

        # (B, A, A) pearson-style correlation between every pair of assets, per sample
        corr = ops.matmul(x_norm, ops.transpose(x_norm, axes=[0, 2, 1])) / ops.cast(self.F, "float32")

        # -----------------------------------------------------
        # 2) Mask out self-correlation (diagonal) so an asset never
        #    picks itself as a "neighbor"
        # -----------------------------------------------------
        eye = ops.eye(A, dtype="float32")            # (A, A)
        diag_penalty = eye * 1e4                       # push diagonal far outside [-1, 1] range
        diag_penalty = ops.expand_dims(diag_penalty, axis=0)  # (1, A, A) -> broadcasts over batch

        corr_for_pos = corr - diag_penalty   # self can't win the "most positive" top-k
        corr_for_neg = corr + diag_penalty   # self can't win the "most negative" top-k

        # -----------------------------------------------------
        # 3) Dynamic top-k neighbor selection, per sample, per asset
        # -----------------------------------------------------
        _, pos_idx = ops.top_k(corr_for_pos, k=self.k_pos, sorted=False)   # (B, A, k_pos)
        _, neg_idx = ops.top_k(-corr_for_neg, k=self.k_neg, sorted=False)  # (B, A, k_neg)

        neighbor_idx = ops.concatenate([pos_idx, neg_idx], axis=-1)  # (B, A, K), int, per-sample

        # -----------------------------------------------------
        # 4) Gather each asset's K neighbor embeddings (batched gather:
        #    indices differ per batch sample AND per asset)
        # -----------------------------------------------------
        h_neighbors = tf.gather(h, neighbor_idx, axis=1, batch_dims=1)  # (B, A, K, H)

        # -----------------------------------------------------
        # 5) Attention over just those K dynamic neighbors
        # -----------------------------------------------------
        h_i = ops.expand_dims(h, axis=2)                                       # (B, A, 1, H)
        h_i = ops.broadcast_to(h_i, (B, A, self.K, self.hidden_dim))           # (B, A, K, H)

        pair = ops.concatenate([h_i, h_neighbors], axis=-1)  # (B, A, K, 2H)

        logits = self.att_mlp(pair)            # (B, A, K, 1)
        logits = ops.squeeze(logits, axis=-1)   # (B, A, K)
        weights = ops.softmax(logits, axis=-1)  # (B, A, K)

        out = ops.sum(ops.expand_dims(weights, -1) * h_neighbors, axis=2)  # (B, A, H)

        out = self.out_proj(out)
        out = self.dropout(out)
        return out

    # ---------------------------------------------------------
    # OUTPUT SHAPE
    # ---------------------------------------------------------
    def compute_output_shape(self, input_shape):
        return (input_shape[0], input_shape[1], self.hidden_dim)

    # ---------------------------------------------------------
    # CONFIG
    # ---------------------------------------------------------
    def get_config(self):
        config = super().get_config()
        config.update({
            "hidden_dim": self.hidden_dim,
            "k_pos": self.k_pos,
            "k_neg": self.k_neg,
            "dropout": self.dropout_rate,
            "seed": self.seed,
        })
        return config

    @classmethod
    def from_config(cls, config):
        return cls(**config)



@keras.utils.register_keras_serializable(package="custom")
class MultiHorizonVol(layers.Layer):
    """
    (B, W, A) -> (B, A, H)
    Multi-horizon EGARCH + GJR volatility extractor.
    """

    def __init__(self, horizons=(0, 5, 15), seed=42, **kwargs):
        super().__init__(**kwargs)
        self.horizons = list(horizons)
        self.seed = seed

    def build(self, input_shape):
        B, W, A = input_shape
        H = len(self.horizons)

        self.omega = self.add_weight(
            shape=(A, H),
            initializer=keras.initializers.GlorotUniform(self.seed),
            name="omega"
        )
        self.alpha = self.add_weight(
            shape=(A, H),
            initializer=keras.initializers.GlorotUniform(self.seed+1),
            name="alpha"
        )
        self.gamma = self.add_weight(
            shape=(A, H),
            initializer=keras.initializers.GlorotUniform(self.seed+2),
            name="gamma"
        )
        self.beta = self.add_weight(
            shape=(A, H),
            initializer=keras.initializers.GlorotUniform(self.seed+3),
            name="beta"
        )

        super().build(input_shape)

    def call(self, x):
        r = x
        r2 = ops.square(r)
        I_neg = ops.cast(r < 0.0, r.dtype)

        B, W, A = x.shape
        H = len(self.horizons)

        vols = []

        for h_idx, win in enumerate(self.horizons):
            sigma2 = ops.mean(r2[:, :min(3, win), :], axis=1)

            for t in range(1, W):
                sigma2 = ops.softplus(
                    self.omega[:, h_idx]
                    + self.alpha[:, h_idx] * r2[:, t-1, :]
                    + self.gamma[:, h_idx] * r2[:, t-1, :] * I_neg[:, t-1, :]
                    + self.beta[:, h_idx]  * sigma2
                )

            vols.append(ops.sqrt(sigma2))

        return ops.stack(vols, axis=-1)  # (B, A, H)

    def get_config(self):
        config = super().get_config()
        config.update({
            "horizons": self.horizons,
            "seed": self.seed,
        })
        return config

    @classmethod
    def from_config(cls, config):
        return cls(**config)


# =============================================================================
# Main model builder
# =============================================================================

def build_cross_sectional_mixer_lstm2(
    n_assets,
    n_onchain_features,
    n_macro_features,
    dropout=0.1,
    activation="relu",
    gate_activation="sigmoid",
    temporal_activation="tanh",
    output_activation="tanh",
    dim_temporal_volume=16,
    dim_temporal_regime=16,
    hidden_dim=64,
    head_num=2,
    tau=1.0,
    seed=42,
    sharpness=10.0,
    n_vol_features=0,
    initial_lr=1e-3,
    kernel_size=3,
    w_decay=1e-4,
    n_features=0,
    window=1,
    deadzone=0.02,
    temporal_attention_type="None",
    gate=False,
    use_lstm=False,
    # --- multi-horizon config ---
    horizons=("h1"
              , "h3"
              , "h7"
              , "h10"
              , "h13"
              , "h17"
              , "h24"),
    horizon_loss_weights=(0.1
                          , 0.08
                          , 0.07
                          , 0.06
                          , 0.055
                          , 0.05
                          , 0.045),
    blend_supervision_weight=0.1,    # weight for the blend-weights auxiliary loss
):
    """
    Cross-sectional mixer with DYNAMIC multi-horizon blending.

    Architecture overview
    ---------------------
    1. Shared backbone (same as before) produces per-asset embeddings `h`.
    2. One score head per horizon → horizon_scores: list of (B, A) tensors.
    3. Meta-network reads:
         - cross-sectional mean & std of each horizon's scores  (regime-free signal strength)
         - temporal_context                                       (regime)
       and produces softmax blend_weights (B, n_horizons).
       This is FULLY DYNAMIC at inference — no future returns needed.
    4. Weighted sum of horizon scores → scores_final → single SoftQuantilePortfolio.
    5. Auxiliary outputs:
         - one SoftQuantilePortfolio per horizon  (supervised with horizon-specific y)
         - blend_weights output                   (supervised with quality soft-labels)

    Training targets expected in model.fit(y={...})
    ------------------------------------------------
        "exposures"            : future returns at primary horizon, shape (N, n_assets)
        "exposures_h1"         : future returns at horizon 1,       shape (N, n_assets)
        "exposures_h3"         : future returns at horizon 2,       shape (N, n_assets)
        "exposures_h5"         : future returns at horizon 3,       shape (N, n_assets)
        "blend_weights_target" : soft quality labels,               shape (N, n_horizons)
                                 computed via compute_horizon_quality()

    Inference
    ---------
        preds = model.predict(x_dict)
        weights = preds["exposures"]   # (N, n_assets) — the only output you need

    Args:
        horizons                 : tuple of horizon names.
        horizon_loss_weights     : loss weight for each auxiliary horizon head.
        blend_supervision_weight : loss weight for the blend_weights_target head.
                                   Keep small (0.05–0.2) so it regularizes without dominating.
    """

    n_horizons = len(horizons)
    assert len(horizon_loss_weights) == n_horizons

    # -------------------------------------------------------------------------
    # Inputs
    # -------------------------------------------------------------------------
    asset_features = keras.Input(shape=(n_assets, n_features),     name="asset_features")
    regime_onchain = keras.Input(shape=(n_onchain_features,),       name="regime_onchain")
    regime_macro   = keras.Input(shape=(n_macro_features,),         name="regime_macro")
    lag_abs_ret    = keras.Input(shape=(n_assets,),                 name="lagged_absolute_returns")
    lag_mkt_ret    = keras.Input(shape=(n_assets,),                 name="lagged_market_returns")
    y_window       = keras.Input(shape=(window, n_assets),            name="y_market_rel_window")
    x_window_reg   = keras.Input(shape=(window, n_onchain_features),  name="x_window")
    vol            = keras.Input(shape=(n_assets, window, n_vol_features),      name="vol")

    # -------------------------------------------------------------------------
    # TemporalToScalar for y_window
    # -------------------------------------------------------------------------
    last_y = TemporalToScalar(
        kernel_size=kernel_size,
        activation=temporal_activation,
        name="y_temporal",
        seed=seed
    )(y_window)  # (B, A)

    # -------------------------------------------------------------------------
    # Regime Multi-Scale Encoder
    # -------------------------------------------------------------------------
    regime_temporal = RegimeMultiScaleEncoder(
        hidden_dim=dim_temporal_regime,
        activation=temporal_activation,
        temporal_attention_type=temporal_attention_type,
        use_lstm=use_lstm,
        dropout=dropout,
        name="regime_multi_scale",
        seed=seed
    )(x_window_reg)  # (B, H/2)


    volume_temporal = RegimeMultiScaleEncoder2D(
        #num_heads=max(1, head_num//2),
        hidden_dim=dim_temporal_volume,
        activation=temporal_activation,
        dropout=dropout,
        temporal_attention_type=temporal_attention_type,
        name="regime_multi_scale_vol",
        seed=seed
    )(vol)  # (B, H/2)


    if gate:

        g1 = layers.Dense(dim_temporal_volume, activation='sigmoid', name="vol_gate",kernel_initializer=keras.initializers.GlorotUniform(seed=seed+51))
        #main = layers.Dense(n_vol_features, activation='linear', name="vol_main", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+6))
        volume_temporal = volume_temporal * g1(volume_temporal)

        gate2 = layers.Dense(dim_temporal_regime, activation='sigmoid', name="chain_gate",kernel_initializer=keras.initializers.GlorotUniform(seed=seed+50))
        regime_temporal = regime_temporal * gate2(regime_temporal)

        gate3 = layers.Dense(n_assets, activation='sigmoid', name="y_gate",kernel_initializer=keras.initializers.GlorotUniform(seed=seed+52))
        last_y = last_y * gate3(last_y)

    # -------------------------------------------------------------------------
    # Volume Multi-Scale Encoder
    # -------------------------------------------------------------------------
    #volume_temporal = VolumeMultiScaleEncoder(
    #    kernel_size=kernel_size,
    #    hidden_dim=hidden_dim // 2,
    #    activation=temporal_activation,
    #    #dropout=dropout,
    #    name="volume_multi_scale",
    #)(vol)  # (B, H/2)

    #VOLATILITY FEATURES
    mean = ops.mean(y_window, axis=1, keepdims=True)     # (B, 1, A)
    y_var = ops.mean(ops.square(y_window - mean), axis=1) # (B, A)

    # -------------------------------------------------------------------------
    # Per-asset scalar features
    # -------------------------------------------------------------------------
    per_asset_scalar = ops.stack(
        [lag_abs_ret, lag_mkt_ret, last_y, y_var], axis=-1
    )  # (B, A, 3)

    x_asset = layers.Concatenate(axis=-1, name="asset_concat")(
        [asset_features, per_asset_scalar]
    )
    x_asset = layers.Dense(hidden_dim, activation=activation, name="per_asset_proj", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+7))(x_asset)
    x_asset = layers.LayerNormalization(axis=-1, name="per_asset_ln")(x_asset)
    x_asset = layers.Dropout(dropout, name="per_asset_dropout", seed=seed)(x_asset)  # (B, A, H)

    x_asset = layers.Concatenate(axis=-1, name="asset_concat_temporal")([x_asset, volume_temporal])

    # -------------------------------------------------------------------------
    # Regime point-in-time features
    # -------------------------------------------------------------------------
    r_on  = layers.Dense(hidden_dim, activation=activation, name="regime_on_proj", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+8))(regime_onchain)
    r_mac = layers.Dense(hidden_dim, activation=activation, name="regime_mac_proj", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+9))(regime_macro)

    # -------------------------------------------------------------------------
    # Temporal context fusion
    # -------------------------------------------------------------------------
    temporal_context = layers.concatenate(
        [r_on, r_mac, regime_temporal], axis=-1
    )
    temporal_context = layers.Dense(hidden_dim, activation=activation, name="temporal_fusion", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+10))(temporal_context)
    temporal_context = layers.LayerNormalization(name="temporal_fusion_ln")(temporal_context)
    temporal_context = layers.Dropout(dropout, name="temporal_fusion_dropout", seed=seed)(temporal_context)  # (B, H)

    # -------------------------------------------------------------------------
    # Broadcast temporal context to all assets and combine
    # -------------------------------------------------------------------------
    temporal_broadcast = ops.expand_dims(temporal_context, axis=1)  # (B, 1, H)
    temporal_broadcast = temporal_broadcast * ops.ones_like(x_asset[..., :1])  # broadcasts to (B, A, H)

    x = layers.Concatenate(axis=-1, name="asset_temporal_concat")(
        [x_asset, temporal_broadcast]
    )  # (B, A, 2H)
    x = layers.Dense(hidden_dim, activation=activation, name="combined_proj", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+11))(x)
    x = layers.LayerNormalization(axis=-1, name="combined_ln")(x)
    x = layers.Dropout(dropout, name="combined_dropout", seed=seed+12)(x)  # (B, A, H)

    # -------------------------------------------------------------------------
    # Multi-Head Attention
    # -------------------------------------------------------------------------
    if head_num > 0 and head_num<=2:
        attn_out = layers.MultiHeadAttention(
            num_heads=head_num,
            key_dim=hidden_dim // max(1, head_num),
            dropout=dropout,
            name="cross_asset_mha",
        )(x, x)
        attn_out = layers.Dropout(dropout, name="mha_dropout")(attn_out)
        x = layers.Add(name="mha_residual")([x, attn_out])
        x = layers.LayerNormalization(axis=-1, name="mha_ln")(x)

    elif head_num==0:
        attn_out = GraphAttentionFC(hidden_dim, dropout=dropout, seed=seed+13)(x)
        attn_out = layers.Dropout(dropout, name="mha_dropout")(attn_out)
        x = layers.Add(name="mha_residual")([x, attn_out])
        x = layers.LayerNormalization(axis=-1, name="mha_ln")(x)

    #if head_num > 0:
    #    x = SAB(hidden_dim=hidden_dim,
    #            num_heads=head_num,
    #            dropout=dropout,
    #            name="cross_asset_sab")(x)

    # -------------------------------------------------------------------------
    # 2‑Layer DGQA Block (Production‑Ready)
    # -------------------------------------------------------------------------
    #if head_num > 0:
    #    num_query_heads     = head_num            # e.g. 4
    #    num_key_value_heads = max(1, head_num // 2)  # e.g. 2
    #    head_dim            = hidden_dim // num_query_heads  # e.g. 16

        # -------------------------
        # DGQA Layer 1
        # -------------------------
        #dgqa1 = DynamicGroupedQueryAttention(
        #    num_query_heads=num_query_heads,
        #    num_key_value_heads=num_key_value_heads,
        #    head_dim=head_dim,
        #    dropout=dropout,
        #    use_bias=True,
        #    seed=seed + 100,   # independent seed for layer 1
        #    name="cross_asset_dgqa_1",
        #)(x)

        #dgqa1 = layers.Dropout(dropout, seed=seed + 101, name="dgqa1_dropout")(dgqa1)
        #x = layers.Add(name="dgqa1_residual")([x, dgqa1])
        #x = layers.LayerNormalization(axis=-1, name="dgqa1_ln")(x)

        # -------------------------
        # DGQA Layer 2
        # -------------------------
        #dgqa2 = DynamicGroupedQueryAttention(
        #    num_query_heads=num_query_heads,
        #    num_key_value_heads=num_key_value_heads,
        #    head_dim=head_dim,
        #    dropout=dropout,
        #    use_bias=True,
        #    seed=seed + 200,   # independent seed for layer 2
        #    name="cross_asset_dgqa_2",
        #)(x)
        #dgqa2 = layers.Dropout(dropout, seed=seed + 201, name="dgqa2_dropout")(dgqa2)
        #x = layers.Add(name="dgqa2_residual")([x, dgqa2])
        #x = layers.LayerNormalization(axis=-1, name="dgqa2_ln")(x)

        #attn_out = layers.MultiHeadAttention(
        #    num_heads=head_num,
        #    key_dim=hidden_dim // max(1, head_num),
        #    dropout=dropout,
        #    name="cross_asset_mha",
        #)(x, x)
        #attn_out = layers.Dropout(dropout, name="mha_dropout")(attn_out)
        #x = layers.Add(name="mha_residual")([x, attn_out])
        #x = layers.LayerNormalization(axis=-1, name="mha_ln")(x)

    elif head_num > 2:
        num_query_heads     = head_num            # e.g. 4
        num_key_value_heads = max(1, head_num // 2)  # e.g. 2
        head_dim            = hidden_dim // num_query_heads  # e.g. 16

        # -------------------------
        # GQA Layer 1 (native Keras)
        # -------------------------
        gqa1 = layers.GroupQueryAttention(
            num_query_heads=num_query_heads,
            num_key_value_heads=num_key_value_heads,
            head_dim=head_dim,
            dropout=dropout,
            use_bias=True,
            kernel_initializer=keras.initializers.GlorotUniform(seed=seed + 1),
            bias_initializer="zeros",
            name="cross_asset_gqa_1",
        )(query=x, value=x)

        gqa1 = layers.Dropout(dropout, seed=seed + 2, name="gqa1_dropout")(gqa1)
        x = layers.Add(name="gqa1_residual")([x, gqa1])
        x = layers.LayerNormalization(axis=-1, name="gqa1_ln")(x)

        attn_out = layers.MultiHeadAttention(
           num_heads=head_num,
           key_dim=hidden_dim // max(1, head_num),
           dropout=dropout,
           name="cross_asset_mha",
        )(x, x)
        attn_out = layers.Dropout(dropout, name="mha_dropout")(attn_out)
        x = layers.Add(name="mha_residual")([x, attn_out])
        x = layers.LayerNormalization(axis=-1, name="mha_ln")(x)

        # -------------------------
        # GQA Layer 2 (native Keras)
        # -------------------------
        # gqa2 = layers.GroupQueryAttention(
        #     num_query_heads=num_query_heads,
        #     num_key_value_heads=num_key_value_heads,
        #     head_dim=head_dim,
        #     dropout=dropout,
        #     use_bias=True,
        #     kernel_initializer=keras.initializers.GlorotUniform(seed=seed + 200),
        #     bias_initializer="zeros",
        #     name="cross_asset_gqa_2",
        # )(query=x, value=x)
        #
        # gqa2 = layers.Dropout(dropout, seed=seed + 3, name="gqa2_dropout")(gqa2)
        # x = layers.Add(name="gqa2_residual")([x, gqa2])
        # x = layers.LayerNormalization(axis=-1, name="gqa2_ln")(x)

    # -------------------------------------------------------------------------
    # MLP Mixer — shared backbone, all horizon heads branch from here
    # -------------------------------------------------------------------------
    h = layers.Dense(hidden_dim * 2, activation=activation, name="mlp1", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+14))(x)
    h = layers.Dropout(dropout, name="mlp1_dropout", seed=seed)(h)
    h = layers.Dense(hidden_dim, activation=activation, name="mlp2", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+15))(h)
    h = layers.LayerNormalization(axis=-1, name="mlp_ln")(h)
    h = layers.Dropout(dropout, name="mlp2_dropout", seed=seed+16)(h)  # (B, A, H)

    # -------------------------------------------------------------------------
    # Multi-horizon score heads (one Dense per horizon, shared backbone)
    # -------------------------------------------------------------------------
    horizon_scores = []  # list of (B, A) tensors

    for hname in horizons:
        raw = layers.Dense(1, name=f"scores_dense_{hname}", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+17))(h)         # (B, A, 1)
        if output_activation is not None:
            s = layers.Activation(output_activation, name=f"scores_act_{hname}")(raw)
        else:
            s = raw
        s = ops.squeeze(s, axis=-1)                                     # (B, A)
        horizon_scores.append(s)

    # -------------------------------------------------------------------------
    # Meta-network: dynamic blend weights (Option D + B)
    #
    # Inputs to meta-network:
    #   1. cross-sectional mean of each horizon's scores → "how strong is the
    #      average signal this horizon is producing right now?"
    #   2. cross-sectional std  of each horizon's scores → "how dispersed /
    #      confident is this horizon's cross-section?"
    #   3. temporal_context → current regime
    #
    # All three are available at inference — no future returns needed.
    # -------------------------------------------------------------------------
    stacked_scores = ops.stack(horizon_scores, axis=-1)   # (B, A, n_horizons)

    score_mean = ops.mean(stacked_scores, axis=1)         # (B, n_horizons)
    score_std  = ops.std(stacked_scores, axis=1)          # (B, n_horizons)

    meta_input = layers.concatenate(
        [score_mean, score_std, temporal_context], axis=-1
    )  # (B, n_horizons*2 + H)

    meta_h = layers.Dense(hidden_dim, activation=activation, name="meta_h1", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+18))(meta_input)
    meta_h = layers.Dropout(dropout, name="meta_dropout", seed=seed)(meta_h)
    meta_h = layers.Dense(hidden_dim // 2, activation=activation, name="meta_h2", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+19))(meta_h)

    blend_logits  = layers.Dense(n_horizons, name="meta_blend_logits", kernel_initializer=keras.initializers.GlorotUniform(seed=seed+20))(meta_h)  # (B, n_horizons)

    # This is also an OUTPUT so it can be supervised with horizon quality labels
    blend_weights = layers.Softmax(name="blend_weights_target")(blend_logits)   # (B, n_horizons)

    # -------------------------------------------------------------------------
    # Weighted sum of horizon scores → final score
    # blend_weights: (B, n_horizons) → expand to (B, 1, n_horizons)
    # stacked_scores: (B, A, n_horizons)
    # result: (B, A)
    # -------------------------------------------------------------------------
    blend_weights_exp = ops.expand_dims(blend_weights, axis=1)           # (B, 1, n_horizons)
    scores_final      = ops.sum(stacked_scores * blend_weights_exp, axis=-1)  # (B, A)

    #asset_blend = ops.softmax(stacked_scores, axis=-1)  # (B, A, n_horizons)
    #entropy = -ops.sum(asset_blend * ops.log(asset_blend + 1e-8), axis=-1)  # (B, A)
    #agreement = ops.sigmoid(-entropy)
    #adaptive_sharpness = 0.5 + 0.4 * (1.0 - agreement)

    # -------------------------------------------------------------------------
    # Main portfolio output — single SoftQuantilePortfolio (used at inference)
    # -------------------------------------------------------------------------
    scores_normed = CrossSectionalNorm(name="scores_csn")(scores_final)
    exposures = SoftQuantilePortfolio(
        tau=tau,
        sharpness=sharpness / 10.0,
        name="exposures_sqportfolio",
        deadzone=deadzone
    )([scores_normed#, adaptive_sharpness
      ])  # (B, A)


    # -------------------------------------------------------------------------
    # Auxiliary horizon outputs (training scaffolding only)
    # Each horizon score gets its own CSN + SoftQuantilePortfolio so it can
    # be directly supervised with horizon-specific future returns.
    # -------------------------------------------------------------------------
    aux_outputs = {}

    for hname, s in zip(horizons, horizon_scores):
        s_norm  = CrossSectionalNorm(name=f"csn_{hname}")(s)
        exp_aux = SoftQuantilePortfolio(
            tau=tau,
            sharpness=sharpness / 10.0,
            name=f"exposures_{hname}",
        )(s_norm)
        aux_outputs[f"exposures_{hname}"] = exp_aux

    # -------------------------------------------------------------------------
    # Model
    # -------------------------------------------------------------------------
    model = ZenithModel(inputs=[
            asset_features,
            regime_onchain,
            regime_macro,
            lag_abs_ret,
            lag_mkt_ret,
            y_window,
            x_window_reg,
            vol,
        ],
        outputs={
            "exposures":           exposures,       # main output — use at inference
            "blend_weights_target": blend_weights,  # supervised with quality labels
            **aux_outputs,                          # exposures_h1, exposures_h3, exposures_h5
        })

    #model = keras.Model(
    #    inputs=[
    #        asset_features,
    #        regime_onchain,
    #        regime_macro,
    #        lag_abs_ret,
    #        lag_mkt_ret,
    #        y_window,
    #        x_window_reg,
    #        vol,
    #    ],
    #    outputs={
    #        "exposures":           exposures,       # main output — use at inference
    #        "blend_weights_target": blend_weights,  # supervised with quality labels
    #        **aux_outputs,                          # exposures_h1, exposures_h3, exposures_h5
    #    },
    #    name="cross_sectional_mixer_lstm2_v16",
    #)

    # -------------------------------------------------------------------------
    # Losses
    # -------------------------------------------------------------------------
    optimizer = optimizers.AdamW(
        learning_rate=initial_lr,
        weight_decay=w_decay,
    )

    loss_dict    = {"exposures": MixedSharpePearsonPnl(alpha=0)}
    weights_dict = {"exposures": 1.0}

    for hname, w in zip(horizons, horizon_loss_weights):
        loss_dict[f"exposures_{hname}"]    = MixedSharpePearsonPnl(alpha=0)
        weights_dict[f"exposures_{hname}"] = w

    # Blend weights supervised with KL divergence against quality soft-labels
    loss_dict["blend_weights_target"]    = keras.losses.KLDivergence()
    weights_dict["blend_weights_target"] = blend_supervision_weight

    model.compile(
        optimizer=optimizer,
        loss=loss_dict,
        loss_weights=weights_dict,
    )

    model.zenith_init(eta0=initial_lr, window=100)  # small window for a quick demo

    return model

