"""# ***FWCV TRAINING FUNCTIONS***"""


def make_dataset(inputs_dict, targets_dict, batch_size, shuffle=False):
    """
    Build a tf.data.Dataset from multiple NumPy arrays.
    inputs_dict:  {"input_name": np_array, ...}
    targets_dict: {"output_name": np_array, ...}
    """

    # Convert dicts to tuples for tf.data
    ds = tf.data.Dataset.from_tensor_slices((inputs_dict, targets_dict))

    if shuffle:
        ds = ds.shuffle(buffer_size=len(list(inputs_dict.values())[0]))

    ds = ds.batch(batch_size)
    ds = ds.prefetch(tf.data.AUTOTUNE)
    return ds

"""
Three-stage hyperparameter optimisation pipeline — with macro_df support.

Stage 1  – FWCVObjective      : Optuna walk-forward CV search (OOS never seen)
Stage 2  – SeedRobustnessEval : first & only OOS touch; prune unstable param sets
Stage 3  – EnsembleBuilder    : final models trained on full data, multiple seeds

External names assumed to exist in the calling scope
-----------------------------------------------------
    initial_data_full       pd.DataFrame   full feature DataFrame (wide)
    br_data                 pd.DataFrame   regime / on-chain feature DataFrame
    macro_df                pd.DataFrame   macro feature DataFrame          ← NEW
    tickers                 list[str]      asset tickers
    selected_cols           list[str]      feature columns to use (may be [])
    selected_regime_cols    list[str]      on-chain regime feature columns (may be [])
    selected_macro_cols     list[str]      macro feature columns (may be [])  ← NEW
    unix_threshold_training int/float      end-of-training unix timestamp
    unix_threshold_full     int/float      end-of-train+val unix timestamp (OOS start)

    Functions
    ---------
    prepare_features_from_wide_df2(...)     → x, x_reg_onchain, x_reg_macro, y, y_r,
                                               x_val, x_val_reg_onchain, x_val_reg_macro,
                                               y_val, y_valr                 ← NEW signature
    create_windowed_inputs(x, y, y_m, w)   → x_w, y_w, y_m_w
    make_dataset(inputs_dict, targets_dict, batch_size, shuffle) → tf.data.Dataset
    build_cross_sectional_mixer_lstm2(**kwargs) → compiled tf.keras.Model
    run_model_evaluation(model, ...)        → (profit: float, profit_cum: float)
    CyclicalLearningRate(base_lr, max_lr, step_size) → keras Callback
    AlphaLRScheduler(loss, optimizer, ...) → keras Callback
"""


# =============================================================================
# Shared low-level utilities
# =============================================================================

def _set_seed(seed: int) -> None:
    """Globally fix all random seeds."""
    tf.random.set_seed(seed)
    np.random.seed(seed)
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)


def _clear_session() -> None:
    """Release GPU memory between model builds."""
    K.clear_session()
    tf.compat.v1.reset_default_graph()
    gc.collect()


def _full_cleanup():
    """Complete TensorFlow/Keras cleanup - call between independent training runs"""

    # 1. Clear Keras session
    keras.backend.clear_session()

    # 2. Reset TensorFlow graph
    tf.compat.v1.reset_default_graph()

    # 3. Force garbage collection
    gc.collect()

    # 4. Clear TensorFlow eager context
    try:
        tf.keras.backend.clear_session()
        tf.compat.v1.keras.backend.clear_session()
    except:
        pass

    # 5. Reset TensorFlow graph keys (prevents "Graph is finalized" errors)
    try:
        from tensorflow.python.framework import ops
        ops._default_graph_stack._reset()
    except:
        pass

    # 6. Clear any cached functions
    try:
        tf.keras.backend._get_available_gpus()  # Force re-initialization
    except:
        pass

    # 7. Optional: Clear GPU memory cache if using GPU
    try:
        tf.config.experimental.set_memory_growth(tf.config.list_physical_devices('GPU')[0], True)
    except:
        pass



def _make_lagged(
    y: np.ndarray,          # shape (T, n_assets)
    y_market: np.ndarray,   # shape (T, n_assets)  or  (T,)
) -> tuple[np.ndarray, np.ndarray]:
    """
    Shift return arrays by one step so that position [t] contains
    the return observed at [t-1].  Position [0] is zeroed.
    """
    y_shifted = np.zeros_like(y)
    y_shifted[1:] = y[:-1]

    y_market_shifted = np.zeros_like(y_market)
    y_market_shifted[1:] = y_market[:-1]

    return y_shifted, y_market_shifted


def _trim_to_window(
    n_window: int,
    *arrays: np.ndarray,
) -> tuple[np.ndarray, ...]:
    """Trim every array in *arrays to its last n_window rows (axis-0)."""
    return tuple(a[-n_window:] for a in arrays)


def _build_inputs_dict(
    x: np.ndarray,                        # (T, n_assets, n_features)
    x_reg_onchain: np.ndarray,            # (T, n_onchain_features)      ← renamed
    x_reg_macro: np.ndarray,              # (T, n_macro_features)        ← NEW
    y_shifted: np.ndarray,                # (T, n_assets)
    y_shifted_market: np.ndarray,         # (T, n_assets) or (T,)
    x_w: np.ndarray,                      # (T, window, n_assets, n_features)
    y_shifted_w: np.ndarray,              # (T, window, n_assets)
    y_shifted_market_w: np.ndarray,       # (T, window, n_assets) or (T, window)
    vol: np.ndarray,
) -> dict[str, np.ndarray]:
    return {
        "asset_features":          x,
        "regime_onchain":          x_reg_onchain,   # ← renamed from "regime_features"
        "regime_macro":            x_reg_macro,     # ← NEW
        "lagged_absolute_returns": y_shifted,
        "lagged_market_returns":   y_shifted_market,
        "x_window":                x_w,
        #"y_window":                y_shifted_w,
        "y_market_rel_window":     y_shifted_market_w,
        "vol": vol
    }


def _pop(d: dict, *keys: str) -> dict:
    """Return a copy of d with the given keys removed."""
    return {k: v for k, v in d.items() if k not in keys}


# Keys that must be stripped from params before passing to build_cross_sectional_mixer_lstm2
_NON_MODEL_KEYS: frozenset[str] = frozenset(
    ["num_epochs", "computing_batch", "standardisation", "max_lr", "standardisation_type_volume"]
)


def _model_kwargs(
    params: dict[str, Any],
    n_features: int,
    n_onchain_features: int,     # ← renamed from n_regime_features
    n_macro_features: int,       # ← NEW
    n_assets: int,
    n_vol_features: int,
) -> dict[str, Any]:
    """
    Build the kwarg dict for build_cross_sectional_mixer_lstm2.
    Strips scheduling / training-loop keys and injects shape params.
    """
    kwargs = _pop(params, *_NON_MODEL_KEYS)
    kwargs["n_features"]         = n_features
    kwargs["n_onchain_features"] = n_onchain_features   # ← renamed
    kwargs["n_macro_features"]   = n_macro_features     # ← NEW
    kwargs["n_assets"]           = n_assets
    kwargs["n_vol_features"]           = n_vol_features
    return kwargs



def _prepare_arrays(
    x: np.ndarray,
    x_reg_onchain: np.ndarray,
    x_reg_macro: np.ndarray,
    y: np.ndarray,
    y_r: np.ndarray,
    volume: np.ndarray,
    window: int,
) -> tuple[np.ndarray, ...]:

    y_shifted, y_shifted_market = _make_lagged(y, y_r)

    # Window price data (4D)
    x_w_price, y_shifted_w, y_shifted_market_w = create_windowed_inputs(x=x, y_abs=y_shifted, y_rel=y_shifted_market, window=window)

    # Window regime data (3D)
    T_reg, R = x_reg_onchain.shape
    x_reg_3d = x_reg_onchain.reshape(T_reg, 1, R)
    x_w_reg, _, _ = create_windowed_inputs(
        x_reg_3d,
        np.zeros((T_reg, 1)),
        np.zeros((T_reg, 1)),
        window
    )
    x_w_reg = x_w_reg.squeeze(axis=2)  # (T_w, window, R)

    #T, total_vol_features = volume.shape
    #volume_w = np.zeros((T - window + 1, window, total_vol_features), dtype=volume.dtype)
    #for i in range(window, T + 1):
    #    volume_w[i - window] = volume[i-window:i]  # (window, total_vol_features)

    T, total_vol_features = volume.shape
    A = y.shape[-1]
    F = total_vol_features // A
    assert A * F == total_vol_features

    volume_w = np.zeros((T - window + 1, A, window, F), dtype=volume.dtype)

    for i in range(window, T + 1):
        w = volume[i-window:i]        # (W, A*F)
        w = w.reshape(window, A, F)   # (W, A, F)
        w = np.transpose(w, (1, 0, 2))  # (A, W, F)
        volume_w[i-window] = w


    # Window volume data (4D)
    #T, A = volume.shape
    #volume_3d = volume.reshape(T, A, 1)
    #vol_w, _, _ = create_windowed_inputs(
    #    volume_3d,
    #    np.zeros((T, A)),
    #    np.zeros((T, A)),
    #    window
    #)  # (T_w, window, A, 1)

    n_w = x_w_price.shape[0]

    # Trim all non-windowed arrays
    (
        x_out, x_reg_onchain_out, x_reg_macro_out,
        y_r_out, y_shifted_out, y_shifted_market_out,
        volume_out,
    ) = _trim_to_window(
        n_w,
        x, x_reg_onchain, x_reg_macro,
        y_r, y_shifted, y_shifted_market,
        volume,
    )

    return (
        x_out, x_reg_onchain_out, x_reg_macro_out, y_r_out,
        y_shifted_out, y_shifted_market_out,
        x_w_reg, y_shifted_w, y_shifted_market_w, volume_w
    )




