def _build_callbacks(
    params: dict[str, Any],
    n_train_samples: int,
    num_epochs: int,
    model: keras.Model,
    use_early_stopping: bool = True,
) -> list[keras.callbacks.Callback]:
    """
    Construct training callbacks from params.
    """
    computing_batch: int = params["computing_batch"]
    warmup = max(1, num_epochs // 8)
    #cyclic_lr = CyclicalLearningRate(
    #    base_lr=params["initial_lr"],
    #    max_lr=params["max_lr"],
    #    step_size=max(1, n_train_samples // computing_batch),
    #)
    alpha_cb = AlphaLRScheduler(
        model.loss,
        model.optimizer,
        warmup=warmup,
        ramp=max(2, 2 * num_epochs // 3),
        alpha_max=0.85,
        is_warmup=True,
        verbose=False,
    )

    tensorboard_callback = tf.keras.callbacks.TensorBoard(
        log_dir=log_tb_dir,
        histogram_freq=1,  # Log weights histograms every epoch
        update_freq='epoch'  # Log metrics every epoch ('batch' is also an option)
    )

    cbs: list[keras.callbacks.Callback] = [
         #cyclic_lr,
         alpha_cb, tensorboard_callback]

    if use_early_stopping:
        cbs.append(
            keras.callbacks.EarlyStopping(
                monitor="val_loss",
                mode="min",
                patience=max(3, num_epochs // 10),
                restore_best_weights=True,
            )
        )
    return cbs, warmup


# =============================================================================
# Stage 1 — FWCV Hypertuning Objective
# =============================================================================

class FWCVObjective:
    """
    Walk-forward cross-validation objective for Optuna.
    OOS data is never accessed here.
    """

    FIXED_SEED:      int   = 42
    FIXED_PERC_UP:   float = 0.8
    FIXED_PERC_DOWN: float = 0.2

    def __init__(
        self,
        last_units: int | None,
        argmax: bool | None,
        losstype: str | None,
        categorical_input: bool | None,
        path_suffix: str = "",
        index_type: str = "",
        n_folds: int = 5,
        fold_size: int | None = None,
        min_train_bars: int | None = None,
        fold_gap: int = 1,
        variance_penalty: float = 0.5,
        save_dir: str = f"/content/drive/MyDrive/OPTIMIZATION_STEVENOMOLE_MINUTE{run}",
        run: int = 0,
    ) -> None:
        self.last_units      = last_units
        self.argmax          = argmax
        self.losstype        = losstype
        self.categorical     = categorical_input
        self.path_suffix     = path_suffix
        self.index_type      = index_type
        self.variance_penalty: float = variance_penalty
        self.fold_gap:         int   = fold_gap
        self.n_folds:          int   = n_folds
        self.save_dir:         str   = f"{save_dir}"
        self.run:              int   = run

        # Global data (injected from calling scope)
        self.data: pd.DataFrame              = initial_data_full
        self.br_data: pd.DataFrame           = br_data
        self.macro_df: pd.DataFrame          = macro_df              # ← NEW
        self.num_assets: int                 = len(tickers)
        self.selected_cols: list[str]        = (
            list(selected_cols)        if len(selected_cols) > 0
            else list(initial_data_full.columns)
        )
        self.selected_regime_cols: list[str] = (
            list(selected_regime_cols) if len(selected_regime_cols) > 0
            else list(br_data.columns)
        )
        self.selected_macro_cols: list[str]  = (   # ← NEW
            list(selected_macro_cols)  if len(selected_macro_cols) > 0
            else list(macro_df.columns)
        )

        # Pre-compute fold size and validate
        n_bars = len(self.data)
        self.fold_size: int = (
            fold_size
            if fold_size is not None
            else max(60, n_bars // (n_folds + 1))
        )
        self.min_train_bars: int = (
            min_train_bars
            if min_train_bars is not None
            else self.fold_size - 1 #* 2
        )
        self._validate_fold_config(n_bars)
        os.makedirs(self.save_dir, exist_ok=True)

        logger.info(
            "FWCVObjective | folds=%d | fold_size=%d | min_train=%d | gap=%d",
            n_folds, self.fold_size, self.min_train_bars, fold_gap,
        )

    # ------------------------------------------------------------------
    # Private helpers
    # ------------------------------------------------------------------

    def _validate_fold_config(self, n_bars: int) -> None:
        required = (
            self.min_train_bars
            + self.n_folds * (self.fold_size) #+ self.fold_gap)
        )
        if required > n_bars:
            raise ValueError(
                f"Insufficient data: {n_bars} bars available, "
                f"need at least {required} for {self.n_folds} folds "
                f"(fold_size={self.fold_size}, gap={self.fold_gap})."
            )

    def _suggest_params(self, trial: optuna.Trial) -> dict[str, Any]:
        return {
            "gate": trial.suggest_categorical("gate", [True, False]),#trial.suggest_int("num_epochs", 20, 50, step=10),
            "num_epochs": trial.suggest_categorical("num_epochs", [20, 40, 60]),#trial.suggest_int("num_epochs", 20, 50, step=10),
            "computing_batch": trial.suggest_int("computing_batch", 128, 256, step=16),
            "dropout":         trial.suggest_float("dropout", 0.2, 0.4, step=0.05), #0.33, 0.38),
            "standardisation": trial.suggest_categorical(
                "standardisation", ["standard", "minmax",
                                    "robust"]
            ),
            "temporal_attention_type": trial.suggest_categorical("temporal_attention_type", [
                "RNN", "LSTM",
                "None"
            ]),
            "use_lstm": trial.suggest_categorical("use_lstm", [False, True]), #[True, False]),
            #"standardisation_type_volume": trial.suggest_categorical("standardisation_type_volume", ["minmax", "robust", "standard"]),
            "hidden_dim":      trial.suggest_int("hidden_dim", 16, 258, step=8),
            "dim_temporal_regime": trial.suggest_int("dim_temporal_regime", 16, 200, step=8),
            "dim_temporal_volume": trial.suggest_int("dim_temporal_volume", 16, 200, step=8),
            "head_num":         trial.suggest_categorical("head_num", [0, 1, 4]),
            "kernel_size": 5, #trial.suggest_categorical("kernel_size", [5, 9]),
            #"n_factors":       trial.suggest_int("n_factors", 4, 7),
            #"emb_dim":         trial.suggest_int("emb_dim", 16, 48, step=2),
            #"drop_path_rate":  trial.suggest_float("drop_path_rate", 0.0, 0.25),
            "w_decay":         trial.suggest_float("w_decay", 0.0001, 0.01),
            #"res_influence":   trial.suggest_float("res_influence", 0.01, 0.15),
            "window":          trial.suggest_int("window", 18, 50, step=4),
            "sharpness":       trial.suggest_int("sharpness", 3, 50, log=False),
            "tau":             trial.suggest_float("tau", 0, 0.46),
            #"initial_lr":      trial.suggest_float("initial_lr", 0.0001, 0.0008), #0.00019, 0.00024),
            "initial_lr":          trial.suggest_float("initial_lr", 0.0006, 0.002), #0.00143, 0.00180), #Was max_lr before ZenithModel
            "activation":      trial.suggest_categorical(
                "activation",  ["gelu", "swish", "relu", "leaky_relu", "elu"]
                ),
            "gate_activation":      trial.suggest_categorical(
                "gate_activation",     [
                    #"sigmoid",     # (0,1) - Classic, probability-like
                    #"hard_sigmoid", # (0,1) - Faster, piecewise linear
                    "tanh",        # (-1,1) - Can have negative gates (inhibition)
                    "softsign",    # (-1,1) - Similar to tanh but smoother gradients
                    "relu",        # [0,∞) - Only positive, unbounded
                    #"elu"          # (-∞,∞) - Can have negative values
                    ]
                ),
            "temporal_activation":      trial.suggest_categorical(
                "temporal_activation", ["tanh", "relu", "gelu"]
                ),
            "output_activation":      trial.suggest_categorical(
                "output_activation", ["tanh", "linear", "softsign"]
                ),
            "blend_supervision_weight": trial.suggest_float("blend_supervision_weight", 0.2, 0.37, step=0.025),
            "deadzone": trial.suggest_float("deadzone", 0.0, 0.05),

        }

    def _fold_boundaries(self) -> list[tuple[int, int, int, int]]:
        """
        Sliding window (non-incremental) walk-forward CV.
        Each fold trains on exactly fold_size bars, validates on the next fold_size bars.
        No overlap, no expanding window.
        """
        folds: list[tuple[int, int, int, int]] = []
        n = len(self.data)

        for k in range(self.n_folds):
            train_start = k * self.fold_size
            train_end   = train_start + self.fold_size - self.fold_gap

            val_start   = train_start + self.fold_size
            val_end     = min(val_start + self.fold_size, n)

            # Check bounds
            if val_start >= n:
                logger.warning("Fold %d skipped — val_start %d beyond data length %d", k, val_start, n)
                continue

            # Check minimum training size
            if train_end - train_start < self.min_train_bars:
                logger.warning("Fold %d skipped — too few training bars (%d < %d)",
                              k, train_end - train_start, self.min_train_bars)
                continue

            folds.append((train_start, train_end, val_start, val_end))
            logger.info("Fold %d | train[%d:%d] val[%d:%d]", k, train_start, train_end, val_start, val_end)

        if not folds:
            raise ValueError(f"No valid folds. Total data length: {n}, "
                            f"fold_size: {self.fold_size}, min_train: {self.min_train_bars}")

        return folds

    def _train_one_fold(
        self,
        params: dict[str, Any],
        train_start: int,
        train_end: int,
        val_start: int,
        val_end: int,
    ) -> float:
        """Train on one fold, return best val_loss."""
        _clear_session()
        _set_seed(self.FIXED_SEED)

        print(f"TRAIN START: {train_start} - TRAIN END: {train_end} VAL START {val_start} VAL END {val_end}")

        # Pass the full fold window (train + val combined) so that
        # prepare_features_from_wide_df2 can apply its internal 80/20 split.
        # The gap rows between train_end and val_start are intentionally excluded.
        fold_df: pd.DataFrame = self.data.iloc[train_start:train_end]
        br_data: pd.DataFrame = self.br_data.iloc[train_start:train_end]
        macro_df: pd.DataFrame = self.macro_df.iloc[train_start:train_end]
        fold_df_val: pd.DataFrame = self.data.iloc[val_start:val_end]
        br_data_val: pd.DataFrame = self.br_data.iloc[val_start:val_end]
        macro_df_val: pd.DataFrame = self.macro_df.iloc[val_start:val_end]


        try:
            # ---- 1. Feature preparation ----
            # training=True → function splits fold_df internally (last ~20% = val)

            x, x_reg_onchain, x_reg_macro, y, y_r, vol,  r1_train, r3_train, r7_train, r10_train, r13_train, r17_train, r24_train = prepare_features_from_wide_df2(
                df=fold_df,
                btc_chain_df=br_data,
                macro_df=macro_df,
                standardisation_type=params["standardisation"],
                training=True,
                path_suffix=self.path_suffix,
                selected_cols=self.selected_cols,
                selected_regime_cols=self.selected_regime_cols,
                selected_macro_cols=self.selected_macro_cols,
                #fwcv=True,
                standardisation_type_volume=params["standardisation_type_volume"] if "standardisation_type_volume" in params.keys() else params["standardisation"]
            )

            # Concatenate train + val along time axis
            #x:          np.ndarray = np.concatenate([x, x_val],                     axis=0)
            #x_reg_onchain: np.ndarray = np.concatenate([x_reg_onchain, x_val_reg_onchain], axis=0)  # ← NEW
            #x_reg_macro:   np.ndarray = np.concatenate([x_reg_macro, x_val_reg_macro],     axis=0)  # ← NEW
            #y:          np.ndarray = np.concatenate([y, y_val],                     axis=0)
            #y_r:        np.ndarray = np.concatenate([y_r, y_valr],                 axis=0)
            #vol:        np.ndarray = np.concatenate([vol, vol_val],                 axis=0)


            x_val, x_val_reg_onchain, x_val_reg_macro, y_val, y_valr, vol_val,  r1_val, r3_val, r7_val, r10_val, r13_val, r17_val, r24_val = prepare_features_from_wide_df2(
                df=fold_df_val,
                btc_chain_df=br_data_val,
                macro_df=macro_df_val,
                standardisation_type=params["standardisation"],
                training=False,
                path_suffix=self.path_suffix,
                selected_cols=self.selected_cols,
                selected_regime_cols=self.selected_regime_cols,
                selected_macro_cols=self.selected_macro_cols,
                #fwcv=True,
                standardisation_type_volume=params["standardisation_type_volume"] if "standardisation_type_volume" in params.keys() else params["standardisation"]
            )

            window: int          = params["window"]
            computing_batch: int = params["computing_batch"]
            num_epochs: int      = params["num_epochs"]

            # ---- 2. Windowing + lagging ----
            (
                x, x_reg_onchain, x_reg_macro, y_r,
                y_shifted, y_shifted_market,
                x_w, y_shifted_w, y_shifted_market_w, vol_w
            ) = _prepare_arrays(x, x_reg_onchain, x_reg_macro, y, y_r, vol, window)

            print("x", x.shape, "x_reg_onchain", x_reg_onchain.shape, "x_reg_macro", x_reg_macro.shape, "y_r", y_r.shape,
                "y_shifted", y_shifted.shape, "y_shifted_market", y_shifted_market.shape,
                "x_w", x_w.shape, "y_shifted_w", y_shifted_w.shape, "y_shifted_market_w", y_shifted_market_w.shape, "vol_w", vol_w.shape)

            (
                x_val, x_val_reg_onchain, x_val_reg_macro, y_valr,
                y_shifted_val, y_shifted_market_val,
                x_w_val, y_shifted_w_val, y_shifted_market_w_val, vol_val_w
            ) = _prepare_arrays(x_val, x_val_reg_onchain, x_val_reg_macro, y_val, y_valr, vol_val, window)


            horizon_quality_train = compute_horizon_quality(
                y_list=[r1_train,
                        r3_train,
                        r7_train,
                        r10_train,
                        r13_train,
                        r17_train,
                        r24_train],
                exposures_list=None, #window=window # or pass warm-start exposures
            )  # shape (N, H)


            # ---- 3. Build model ----
            model: keras.Model = build_cross_sectional_mixer_lstm2(
                **_model_kwargs(
                    params,
                    n_features=x.shape[-1],
                    n_onchain_features=x_reg_onchain.shape[-1],   # ← renamed
                    n_macro_features=x_reg_macro.shape[-1],       # ← NEW
                    n_assets=self.num_assets,
                    n_vol_features=vol_w.shape[-1]
                )
            )

            print("x shape", x.shape, "r1_train[-x_val.shape[0]:]", r1_train[-x_val.shape[0]:].shape, "r3_train[-x_val.shape[0]:]", r3_train[-x_val.shape[0]:].shape, "r7_train[-x_val.shape[0]:]", r7_train[-x_val.shape[0]:].shape,
                  "r10_train[-x_val.shape[0]:]", r10_train[-x_val.shape[0]:].shape, "r13_train[-x_val.shape[0]:]", r13_train[-x_val.shape[0]:].shape, "r17_train[-x_val.shape[0]:]", r17_train[-x_val.shape[0]:].shape,
                   "r24_train[-x_val.shape[0]:]", r24_train[-x_val.shape[0]:].shape, "horizon_quality_train length", len(horizon_quality_train[-x_val.shape[0]:])
            )

            # ---- 4. Datasets ----
            train_ds = make_dataset(
                inputs_dict=_build_inputs_dict(
                    x, x_reg_onchain, x_reg_macro,               # ← NEW arg
                    y_shifted, y_shifted_market,
                    x_w, y_shifted_w, y_shifted_market_w, vol_w
                ),
                targets_dict={
                    #"exposures": y_blend[-x.shape[0]:], #y_r
                    "exposures":            y_r[-x.shape[0]:], #y_valr
                    "exposures_h1":         r1_train[-x.shape[0]:],
                    "exposures_h3":         r3_train[-x.shape[0]:],
                    "exposures_h7":         r7_train[-x.shape[0]:],
                    "exposures_h10":         r10_train[-x.shape[0]:],
                    "exposures_h13":         r13_train[-x.shape[0]:],
                    "exposures_h17":         r17_train[-x.shape[0]:],
                    "exposures_h24":         r24_train[-x.shape[0]:],
                    "blend_weights_target": horizon_quality_train[-x.shape[0]:], # soft quality labels (N, 3)

                             },
                batch_size=computing_batch,
                shuffle=False,
            )
            val_ds = make_dataset(
                inputs_dict=_build_inputs_dict(
                    x_val, x_val_reg_onchain, x_val_reg_macro,   # ← NEW arg
                    y_shifted_val, y_shifted_market_val,
                    x_w_val, y_shifted_w_val, y_shifted_market_w_val, vol_val_w
                ),
                targets_dict={
                    #"exposures": y_blend_val[-x_val.shape[0]:], #y_valr
                    "exposures":            y_val[-x_val.shape[0]:], #y_valr
                    "exposures_h1":         r1_val[-x_val.shape[0]:],
                    "exposures_h3":         r3_val[-x_val.shape[0]:],
                    "exposures_h7":         r7_val[-x_val.shape[0]:],
                    "exposures_h10":         r10_val[-x_val.shape[0]:],
                    "exposures_h13":         r13_val[-x_val.shape[0]:],
                    "exposures_h17":         r17_val[-x_val.shape[0]:],
                    "exposures_h24":         r24_val[-x_val.shape[0]:],
                    "blend_weights_target": horizon_quality_train[-x_val.shape[0]:], # soft quality labels (N, 3)
                             },
                batch_size=computing_batch,
                shuffle=False,
            )

            # ---- 5. Train ----
            callbacks, warmup_epochs = _build_callbacks(
                params=params,
                n_train_samples=x.shape[0],
                num_epochs=num_epochs,
                model=model,
                use_early_stopping=False,
            )

            history = model.fit(
                train_ds,
                validation_data=None,
                epochs=num_epochs,
                callbacks=callbacks,
                verbose=0,
            )

            preds = model.predict({
                "asset_features": x_val,
                "regime_onchain": x_val_reg_onchain,
                "regime_macro": x_val_reg_macro,
                "lagged_absolute_returns": y_shifted_val,
                "lagged_market_returns": y_shifted_market_val,
                "x_window": x_w_val,
                #"y_window": y_shifted_w_val,
                "y_market_rel_window": y_shifted_market_w_val,
                "vol": vol_val_w
            }
                                 )["exposures"]

            print(f"SHAPE y_val : {y_val.shape} - SHAPE preds: {preds.shape}")
            y_val = y_val[-len(preds):]

            _, summary = backtest_weights(preds, y_val)
            best_val_loss = - summary["sharpe"]
            print(f"SHARPE: {best_val_loss} - PROFIT: {_['equity'][-1]}")
            #best_val_loss: float = float(min(history.history["val_loss"]))
            return best_val_loss

        finally:
            for var in [
                'model',
                'x', 'x_reg_onchain', 'x_reg_macro', 'y', 'y_r',
                'x_val', 'x_val_reg_onchain', 'x_val_reg_macro', 'y_val', 'y_valr', 'y_blend_val',
                'x_w', 'x_w_val',
            ]:
                try:
                    del locals()[var]
                except KeyError:
                    pass
            _clear_session()

    # ------------------------------------------------------------------
    # Optuna entry point
    # ------------------------------------------------------------------

    def __call__(self, trial: optuna.Trial) -> float:
        """Minimise: mean_val_loss + variance_penalty * std_val_loss"""
        try:
            params: dict[str, Any] = self._suggest_params(trial)
            folds = self._fold_boundaries()

            if not folds:
                raise RuntimeError("No valid folds — check fold configuration.")

            fold_losses: list[float] = []

            for k, (ts, te, vs, ve) in enumerate(folds):
                logger.info(
                    "Trial %d | fold %d/%d | train[%d:%d] val[%d:%d]",
                    trial.number, k + 1, len(folds), ts, te, vs, ve,
                )
                loss: float = self._train_one_fold(params, ts, te, vs, ve)
                fold_losses.append(loss)

                if k >= 1:
                    trial.report(float(np.mean(fold_losses)), step=k)
                    if trial.should_prune():
                        raise optuna.TrialPruned()

            median_val_loss: float = float(np.median(fold_losses))
            mean_val_loss: float = float(np.mean(fold_losses))
            std_loss:  float = float(np.std(fold_losses))
            q75, q25 = np.percentile(fold_losses, [75, 25])
            iqr = q75 - q25
            objective: float = median_val_loss + self.variance_penalty * iqr

            trial.set_user_attr("fold_losses",   fold_losses)
            trial.set_user_attr("mean_val_loss", mean_val_loss)
            trial.set_user_attr("median_val_loss", median_val_loss)
            trial.set_user_attr("std_val_loss",  std_loss)
            trial.set_user_attr("n_folds_run",   len(fold_losses))
            trial.set_user_attr("iqr",   iqr)

            logger.info(
                "Trial %d | median=%.4f std=%.4f objective=%.4f mean=%.4f iqr=%.4f",
                trial.number, median_val_loss, std_loss, objective, mean_val_loss, iqr
            )
            return objective

        except optuna.TrialPruned:
            raise
        except Exception as exc:
            logger.error(
                "Trial %d failed: %s", trial.number, exc, exc_info=True
            )
            raise RuntimeError(f"Trial failed: {exc}") from exc



class SeedClustering:
    """
    Replaces SeedRobustnessEvaluator.
    Uses the same 'robustness_seeds' list.
    Trains each seed on train+val, clusters exposures, returns representative seeds.
    """

    def __init__(self, params, robustness_seeds, n_clusters=3, path_suffix=""):
        self.params = params
        self.seeds = robustness_seeds
        self.n_clusters = n_clusters
        self.path_suffix = path_suffix
        os.makedirs(self.path_suffix, exist_ok=True)

        self.data = initial_data_full
        self.br = br_data
        self.mac = macro_df
        self.oos_data = oos_data
        self.br_oos = br_data_oos
        self.macro_oos = macro_df_oos
        self.n_assets = len(tickers)

    # ------------------------------------------------------------
    # Train one seed on train+val and return exposures
    # ------------------------------------------------------------
    def _train_and_get_exposures(self, seed):
        _clear_session()
        _set_seed(seed)

        self.params["seed"] = seed

        df_trainval = self.data[self.data.index < unix_threshold_full]
        br_trainval = self.br.loc[df_trainval.index]
        mac_trainval = self.mac.loc[df_trainval.index]

        # Prepare features
        x, x_on, x_mac, y, y_r, vol, \
        r1, r3, r7, r10, r13, r17, r24 = prepare_features_from_wide_df2(
            df=df_trainval,
            btc_chain_df=br_trainval,
            macro_df=mac_trainval,
            standardisation_type=self.params["standardisation"],
            training=True,
            path_suffix=self.path_suffix,
            selected_cols=selected_cols,
            selected_regime_cols=selected_regime_cols,
            selected_macro_cols=selected_macro_cols,
            #fwcv=True,
            standardisation_type_volume=self.params["standardisation_type_volume"] if "standardisation_type_volume" in self.params.keys() else self.params["standardisation"]
        )

        x_oos, x_on_oos, x_mac_oos, y_oos, y_r_oos, vol_oos, \
        r1_oos, r3_oos, r7_oos, r10_oos, r13_oos, r17_oos, r24_oos = prepare_features_from_wide_df2(
            df=self.oos_data,
            btc_chain_df=self.br_oos,
            macro_df=self.macro_oos,
            standardisation_type=self.params["standardisation"],
            training=False,
            path_suffix=self.path_suffix,
            selected_cols=selected_cols,
            selected_regime_cols=selected_regime_cols,
            selected_macro_cols=selected_macro_cols,
            #fwcv=True,
            standardisation_type_volume=self.params["standardisation_type_volume"] if "standardisation_type_volume" in self.params.keys() else self.params["standardisation"]
        )

        window = self.params["window"]
        batch = self.params["computing_batch"]
        epochs = self.params["num_epochs"]

        # Windowing
        (
            x, x_on, x_mac, y_r,
            y_shift, y_mkt_shift,
            x_w, y_w, y_mkt_w, vol_w
        ) = _prepare_arrays(x, x_on, x_mac, y, y_r, vol, window)

        (
            x_oos, x_on_oos, x_mac_oos, y_r_oos,
            y_shift_oos, y_mkt_shift_oos,
            x_w_oos, y_w_oos, y_mkt_w_oos, vol_w_oos
        ) = _prepare_arrays(x_oos, x_on_oos, x_mac_oos, y_oos, y_r_oos, vol_oos, window)

        # Horizon quality
        hq = compute_horizon_quality(
            [r1,
             r3,
             r7,
             r10,
             r13,
             r17,
             r24],
            exposures_list=None #window=window
        )

        # Build model
        model = build_cross_sectional_mixer_lstm2(
            **_model_kwargs(
                self.params,
                n_features=x.shape[-1],
                n_onchain_features=x_on.shape[-1],
                n_macro_features=x_mac.shape[-1],
                n_assets=self.n_assets,
                n_vol_features=vol_w.shape[-1],
            )
        )


        # Dataset
        train_ds = make_dataset(
            _build_inputs_dict(x, x_on, x_mac, y_shift, y_mkt_shift, x_w, y_w, y_mkt_w, vol_w),
            {
                "exposures": y_r[-x.shape[0]:],
                "exposures_h1": r1[-x.shape[0]:],
                "exposures_h3": r3[-x.shape[0]:],
                "exposures_h7": r7[-x.shape[0]:],
                "exposures_h10": r10[-x.shape[0]:],
                "exposures_h13": r13[-x.shape[0]:],
                "exposures_h17": r17[-x.shape[0]:],
                "exposures_h24": r24[-x.shape[0]:],
                "blend_weights_target": hq[-x.shape[0]:],
            },
            batch_size=batch,
            shuffle=False,
        )

        # Callbacks
        cbs, warmup_epochs = _build_callbacks(
            params=self.params,
            n_train_samples=x.shape[0],
            num_epochs=epochs,
            model=model,
            use_early_stopping=False,
        )

        # Train
        model.fit(train_ds, epochs=epochs, callbacks=cbs, verbose=0)

        # Get exposures on train+val
        preds = model.predict(
            {
                "asset_features": x_oos,
                "regime_onchain": x_on_oos,
                "regime_macro": x_mac_oos,
                "lagged_absolute_returns": y_shift_oos,
                "lagged_market_returns": y_mkt_shift_oos,
                "x_window": x_w_oos,
                "y_market_rel_window": y_mkt_w_oos,
                "vol": vol_w_oos,
            },
            verbose=0,
        )["exposures"]

        try:
            del model, cbs, train_ds, x, x_on, x_mac, y_r, y_shift, y_mkt_shift, x_w, y_w, y_mkt_w, vol_w, hq, x_oos, x_on_oos, x_mac, y_r_oos,
            y_shift_oos, y_mkt_shift_oos,
            x_w_oos, y_w_oos, y_mkt_w_oos, vol_w_oos, r1_oos, r3_oos, r7_oos, r10_oos, r13_oos, r17_oos, r24_oos
        except:
            pass

        _clear_session()
        print(f"ENDED TRAINING FOR CLUSTERING seed: {seed}")
        return preds

    # ------------------------------------------------------------
    # Cluster seeds by exposure correlation
    # ------------------------------------------------------------
    def cluster(self):
        exposures = {}

        # Train all seeds
        for seed in self.seeds:
            exposures[seed] = self._train_and_get_exposures(seed)

        # Build correlation matrix
        seed_list = sorted(exposures.keys())
        X = np.stack([exposures[s].reshape(-1) for s in seed_list], axis=0)
        corr = np.corrcoef(X)
        dist = 1 - corr

        # Hierarchical clustering
        Z = linkage(dist, method="average")
        labels = fcluster(Z, t=self.n_clusters, criterion="maxclust")

        # Pick representative seeds
        reps = []
        labels = np.array(labels)
        seed_arr = np.array(seed_list)

        for c in np.unique(labels):
            cluster_seeds = seed_arr[labels == c]
            rep = int(np.median(cluster_seeds))
            reps.append(rep)

        return reps


