# =============================================================================

class EnsembleBuilder:
    """
    Builds final ensemble using ONLY the representative clustered seeds.
    Saves each model and the ensemble metadata.
    """

    def __init__(self, params, representative_seeds, save_dir, path_suffix="", trial=1):
        self.params = params
        self.rep_seeds = representative_seeds
        self.path_suffix = path_suffix

        self.save_dir = save_dir
        os.makedirs(self.save_dir, exist_ok=True)
        os.makedirs(self.path_suffix, exist_ok=True)

        self.data = initial_data_full
        self.br = br_data
        self.mac = macro_df
        self.n_assets = len(tickers)
        self.trial=trial

    # ------------------------------------------------------------
    # Train final model for one seed
    # ------------------------------------------------------------
    def _train_final(self, seed):
        _clear_session()
        _set_seed(seed)

        self.params["seed"] = seed

        df_trainval = self.data[self.data.index < unix_threshold_full]
        br_trainval = self.br.loc[df_trainval.index]
        mac_trainval = self.mac.loc[df_trainval.index]

        # Prepare features
        x, x_on, x_mac, y, y_r, vol, \
        r1, r3, r7, r10, r13, r17, r24 = prepare_features_from_wide_df2(
            df=df_trainval,
            btc_chain_df=br_trainval,
            macro_df=mac_trainval,
            standardisation_type=self.params["standardisation"],
            training=True,
            path_suffix=self.path_suffix,
            selected_cols=selected_cols,
            selected_regime_cols=selected_regime_cols,
            selected_macro_cols=selected_macro_cols,
            #fwcv=True,
            standardisation_type_volume=self.params["standardisation_type_volume"] if "standardisation_type_volume" in self.params.keys() else self.params["standardisation"]
        )

        window = self.params["window"]
        #self.params["window"] = 60
        batch = self.params["computing_batch"]
        epochs = 20 #self.params["num_epochs"]

        (
            x, x_on, x_mac, y_r,
            y_shift, y_mkt_shift,
            x_w, y_w, y_mkt_w, vol_w
        ) = _prepare_arrays(x, x_on, x_mac, y, y_r, vol, window)

        hq = compute_horizon_quality([r1,
                                      r3,
                                      r7,
                                      r10,
                                      r13,
                                      r17,
                                     r24], exposures_list=None#, window=window
                                    )

        model = build_cross_sectional_mixer_lstm2(
            **_model_kwargs(
                self.params,
                n_features=x.shape[-1],
                n_onchain_features=x_on.shape[-1],
                n_macro_features=x_mac.shape[-1],
                n_assets=self.n_assets,
                n_vol_features=vol_w.shape[-1],
            )
        )

        train_ds = make_dataset(
            _build_inputs_dict(x, x_on, x_mac, y_shift, y_mkt_shift, x_w, y_w, y_mkt_w, vol_w),
            {
                "exposures": y_r[-x.shape[0]:],
                "exposures_h1": r1[-x.shape[0]:],
                "exposures_h3": r3[-x.shape[0]:],
                "exposures_h7": r7[-x.shape[0]:],
                "exposures_h10": r10[-x.shape[0]:],
                "exposures_h13": r13[-x.shape[0]:],
                "exposures_h17": r17[-x.shape[0]:],
                "exposures_h24": r24[-x.shape[0]:],
                "blend_weights_target": hq[-x.shape[0]:],
            },
            batch_size=batch,
            shuffle=False,
        )

        cbs, warmup_epochs = _build_callbacks(
            params=self.params,
            n_train_samples=x.shape[0],
            num_epochs=epochs,
            model=model,
            use_early_stopping=False,
        )

        model.fit(train_ds, epochs=epochs, callbacks=cbs, verbose=1)


        # Get exposures on train+val
        preds = model.predict(
            {
                "asset_features": x,
                "regime_onchain": x_on,
                "regime_macro": x_mac,
                "lagged_absolute_returns": y_shift,
                "lagged_market_returns": y_mkt_shift,
                "x_window": x_w,
                "y_market_rel_window": y_mkt_w,
                "vol": vol_w,
            },
            verbose=0,
        )


        cbs2, warmup_epochs = _build_callbacks(
            params=self.params,
            n_train_samples=x.shape[0],
            num_epochs=epochs//2,
            model=model,
            use_early_stopping=False,
        )

        exposures_list = [preds["exposures_h1"][-x.shape[0]:],
                          preds["exposures_h3"][-x.shape[0]:],
                          preds["exposures_h7"][-x.shape[0]:],
                          preds["exposures_h10"][-x.shape[0]:],
                          preds["exposures_h13"][-x.shape[0]:],
                          preds["exposures_h17"][-x.shape[0]:],
                          preds["exposures_h24"][-x.shape[0]:]]

        hq2 = compute_horizon_quality([r1[-x.shape[0]:],
                                       r3[-x.shape[0]:],
                                       r7[-x.shape[0]:],
                                       r10[-x.shape[0]:],
                                       r13[-x.shape[0]:],
                                       r17[-x.shape[0]:],
                                       r24[-x.shape[0]:]], exposures_list=exposures_list, #window=window
                                     )

        print("hq2 shape", hq2.shape, "r1 shape", r1.shape)

        train_ds2 = make_dataset(
            _build_inputs_dict(x, x_on, x_mac, y_shift, y_mkt_shift, x_w, y_w, y_mkt_w, vol_w),
            {
                "exposures": y_r[-x.shape[0]:],
                "exposures_h1": r1[-x.shape[0]:],
                "exposures_h3": r3[-x.shape[0]:],
                "exposures_h7": r7[-x.shape[0]:],
                "exposures_h10": r10[-x.shape[0]:],
                "exposures_h13": r13[-x.shape[0]:],
                "exposures_h17": r17[-x.shape[0]:],
                "exposures_h24": r24[-x.shape[0]:],
                "blend_weights_target": hq2[-x.shape[0]:],   # ← NEW TARGET
            },
            batch_size=batch,
            shuffle=False,
        )

        model.fit(train_ds2, epochs=epochs//2, callbacks=cbs2, verbose=1)


        # ---- Persist ----
        timestamp = datetime.now().strftime("%d_%m_%Y_%H_%M_%S")
        keras_path = os.path.join(
            self.save_dir, f"trial{self.trial}_seed{seed}_{timestamp}.keras"
        )
        meta_path = keras_path.replace(".keras", ".meta")

        model.save(keras_path)

        with open(meta_path, "w") as fh:
            fh.write(f"trial:   {self.trial}\n")
            fh.write(f"seed:    {seed}\n")
            fh.write(f"params:  {self.params}\n")
            fh.write(
                f"columns: "
                f"{list(self.data.columns) + list(self.br.columns) + list(self.mac.columns)}\n"  # ← NEW
            )

        print(f"SAVED MODEL FOR TRIAL {self.trial} AND SEED {seed} at {keras_path}")
        del x, x_on, x_mac, y, y_r, vol, r1, r3, r7, r10, r13, r17, r24, hq, hq2
        _clear_session()

        return model

    @staticmethod
    def ensemble_predict(models, inputs):
        preds = [m.predict(inputs)["exposures"] for m in models]
        return np.mean(np.stack(preds, axis=0), axis=0)

    def build(self):
        models = [self._train_final(seed) for seed in self.rep_seeds]
        return models


