    def plot_asset_allocation(self, save_path=None, figsize=None, max_scale=None):
        """
        Plot asset allocation heatmap over time.
        Blue = long, Red = short, White = zero/flat.

        Args:
            save_path: Optional path to save the figure
            figsize: Optional (width, height) tuple. Auto-sized if None.
            max_scale: Color scale max absolute value. Auto-detected if None.
        """
        if not hasattr(self, 'results'):
            raise RuntimeError("Run evaluate() first")

        predictions = self.results['predictions']  # (n_timesteps, n_assets)
        dates = self.results['dates']
        n_t, n_a = predictions.shape

        # Auto-size: wide enough to see ~1px per timestep
        if figsize is None:
            w = max(20, n_t / 35)
            h = max(8, n_a * 0.35)
            figsize = (w, h)

        fig, ax = plt.subplots(figsize=figsize)

        # Diverging colormap: red=short, white=zero, blue=long
        cmap = plt.cm.RdBu  # Red-White-Blue, negative=red, positive=blue

        if max_scale is None:
            max_scale = np.percentile(np.abs(predictions[predictions != 0]), 95) if np.any(predictions != 0) else 1.0
            max_scale = max(max_scale, 1e-6)

        # predictions transposed → rows=assets, cols=timesteps (standard heatmap orientation)
        im = ax.imshow(
            predictions.T,
            aspect='auto',
            cmap=cmap,
            vmin=-max_scale,
            vmax=max_scale,
            interpolation='nearest',
            origin='upper'
        )

        # Colorbar
        cbar = fig.colorbar(im, ax=ax, fraction=0.02, pad=0.01)
        cbar.set_label('Position size (- short / + long)', fontsize=9)
        cbar.ax.tick_params(labelsize=8)

        # Y-axis: asset labels
        ax.set_yticks(np.arange(n_a))
        ax.set_yticklabels(self.tickers, fontsize=7)
        ax.tick_params(axis='y', length=0)

        # X-axis: date ticks (sample ~8–12 evenly spaced dates)
        n_ticks = min(12, n_t)
        tick_indices = np.linspace(0, n_t - 1, n_ticks, dtype=int)
        ax.set_xticks(tick_indices)
        if hasattr(dates, '__getitem__'):
            tick_labels = [str(dates[i])[:10] for i in tick_indices]
        else:
            tick_labels = [str(i) for i in tick_indices]
        ax.set_xticklabels(tick_labels, rotation=45, ha='right', fontsize=7)

        # Thin horizontal grid lines to separate assets
        for y in np.arange(n_a) - 0.5:
            ax.axhline(y, color='white', linewidth=0.3, alpha=0.4)

        ax.set_title(
            f'Asset allocation heatmap  ·  {n_t} timesteps  ·  {n_a} assets  '
            f'·  {self.ensemble_method} ensemble',
            fontsize=11, pad=10
        )
        ax.set_xlabel('Time', fontsize=9)
        ax.set_ylabel('Asset', fontsize=9)

        plt.tight_layout()

        if save_path:
            plt.savefig(save_path, dpi=150, bbox_inches='tight')
            print(f"Asset allocation heatmap saved to {save_path}")

        plt.show()
        return fig

