    def _extract_params_from_meta(self, model_path: str) -> dict:
        """Extract parameters from .meta file for a model."""
        meta_path = model_path.replace(".keras", ".meta")
        params = {}
        try:
            with open(meta_path, 'r') as f:
                for line in f:
                    if line.startswith("params:"):
                        import ast
                        params = ast.literal_eval(line.split("params:")[1].strip())
                        break
        except Exception as e:
            print(f"Warning: Could not read meta file {meta_path}: {e}")
        return params

    def prepare_oos_data_for_window(self, window: int, standardisation: str):
        """Prepare OOS data for a specific window size."""
        print(f"\nPreparing OOS data for window={window}...")

        x, x_reg_onchain, x_reg_macro, y, y_m, vol, r1_train, r3_train, r7_train, r10_train, r13_train, r17_train, r24_train = prepare_features_from_wide_df2(
            df=self.oos_data,
            btc_chain_df=self.br_data_oos,
            macro_df=self.macro_oos,
            training=False,
            path_suffix=self.path_suffix,
            standardisation_type=standardisation,
            selected_cols=self.selected_cols,
            selected_regime_cols=self.selected_regime_cols,
            selected_macro_cols=self.selected_macro_cols,
            standardisation_type_volume=standardisation
        )

        (
            x, x_reg_onchain, x_reg_macro, y_r,
            y_shifted, y_shifted_market,
            x_w, y_shifted_w, y_shifted_market_w,
            vol_w
        ) = _prepare_arrays(x, x_reg_onchain, x_reg_macro, y, y_m, vol, window)

        oos_inputs = _build_inputs_dict(
            x, x_reg_onchain, x_reg_macro,
            y_shifted, y_shifted_market,
            x_w, y_shifted_w, y_shifted_market_w, vol_w
        )

        true_returns = y[-len(x):]
        dates = self.oos_data.index[-len(x):]

        self.oos_inputs = oos_inputs

        return oos_inputs, true_returns, dates

    def group_models_by_trial(self):
        """Group model paths by trial number and extract their parameters."""
        trial_groups = {}

        for path in self.model_paths:
            trial_num, seed_num = self._extract_trial_info(path)
            if trial_num is None:
                match = re.search(r'trial(\d+)', path)
                if match:
                    trial_num = int(match.group(1))
                else:
                    continue

            # Get parameters from meta file
            params = self._extract_params_from_meta(path)
            window = params.get('window', self.window)  # fallback to default window

            if trial_num not in trial_groups:
                trial_groups[trial_num] = {
                    'paths': [],
                    'window': window,  # Use first model's window (should be same for all seeds of same trial)
                    'params': params
                }
            trial_groups[trial_num]['paths'].append(path)

        return trial_groups

    def predict_hierarchical_ensemble(self):
        """
        Hierarchical ensemble:
        1. Within each trial: median across seeds (using trial's window)
        2. Across trials: median across trial-level predictions
        """
        if not self.models:
            self.load_models()

        # Group models by trial and get their window sizes
        trial_groups = self.group_models_by_trial()
        print(f"\n=== HIERARCHICAL ENSEMBLE ===")
        print(f"Found {len(trial_groups)} trials")

        for trial_num, info in trial_groups.items():
            print(f"  Trial {trial_num}: {len(info['paths'])} seeds, window={info['window']}")

        # Step 1: For each trial, prepare data with its window and get median across seeds
        trial_predictions = []

        for trial_num, info in trial_groups.items():
            window = info['window']
            paths = info['paths']

            print(f"\n  Processing Trial {trial_num} (window={window})...")

            # Prepare OOS data for this trial's window size
            oos_inputs, true_returns, dates = self.prepare_oos_data_for_window(window, info["params"]["standardisation"])

            # Load all models for this trial
            trial_models = []
            for path in paths:
                try:
                    model = keras.models.load_model(path)
                    trial_models.append(model)
                    print(f"    ✓ Loaded seed model")
                except Exception as e:
                    print(f"    ✗ Failed to load: {Path(path).name}: {e}")
                    continue

            if not trial_models:
                print(f"    No models loaded for trial {trial_num}")
                continue

            # Generate predictions from all seeds
            seed_preds = []
            for model in trial_models:
                try:
                    pred = model.predict(oos_inputs, verbose=0)
                    if isinstance(pred, dict):
                        pred = pred["exposures"]
                    seed_preds.append(pred)
                    trial_predictions.append(pred)
                except Exception as e:
                    print(f"    ✗ Prediction failed: {e}")
                    continue

            if seed_preds:
                # Take median across seeds for this trial
                if self.ensemble_seed_method == "mean":
                    trial_median = np.mean(np.stack(seed_preds), axis=0)
                elif self.ensemble_seed_method == "median":
                    trial_median = np.median(np.stack(seed_preds), axis=0)
                elif self.ensemble_seed_method == "min":
                    trial_median = np.min(np.stack(seed_preds), axis=0)
                elif self.ensemble_seed_method == "sum":
                    trial_median = np.sum(np.stack(seed_preds), axis=0)
                elif self.ensemble_seed_method == "min_abs":
                    # For each time step and asset, pick the prediction with minimum absolute value
                    # across all models
                    n_models, n_samples, n_assets = np.stack(seed_preds).shape

                    # Initialize array for ensemble predictions
                    trial_median = np.zeros((n_samples, n_assets))

                    # For each time step and asset, find the model with minimum absolute prediction
                    for t in range(n_samples):
                        for a in range(n_assets):
                            # Get predictions from all models for this time step and asset
                            model_preds = np.stack(seed_preds)[:, t, a]

                            # Find index of prediction with minimum absolute value
                            min_abs_idx = np.argmin(np.abs(model_preds))

                            # Select that prediction
                            trial_median[t, a] = model_preds[min_abs_idx]

                    print(f"  ✓ Applied 'min_abs' ensemble: picked least extreme prediction per position")
                #trial_median = np.median(np.stack(seed_preds), axis=0)
                #trial_predictions.append(trial_median)
                print(f"    ✓ Trial median shape: {trial_median.shape}")

        if not trial_predictions:
            raise RuntimeError("No trial predictions generated")

        # Step 2: Take median across trials
        min_length = min([len(tp) for tp in trial_predictions])
        trial_predictions = [tp[-min_length:] for tp in trial_predictions]

        if self.ensemble_method == "mean":
            hierarchical_ensemble = np.mean(np.stack(trial_predictions), axis=0)
        elif self.ensemble_method == "median":
            hierarchical_ensemble = np.median(np.stack(trial_predictions), axis=0)
        elif self.ensemble_method == "min":
            hierarchical_ensemble = np.min(np.stack(trial_predictions), axis=0)
        elif self.ensemble_method == "sum":
            hierarchical_ensemble = np.sum(np.stack(trial_predictions), axis=0)
        elif self.ensemble_method == "min_abs":
            # For each time step and asset, pick the prediction with minimum absolute value
            # across all models
            n_models, n_samples, n_assets = np.stack(trial_predictions).shape

            # Initialize array for ensemble predictions
            hierarchical_ensemble = np.zeros((n_samples, n_assets))

            # For each time step and asset, find the model with minimum absolute prediction
            for t in range(n_samples):
                for a in range(n_assets):
                    # Get predictions from all models for this time step and asset
                    model_preds = np.stack(trial_predictions)[:, t, a]

                    # Find index of prediction with minimum absolute value
                    min_abs_idx = np.argmin(np.abs(model_preds))

                    # Select that prediction
                    hierarchical_ensemble[t, a] = model_preds[min_abs_idx]

        #hierarchical_ensemble = np.median(np.stack(trial_predictions), axis=0)

        # Apply threshold and leverage
        if self.top_k_coins>0:

            print(f"HIERARCHICAL: TOP {self.top_k_coins} LONG/SHORT")

            sorted_idx = np.argsort(hierarchical_ensemble, axis=1)

            # Top 3 long (largest positive)
            top_long = sorted_idx[:, -self.top_k_coins:]

            # Top 3 short (most negative)
            top_short = sorted_idx[:, :self.top_k_coins]

            print(f"TOP LONG: {top_long}")

            # Create zeroed matrix
            sparse_preds = np.zeros_like(hierarchical_ensemble)

            # Fill in only the selected positions
            for t in range(hierarchical_ensemble.shape[0]):
                sparse_preds[t, top_long[t]] = hierarchical_ensemble[t, top_long[t]]
                sparse_preds[t, top_short[t]] = hierarchical_ensemble[t, top_short[t]]

            hierarchical_ensemble = sparse_preds

        elif self.size_threshold>0:
            hierarchical_ensemble[abs(hierarchical_ensemble) < self.size_threshold] = 0

        if self.dollar_neutral:
            w_long  = np.maximum(hierarchical_ensemble, 0.0)   # positive weights
            w_short = np.minimum(hierarchical_ensemble, 0.0)   # negative weights
            sum_long  = np.sum(w_long, axis=1, keepdims=True)          # (T, 1)
            sum_short = -np.sum(w_short, axis=1, keepdims=True)        # (T, 1), absolute
            target = np.minimum(sum_long, sum_short)  # (T, 1)
            eps = 1e-8
            scale_long  = target / (sum_long  + eps)
            scale_short = target / (sum_short + eps)
            w_long_bal  = w_long  * scale_long
            w_short_bal = w_short * scale_short
            hierarchical_ensemble  = w_long_bal + w_short_bal

        hierarchical_ensemble = hierarchical_ensemble * self.leverage

        # Store the true returns and dates from the first trial (they should be the same)
        # Or we can store the last trial's data
        self.true_returns = true_returns[-min_length:]
        self.dates = dates[-min_length:]
        self.ensemble_pred = hierarchical_ensemble

        print(f"\n✓ Hierarchical ensemble complete")
        print(f"  - Ensembled {len(trial_predictions)} trials")
        print(f"  - Final shape: {hierarchical_ensemble.shape}")

        return hierarchical_ensemble, trial_predictions


    def evaluate_hierarchical(self):
        """Run hierarchical ensemble evaluation."""
        # Generate hierarchical ensemble predictions
        ensemble_pred, trials_pred = self.predict_hierarchical_ensemble()

        # Calculate metrics
        metrics, portfolio_returns, cumulative, drawdown, long_ratio, long_pct, short_pct, net_exposure = \
            self.calculate_performance_metrics(ensemble_pred, self.true_returns)

        # Store results
        self.results = {
            'metrics': metrics,
            'predictions': ensemble_pred,
            'true_returns': self.true_returns,
            'portfolio_returns': portfolio_returns,
            'cumulative': cumulative,
            'drawdown': drawdown,
            'dates': self.dates,
            "individual_predictions": trials_pred,
            'long_ratio': long_ratio,
            'long_pct': long_pct,
            'short_pct': short_pct,
            'net_exposure': net_exposure
        }

        return self.results

    def debug_models(self, model_index=0, max_layers=60):
        """
        Print full model summary (with layer config) + plot activations + gradients.
        """

        import tensorflow as tf
        from tensorflow import keras
        import matplotlib.pyplot as plt

        if not self.models:
            raise RuntimeError("Call load_models() first")

        model = self.models[model_index]
        print("\n" + "="*80)
        print(f"MODEL {model_index} — {model.name}")
        print("="*80)

        # -------------------------------------------------------------------------
        # 1. PRINT FULL MODEL SUMMARY WITH CONFIG
        # -------------------------------------------------------------------------
        print("\n=== MODEL SUMMARY WITH CONFIG ===\n")

        for i, layer in enumerate(model.layers):
            cfg = layer.get_config()
            print(f"Layer {i}: {layer.name}")
            print(f"  Class: {layer.__class__.__name__}")

            # Print input/output shapes
            try:
                print(f"  Input shape: {layer.input_shape}")
            except:
                pass
            try:
                print(f"  Output shape: {layer.output_shape}")
            except:
                pass

            # Print key config fields
            for k, v in cfg.items():
                print(f"  {k}: {v}")

            print("-"*60)

        # -------------------------------------------------------------------------
        # 2. PREPARE INPUTS FOR ACTIVATION / GRADIENT DEBUGGING
        # -------------------------------------------------------------------------
        model_input_list = []
        for inp in model.inputs:
            clean_name = inp.name.split(":")[0]
            if clean_name not in self.oos_inputs:
                raise RuntimeError(f"Missing input {clean_name} in oos_inputs")

            x = tf.convert_to_tensor(self.oos_inputs[clean_name], dtype=tf.float32)
            x = x[:1]  # first batch element
            model_input_list.append(x)

        # -------------------------------------------------------------------------
        # 3. BUILD ACTIVATION MODEL
        # -------------------------------------------------------------------------
        valid_layers = []
        layer_outputs = []

        for layer in model.layers:
            try:
                if "input" in str(layer.__class__.__name__).lower():
                    continue
                layer_outputs.append(layer.output)
                valid_layers.append(layer)
            except:
                pass

        act_model = keras.Model(inputs=model.inputs, outputs=layer_outputs)
        activations = act_model(model_input_list)

        if not isinstance(activations, (list, tuple)):
            activations = [activations]

        # -------------------------------------------------------------------------
        # 4. PLOT ACTIVATIONS (all layers concatenated into one figure)
        # -------------------------------------------------------------------------
        print("\n=== ACTIVATIONS ===\n")

        layers_to_plot = list(zip(valid_layers[:max_layers], activations[:max_layers]))
        n_act = len(layers_to_plot)
        ncols = 4
        nrows = int(np.ceil(n_act / ncols))

        fig_act, axes_act = plt.subplots(nrows, ncols, figsize=(ncols * 4, nrows * 3))
        axes_act = np.array(axes_act).reshape(-1)  # flatten regardless of shape

        for i, (layer, act) in enumerate(layers_to_plot):
            act_np = act.numpy().flatten()
            ax = axes_act[i]
            ax.hist(act_np, bins=50, color='blue', alpha=0.7)
            ax.set_title(f"L{i}: {layer.name}", fontsize=8)
            ax.tick_params(labelsize=6)
            ax.grid(True, alpha=0.3)

            print(f"Layer {layer.name}: shape={act.shape}, "
                  f"min={act_np.min():.5f}, max={act_np.max():.5f}, mean={act_np.mean():.5f}")

        # hide unused axes
        for j in range(n_act, len(axes_act)):
            axes_act[j].axis('off')

        fig_act.suptitle("Activation Distributions per Layer", fontsize=14, fontweight='bold')
        fig_act.tight_layout(rect=[0, 0, 1, 0.97])

        act_save_path = self.model_paths[0].rsplit("/", 1)[0] + "/plot_activations.jpeg"
        fig_act.savefig(act_save_path, dpi=150, bbox_inches='tight')
        plt.show()
        print(f"Saved activations grid to {act_save_path}")

        # -------------------------------------------------------------------------
        # 5. COMPUTE GRADIENTS
        # -------------------------------------------------------------------------
        print("\n=== GRADIENTS ===\n")

        with tf.GradientTape() as tape:
            outputs = model(model_input_list)
            if isinstance(outputs, dict):
                main_out = outputs.get("exposures", list(outputs.values())[0])
            else:
                main_out = outputs
            loss = tf.reduce_mean(main_out)

        grads = tape.gradient(loss, model.trainable_variables)

        # -------------------------------------------------------------------------
        # 6. PLOT GRADIENTS (all variables concatenated into one figure)
        # -------------------------------------------------------------------------
        grad_pairs = [(var, g) for var, g in zip(model.trainable_variables, grads) if g is not None]
        none_vars = [var for var, g in zip(model.trainable_variables, grads) if g is None]
        for var in none_vars:
            print(f"Var {var.name}: grad=None")

        n_grad = len(grad_pairs)
        ncols_g = 4
        nrows_g = int(np.ceil(n_grad / ncols_g))

        fig_grad, axes_grad = plt.subplots(nrows_g, ncols_g, figsize=(ncols_g * 4, nrows_g * 3))
        axes_grad = np.array(axes_grad).reshape(-1)

        for i, (var, g) in enumerate(grad_pairs):
            g_np = g.numpy().flatten()
            ax = axes_grad[i]
            ax.hist(g_np, bins=50, color='red', alpha=0.7)
            ax.set_title(var.name, fontsize=7)
            ax.tick_params(labelsize=6)
            ax.grid(True, alpha=0.3)

            print(f"Var {var.name}: norm={tf.norm(g).numpy():.6f}, "
                  f"min={g_np.min():.5f}, max={g_np.max():.5f}, mean={g_np.mean():.5f}")

        for j in range(n_grad, len(axes_grad)):
            axes_grad[j].axis('off')

        fig_grad.suptitle("Gradient Distributions per Variable", fontsize=14, fontweight='bold')
        fig_grad.tight_layout(rect=[0, 0, 1, 0.97])

        grad_save_path = self.model_paths[0].rsplit("/", 1)[0] + "/plot_gradients.jpeg"
        fig_grad.savefig(grad_save_path, dpi=150, bbox_inches='tight')
        plt.show()
        print(f"Saved gradients grid to {grad_save_path}")


