def quick_ensemble_test(
         ensemble_dir: str,
         oos_data: pd.DataFrame,
         br_data_oos: pd.DataFrame,
         macro_oos: pd.DataFrame,
         tickers: list[str],
         selected_cols: list[str],
         selected_regime_cols: list[str],
         selected_macro_cols: list[str],
         path_suffix: str = "",
         criterion: str = "median",
         criterion_seed: str = "median",
         size_threshold: float = 0.0,
         leverage: int = 1,
         top_k_coins:int = 0,
         dollar_neutral:bool =False,

 ):
     """
     Run hierarchical ensemble test (median across seeds → median across trials).
     Each trial uses its own window parameter from its .meta file.
     """
     model_paths = glob.glob(f"{ensemble_dir}/*.keras", recursive=False)
     print(f"Found {len(model_paths)} models")

     # Need a dummy window value for initialization (will be overridden per trial)
     tester = EnsembleTester(
         model_paths=model_paths,
         oos_data=oos_data,
         br_data_oos=br_data_oos,
         macro_oos=macro_oos,
         tickers=tickers,
         selected_cols=selected_cols,
         selected_regime_cols=selected_regime_cols,
         selected_macro_cols=selected_macro_cols,
         path_suffix=path_suffix,
         ensemble_method=criterion,
         ensemble_seed_method=criterion_seed,
         size_threshold=size_threshold,
         leverage=leverage,
         top_k_coins=top_k_coins,
         dollar_neutral=dollar_neutral,

     )

     # Use hierarchical evaluation
     results = tester.evaluate_hierarchical()
     #for m, p in zip(tester.models, tester.model_paths):
     #   print(f"MODEL: {p}\n")
     #   print(f"{m.summary()}")

     #tester.debug_models()
     tester.print_summary()
     tester.plot_results(save_path=f"{ensemble_dir}/hierarchical_ensemble_performance.png")
     tester.plot_exposure_summary(save_path=f"{ensemble_dir}/hierarchical_exposure_analysis.png")
     tester.plot_asset_allocation(save_path=f"{ensemble_dir}/hierarchical_asset_allocation.png")
     return tester, results


